    pub(crate) fn original_groups_fixture_in_unit_with_sites(
        unit: &str,
        module: &str,
        groups: Vec<(u32, Vec<PendingImportOwner>)>,
        version: u8,
        packages: &BTreeMap<(String, String), PackageInterfaceWitness>,
        interface: Vec<u8>,
        sites: &BTreeMap<u32, Vec<tidepool_repr::execution_schema::SiteRow>>,
        literal: &[u8],
    ) -> crate::recovery_artifacts::CertifiedRecoveryProduct {
        let projected = groups
            .iter()
            .map(|(ordinal, imports)| {
                let mut wire = testing::wire_program();
                let tidepool_repr::execution_schema::Group::NonRecursive(top) =
                    &mut wire.bindings[0]
                else {
                    unreachable!()
                };
                top.identity = testing::identity(module, &format!("entry_{ordinal}"));
                // The one-group fixture retains its existing entry identity.
                if groups.len() == 1 && *ordinal == 7 {
                    top.identity = testing::identity(module, "entry");
                }
                top.identity.unit = unit.into();
                top.binding.rhs = tidepool_repr::execution_schema::HeapRhs::Bytes(literal.to_vec());
                let top = top.clone();
                wire.bindings = vec![tidepool_repr::execution_schema::Group::Recursive(vec![top])];
                wire.expressions.nodes.clear();
                wire.sites = sites.get(ordinal).cloned().unwrap_or_default();
                if !wire.sites.is_empty() {
                    wire.types = testing::closed_type_graph(
                        testing::identity("Fixture", "Completion"),
                        tidepool_repr::type_graph::DeclarationForm::Data,
                    );
                }
                wire.globals = imports
                    .iter()
                    .map(|import| {
                        let (identity, required_generation) = match import {
                            PendingImportOwner::Source { binder, .. }
                            | PendingImportOwner::Package { binder, .. } => (binder, None),
                            PendingImportOwner::Retained {
                                identity,
                                generation,
                            } => (identity, Some(*generation)),
                        };
                        GlobalDecl {
                            identity: identity.clone(),
                            rep: RuntimeRep::LiftedRef,
                            entry_signature: None,
                            required_evaluated: false,
                            required_generation,
                        }
                    })
                    .collect();
                testing::projected_group(wire, *ordinal).unwrap()
            })
            .collect();
        let product_bytes =
            tidepool_test_data::prepared_encode::encode_module_products(&[RawModuleProduct {
                unit: unit.into(),
                module: module.into(),
                interface: interface.clone(),
                groups: projected,
            }]);
        let owner = CachedHomeOwner {
            unit: unit.into(),
            module: module.into(),
            module_version: ModuleVersion([version; 32]),
            skinny_iface_sha256: sha(&interface),
            product_sha256: sha(&product_bytes),
        };
        let raw = parse_module_products(
            &product_bytes,
            &crate::prepared_artifact::production_requirements().unwrap(),
            crate::module_candidates::product_decode_limits(),
        )
        .unwrap()
        .pop()
        .unwrap();
        let groups = raw
            .groups
            .into_iter()
            .zip(groups)
            .map(|(group, (_, imports))| PendingCertifiedGroup {
                owner: owner.clone(),
                origin: ProductOrigin::Fresh,
                group: Arc::new(group),
                imports: imports.into(),
            })
            .collect::<Vec<_>>();
        let seal = encode_home_certification(&owner, &groups, packages).unwrap();
        let package_bytes = crate::module_candidates::tests::package_imports_with_roots(
            &owner.unit,
            &owner.module,
            &interface,
            Vec::new(),
        );
        crate::recovery_artifacts::CertifiedRecoveryProduct::from_certification(
            owner,
            interface,
            product_bytes,
            package_bytes,
            seal,
        )
    }

    pub(crate) fn recovered_witness_fixtures(
        products: &[crate::recovery_artifacts::CertifiedRecoveryProduct],
    ) -> Vec<CertifiedRecoveredOriginal> {
        let completed = products
            .iter()
            .map(|product| {
                let producer = product
                    .module_interface()
                    .expect("canonical fixture issuer")
                    .producer_sha256();
                let entry =
                    crate::artifact_inventory::ArtifactEntry::original(producer, product.clone())
                        .unwrap();
                let crate::artifact_inventory::ArtifactPayload::Original(completed) = entry.payload
                else {
                    unreachable!()
                };
                assert_eq!(completed.product_bytes(), product.product_bytes());
                assert_eq!(
                    completed.certification_bytes(),
                    product.certification_bytes()
                );
                completed
            })
            .collect::<Vec<_>>();
        let products = completed.as_slice();
        assert!(
            products
                .iter()
                .all(|product| product.module_interface().is_some()),
            "recovery fixtures require canonical finalized module interfaces",
        );
        let mut canonical_packages = BTreeMap::new();
        for product in products {
            let interface = product.module_interface().unwrap();
            if let Some(previous) = canonical_packages.insert(
                interface.interface_sha256(),
                interface.package_imports_bytes(),
            ) {
                assert_eq!(
                    previous,
                    interface.package_imports_bytes(),
                    "recovery fixtures sharing canonical interface bytes must share package sidecars",
                );
            }
        }
        let root = tempfile::tempdir().unwrap();
        let producer = products
            .first()
            .and_then(|product| product.module_interface())
            .map_or([1; 32], CertifiedModuleInterface::producer_sha256);
        let references = crate::recovery_artifacts::materialize_certified_products(
            root.path(),
            producer,
            products,
        )
        .unwrap();
        let verified = references
            .iter()
            .map(|reference| {
                crate::recovery_artifacts::verify_materialized_ref(root.path(), reference).unwrap()
            })
            .collect();
        certify_recovery_products_with_validation(
            verified,
            &mut PackageInterfaceValidation::default(),
        )
        .unwrap()
    }

    fn source_target_observations(
        sources: &[(&crate::recovery_artifacts::CertifiedRecoveryProduct, u32)],
    ) -> Vec<AcceptedGlobal> {
        sources
            .iter()
            .map(|(product, ordinal)| {
                let definitions = original_native_group_definitions(product, *ordinal).unwrap();
                let mut exports = definitions.export_contracts();
                let contract = exports.next().unwrap().unwrap();
                assert!(
                    exports.next().is_none(),
                    "source target fixture requires one exact export"
                );
                AcceptedGlobal {
                    identity: contract.identity.clone(),
                    rep: contract.rep,
                    entry_signature: contract.entry_signature.cloned(),
                    required_evaluated: contract.evaluated,
                    owner: ReceiptImportOwner::Source {
                        unit: product.owner().unit.clone(),
                        module: product.owner().module.clone(),
                        module_version: Some(product.owner().module_version.clone()),
                        original_ordinal: *ordinal,
                        binder: contract.identity.clone(),
                    },
                }
            })
            .collect()
    }

    // This fixture constructs validated syntax, not target admission or grants.
    fn prepared_target_fixture(observations: &[AcceptedGlobal]) -> Arc<PreparedProgram> {
        let mut wire = testing::wire_program();
        wire.globals = observations
            .iter()
            .map(|observation| {
                let entry_signature = observation.entry_signature.as_ref().map(|signature| {
                    let id = tidepool_repr::execution_schema::SignatureId(
                        u32::try_from(wire.signatures.len()).unwrap(),
                    );
                    wire.signatures.push(signature.clone());
                    id
                });
                GlobalDecl {
                    identity: observation.identity.clone(),
                    rep: observation.rep,
                    entry_signature,
                    required_evaluated: observation.required_evaluated,
                    required_generation: match &observation.owner {
                        ReceiptImportOwner::Retained { generation, .. } => Some(*generation),
                        _ => None,
                    },
                }
            })
            .collect();
        if !observations.is_empty() {
            wire.signatures[0].results = tidepool_repr::execution_schema::ResultContract::Returns(
                observations.iter().map(|row| row.rep).collect(),
            );
            wire.expressions.nodes[0] = tidepool_repr::execution_schema::ExprFrame::Return(
                (0..observations.len())
                    .map(|index| {
                        tidepool_repr::execution_schema::Atom::Ref(
                            tidepool_repr::execution_schema::ValueRef::Global(
                                tidepool_repr::execution_schema::GlobalId(
                                    u32::try_from(index).unwrap(),
                                ),
                            ),
                        )
                    })
                    .collect(),
            );
        }
        Arc::new(testing::prepare(wire).unwrap())
    }

