    #[derive(Clone, Debug)]
    enum SourcePromotionStep {
        Empty,
        Identity,
        Rekey(u8),
        Recover,
    }

    fn check_authenticated_source_promotion_history(
        sparse: &[(u32, bool)],
        history: &[SourcePromotionStep],
    ) {
        let cached = full_native_fixture(
            "PromotionCached",
            sparse
                .iter()
                .map(|(ordinal, _)| (*ordinal, vec![]))
                .collect(),
            7,
        );
        let fresh = full_native_fixture("PromotionFresh", vec![(3, vec![])], 9);
        let retained = full_native_fixture("PromotionRetained", vec![(3, vec![])], 0);
        let products = [cached];
        let selected = products[0]
            .original_native()
            .unwrap()
            .groups
            .iter()
            .filter(|group| {
                sparse.iter().any(|(ordinal, selected)| {
                    *selected && *ordinal == group.group.original_ordinal()
                })
            })
            .map(|group| {
                group
                    .admitted(products[0].original_native().unwrap())
                    .unwrap()
            })
            .collect::<Vec<_>>();
        let rows = |group: &PendingCertifiedGroup| {
            group
                .group
                .binders()
                .iter()
                .map(|binder| {
                    (
                        (
                            group.owner.clone(),
                            group.group.original_ordinal(),
                            binder.clone(),
                        ),
                        (group.owner.clone(), group.origin),
                    )
                })
                .collect::<Vec<_>>()
        };
        let base = products[0]
            .original_native()
            .unwrap()
            .groups
            .iter()
            .flat_map(|group| {
                rows(
                    &group
                        .admitted(products[0].original_native().unwrap())
                        .unwrap(),
                )
            })
            .collect::<Vec<_>>();
        let mut current = selected.iter().flat_map(rows).collect::<Vec<_>>();
        let mut fresh_group = fresh.original_native().unwrap().groups[0]
            .admitted(fresh.original_native().unwrap())
            .unwrap();
        fresh_group.origin = ProductOrigin::Fresh;
        current.extend(rows(&fresh_group));
        let mut retained_group = retained.original_native().unwrap().groups[0]
            .admitted(retained.original_native().unwrap())
            .unwrap();
        retained_group.origin = ProductOrigin::RetainedCore;
        current.extend(rows(&retained_group));
        let operation = InventoryOperation::new(Default::default());
        let original = AvailableOriginalSources::authenticate(&products, &operation).unwrap();
        let mut sources = original.overlay(&selected, &operation).unwrap();
        for (key, value) in current
            .iter()
            .filter(|(_, (_, origin))| *origin != ProductOrigin::Cached)
        {
            sources.insert(key.clone(), value.clone());
        }
        let check =
            |sources: &SourceGroupMap,
             current: &[(SourceGroupKey, (CachedHomeOwner, ProductOrigin))]| {
                // Recompute from immutable witnesses and current rows, independently
                // of the source map's incremental reindexing and fallback lookup.
                let expected = base
                    .iter()
                    .chain(current)
                    .cloned()
                    .collect::<BTreeMap<_, _>>();
                assert_eq!(
                    sources
                        .iter()
                        .map(|(key, value)| (key.clone(), value.clone()))
                        .collect::<BTreeMap<_, _>>(),
                    expected,
                    "history={history:?}"
                );
                assert_eq!(
                    sources.groups,
                    current.iter().cloned().collect::<BTreeMap<_, _>>(),
                    "selected/current overlay must keep its exact provenance; history={history:?}"
                );
                assert_eq!(
                    sources.original.as_ref().unwrap().sources.groups,
                    base.iter().cloned().collect::<BTreeMap<_, _>>(),
                    "promotion must not change authenticated availability; history={history:?}"
                );
                for (key, value) in &expected {
                    assert_eq!(sources.get(key), Some(value));
                    assert!(sources.contains_module(&key.0.unit, &key.0.module));
                    assert_eq!(
                        resolve_receipt_owner(
                            ReceiptImportOwner::Source {
                                unit: key.0.unit.clone(),
                                module: key.0.module.clone(),
                                module_version: Some(key.0.module_version.clone()),
                                original_ordinal: key.1,
                                binder: key.2.clone(),
                            },
                            sources,
                            &BTreeMap::new(),
                        )
                        .unwrap(),
                        PendingImportOwner::Source {
                            owner: value.0.clone(),
                            original_ordinal: key.1,
                            binder: key.2.clone(),
                        }
                    );
                }
            };
        check(&sources, &current);
        let mut counts = [0; 4];
        for step in history {
            let versions = match step {
                SourcePromotionStep::Empty => {
                    counts[0] += 1;
                    BTreeMap::new()
                }
                SourcePromotionStep::Identity => {
                    counts[1] += 1;
                    current
                        .iter()
                        .map(|(key, _)| (key.0.clone(), key.0.module_version.clone()))
                        .collect()
                }
                SourcePromotionStep::Rekey(version) => {
                    counts[2] += 1;
                    let old = current
                        .iter()
                        .find(|(_, (_, origin))| *origin == ProductOrigin::RetainedCore)
                        .map(|(key, _)| key.0.clone())
                        .expect("retained source row");
                    let version = ModuleVersion([*version; 32]);
                    let versions = BTreeMap::from([(old, version.clone())]);
                    for (key, (owner, origin)) in &mut current {
                        if *origin == ProductOrigin::RetainedCore {
                            key.0.module_version = version.clone();
                            owner.module_version = version.clone();
                        }
                    }
                    versions
                }
                SourcePromotionStep::Recover => {
                    counts[3] += 1;
                    let recovered = recovered_witness_fixtures(&products)
                        .into_iter()
                        .map(|row| row.product)
                        .collect::<Vec<_>>();
                    let recovered_original =
                        AvailableOriginalSources::authenticate(&recovered, &operation).unwrap();
                    sources = recovered_original.overlay(&selected, &operation).unwrap();
                    for (key, value) in current
                        .iter()
                        .filter(|(_, (_, origin))| *origin != ProductOrigin::Cached)
                    {
                        sources.insert(key.clone(), value.clone());
                    }
                    BTreeMap::new()
                }
            };
            sources
                .promote(&versions, &ValidatedPromotionSharing::default())
                .unwrap();
            check(&sources, &current);
        }
        eprintln!("source_promotion_history sparse_groups={} selected={} empty={} identity={} rekey={} recovery={}",
            sparse.len(), selected.len(), counts[0], counts[1], counts[2], counts[3]);
    }

    #[test]
    fn authenticated_selected_overlay_preserves_empty_and_identity_promotion_after_recovery() {
        check_authenticated_source_promotion_history(
            &[(0, true), (29, false), (u32::MAX, true)],
            &[
                SourcePromotionStep::Empty,
                SourcePromotionStep::Identity,
                SourcePromotionStep::Recover,
                SourcePromotionStep::Identity,
            ],
        );
    }

    #[test]
    fn authenticated_sparse_overlay_promotes_retained_and_preserves_cached_and_fresh_rows() {
        check_authenticated_source_promotion_history(
            &[(0, false), (3, true), (11, false), (u32::MAX, true)],
            &[
                SourcePromotionStep::Rekey(5),
                SourcePromotionStep::Empty,
                SourcePromotionStep::Rekey(5),
                SourcePromotionStep::Recover,
                SourcePromotionStep::Rekey(2),
                SourcePromotionStep::Identity,
            ],
        );
    }

    proptest::proptest! {
        #![proptest_config(original_native_index_property_config())]
        #[test]
        fn original_native_index_matches_linear_scan_for_generated_sparse_groups(
            groups in proptest::collection::vec((proptest::prelude::any::<u32>(),
                proptest::prelude::any::<bool>(), proptest::prelude::any::<bool>()), 0..48),
            query in proptest::prelude::any::<u32>(),
        ) {
            let mut seen = BTreeSet::new();
            let groups = groups.into_iter().filter(|(ordinal, _, _)| seen.insert(*ordinal)).collect::<Vec<_>>();
            check_original_native_index_against_linear_scan(&groups, query);
        }
        #[test]
        fn authenticated_source_promotion_histories_match_recomputed_membership(
            sparse in proptest::collection::vec((proptest::prelude::any::<u32>(), proptest::prelude::any::<bool>()), 1..24),
            history in proptest::collection::vec((0u8..4, 1u8..6), 0..32),
        ) {
            let mut seen = BTreeSet::new();
            let sparse = sparse.into_iter().filter(|(ordinal, _)| seen.insert(*ordinal)).collect::<Vec<_>>();
            let mut steps = vec![SourcePromotionStep::Empty, SourcePromotionStep::Rekey(1),
                SourcePromotionStep::Identity, SourcePromotionStep::Recover];
            steps.extend(history.into_iter().map(|(operation, version)| match operation {
                0 => SourcePromotionStep::Empty,
                1 => SourcePromotionStep::Identity,
                2 => SourcePromotionStep::Rekey(version),
                _ => SourcePromotionStep::Recover,
            }));
            check_authenticated_source_promotion_history(&sparse, &steps);
        }
        #[test]
        fn retained_original_membership_matches_raw_prefix_overlays(
            ordinals in proptest::collection::vec(proptest::prelude::any::<u32>(), 1..24),
            prefixes in proptest::collection::vec(0usize..24, 1..24),
        ) {
            let mut seen = BTreeSet::new();
            let ordinals = ordinals.into_iter().filter(|ordinal| seen.insert(*ordinal)).collect::<Vec<_>>();
            let products = [7, 9].map(|version| full_native_fixture("MembershipHistory",
                ordinals.iter().map(|ordinal| (*ordinal, vec![])).collect(), version));
            assert_ne!(products[0].owner(), products[1].owner());
            let inventory = crate::artifact_inventory::ArtifactInventory::default();
            let mut basis_view = inventory.empty_view();
            for product in &products {
                let entry = Arc::new(crate::artifact_inventory::ArtifactEntry::original(
                    product.module_interface().unwrap().producer_sha256(), product.clone(),
                ).unwrap());
                let sibling = inventory.admit_recovery_selection(
                    &inventory.empty_view(), vec![entry], &BTreeSet::new(),
                ).unwrap();
                basis_view = basis_view.retain_custody(&sibling).unwrap();
            }
            let metadata = crate::artifact_inventory::CompilerInputProjection::default()
                .project_metadata(basis_view.metadata_snapshot()).unwrap();
            let basis = metadata.original_source_membership_basis();
            let retained = RetainedOriginalSources::default();
            let operation = Arc::new(InventoryOperation::new(Default::default()));
            let original = retained.admit(&basis, &products, &operation).unwrap();
            let expected = products.iter().flat_map(|product| ordinals.iter().map(move |ordinal| (
                product.owner().clone(), *ordinal,
                testing::identity("MembershipHistory", &format!("entry_{ordinal}")),
            ))).collect::<BTreeSet<_>>();
            let mut overlay_calls = 0;
            for (index, prefix) in prefixes.into_iter().enumerate() {
                let count = prefix % (ordinals.len() + 1);
                let product = &products[index % products.len()];
                let selected = product.original_native().unwrap().groups[..count].iter()
                    .map(|group| group.admitted(product.original_native().unwrap()).unwrap()).collect::<Vec<_>>();
                let membership = retained.admit(&basis, &products, &operation).unwrap();
                assert!(Arc::ptr_eq(&original, &membership));
                let overlay = membership.overlay(&selected, &operation).unwrap();
                assert_eq!(overlay.groups.len(), count);
                assert_eq!(overlay.iter().map(|(key, _)| key.clone()).collect::<BTreeSet<_>>(), expected,
                    "selected prefix overlay cannot omit or add full available membership");
                if let Some(group) = selected.first() {
                    let mut foreign = group.clone();
                    foreign.owner.unit = "foreign".into();
                    assert!(membership.overlay(&[foreign], &operation).is_err());
                    assert!(membership.overlay(&[group.clone(), group.clone()], &operation).is_err());
                }
                assert!(matches!(retained.admit(&basis, &products[..1], &operation),
                    Err(CertificationError::OriginalMembership(reason))
                        if *reason == OriginalMembershipFailure::MissingOwner(products[1].owner().clone())));
                overlay_calls += 1;
            }
            let fresh = Arc::new(InventoryOperation::new(Default::default()));
            let recovered = recovered_witness_fixtures(&products).into_iter().map(|row| row.product).collect::<Vec<_>>();
            let next = retained.admit(&basis, &recovered, &fresh).unwrap();
            assert!(!Arc::ptr_eq(&original, &next));
            assert_eq!(next.sources.iter().map(|(key, _)| key.clone()).collect::<BTreeSet<_>>(), expected);
            let weak = Arc::downgrade(&next);
            drop(next);
            drop(retained);
            assert!(weak.upgrade().is_none());
            eprintln!("original_membership_history owners=2 groups={} overlay_calls={overlay_calls} recovered=2", ordinals.len());
        }
    }

    #[test]
    fn selected_group_validation_keeps_exact_bindings_across_equal_owner_custody() {
        use crate::artifact_inventory::{ArtifactEntry, ArtifactInventory, ArtifactPayload};
        let product = full_native_fixture("SelectedScopeIdentity", vec![(7, vec![])], 1);
        let producer = product.module_interface().unwrap().producer_sha256();
        let original = Arc::new(ArtifactEntry::original(producer, product.clone()).unwrap());
        let alternate = Arc::new(
            ArtifactEntry::original([3; 32], fixture_finalized_product(product.clone(), [3; 32]))
                .unwrap(),
        );
        let ArtifactPayload::Original(alternate_product) = &alternate.payload else {
            unreachable!()
        };
        assert_eq!(product.owner(), alternate_product.owner());
        assert_ne!(original.descriptor.id, alternate.descriptor.id);
        let inventory = ArtifactInventory::default();
        let selected = inventory
            .admit_shared(&inventory.empty_view(), vec![original.clone()])
            .unwrap();
        let foreign = inventory
            .admit_shared(&inventory.empty_view(), vec![alternate.clone()])
            .unwrap();
        let broad = selected.retain_custody(&foreign).unwrap();
        let metadata = broad.metadata_snapshot();
        let available = metadata
            .artifacts
            .iter()
            .filter_map(|(id, entry)| match &entry.payload {
                ArtifactPayload::Original(product) => Some((*id, product)),
                _ => None,
            })
            .collect();
        let mut validation = PackageInterfaceValidation::default();
        let mut checked =
            OriginalValidationInventory::selected(&available, &validation.inventory).unwrap();
        let rows = checked
            .certify_selected_scope(
                SelectedOriginalGroupScope::View(&broad),
                &BTreeMap::new(),
                &mut validation,
            )
            .unwrap()
            .rows;
        assert_eq!(rows.len(), 1);
        let (binding, selected_row) = rows.first_key_value().unwrap();
        let row = selected_row.product().as_ref();
        assert_eq!(binding.binding.artifact(), original.descriptor.id);
        assert_eq!(binding.original_ordinal, 7);
        let current = BTreeMap::from([(*binding, row)]);
        let repeated = checked
            .certify_selected_scope(
                SelectedOriginalGroupScope::View(&broad),
                &current,
                &mut validation,
            )
            .unwrap()
            .rows;
        assert_eq!(
            repeated.keys().collect::<Vec<_>>(),
            rows.keys().collect::<Vec<_>>()
        );
        for (binding, repeated_row) in &repeated {
            assert!(repeated_row.product().same_issuance(current[binding]));
        }
        assert!(matches!(
            checked.certify_selected_scope(
                SelectedOriginalGroupScope::View(&foreign),
                &current,
                &mut validation
            ),
            Err(CertificationError::Mismatch(
                "current group outside selected binding closure"
            ))
        ));
        let mut wrong_owner = row.clone();
        wrong_owner.owner.unit = "foreign".into();
        assert!(matches!(
            checked.certify_selected_scope(
                SelectedOriginalGroupScope::View(&broad),
                &BTreeMap::from([(*binding, &wrong_owner)]),
                &mut validation
            ),
            Err(CertificationError::Mismatch("shared original home groups"))
        ));
        let mut changed = row.clone();
        changed.imports = vec![PendingImportOwner::Retained {
            identity: testing::identity("Captured", "different"),
            generation: 99,
        }]
        .into();
        assert!(matches!(
            checked.certify_selected_scope(
                SelectedOriginalGroupScope::View(&broad),
                &BTreeMap::from([(*binding, &changed)]),
                &mut validation
            ),
            Err(CertificationError::Mismatch("shared original home groups"))
        ));
        assert_eq!(
            broad.selected_native_groups(),
            selected.selected_native_groups()
        );
        assert_eq!(rows.first_key_value().unwrap().0, binding);
    }

    #[test]
    fn selected_source_edges_keep_the_exact_child_amid_equal_owner_custody() {
        use crate::artifact_inventory::{ArtifactEntry, ArtifactInventory, ArtifactPayload};
        let child = full_native_fixture("SelectedExactChild", vec![(7, vec![])], 1);
        let root = full_native_fixture(
            "SelectedExactRoot",
            vec![(
                11,
                vec![PendingImportOwner::Source {
                    owner: child.owner().clone(),
                    original_ordinal: 7,
                    binder: testing::identity("SelectedExactChild", "entry"),
                }],
            )],
            1,
        );
        let producer = child.module_interface().unwrap().producer_sha256();
        let child_entry = Arc::new(ArtifactEntry::original(producer, child.clone()).unwrap());
        let root_entry = Arc::new(ArtifactEntry::original(producer, root).unwrap());
        let other_entry = Arc::new(
            ArtifactEntry::original([3; 32], fixture_finalized_product(child, [3; 32])).unwrap(),
        );
        let inventory = ArtifactInventory::default();
        let selected = inventory
            .admit_shared(
                &inventory.empty_view(),
                vec![child_entry.clone(), root_entry.clone()],
            )
            .unwrap();
        let other = inventory
            .admit_shared(&inventory.empty_view(), vec![other_entry.clone()])
            .unwrap();
        let broad = selected.retain_custody(&other).unwrap();
        let metadata = broad.metadata_snapshot();
        let available = metadata
            .artifacts
            .iter()
            .filter_map(|(id, entry)| match &entry.payload {
                ArtifactPayload::Original(product) => Some((*id, product)),
                _ => None,
            })
            .collect();
        let mut validation = PackageInterfaceValidation::default();
        let mut checker =
            OriginalValidationInventory::selected(&available, &validation.inventory).unwrap();
        let rows = checker
            .certify_selected_scope(
                SelectedOriginalGroupScope::View(&broad),
                &BTreeMap::new(),
                &mut validation,
            )
            .unwrap()
            .rows;
        assert_eq!(rows.len(), 2);
        let root_binding = *rows
            .iter()
            .find(|(binding, _)| binding.binding.artifact() == root_entry.descriptor.id)
            .unwrap()
            .0;
        let child_binding = *rows
            .iter()
            .find(|(binding, _)| binding.binding.artifact() == child_entry.descriptor.id)
            .unwrap()
            .0;
        assert_eq!(
            broad
                .original_group_children(root_binding, &validation.inventory)
                .unwrap(),
            vec![child_binding]
        );
        assert!(rows
            .iter()
            .all(|(binding, _)| binding.binding.artifact() != other_entry.descriptor.id));
        let baseline = rows
            .iter()
            .map(|(binding, row)| (*binding, row.product().as_ref()))
            .collect();
        let repeated = checker
            .certify_selected_scope(
                SelectedOriginalGroupScope::View(&broad),
                &baseline,
                &mut validation,
            )
            .unwrap()
            .rows;
        assert_eq!(
            repeated.keys().collect::<Vec<_>>(),
            rows.keys().collect::<Vec<_>>()
        );
        for (binding, repeated_row) in &repeated {
            assert!(repeated_row.product().same_issuance(baseline[binding]));
        }
        let wrong = other
            .original_group_bindings(&validation.inventory)
            .unwrap()[0];
        let mut substituted = baseline;
        let child_row = substituted.remove(&child_binding).unwrap();
        substituted.insert(wrong, child_row);
        assert!(matches!(
            checker.certify_selected_scope(
                SelectedOriginalGroupScope::View(&broad),
                &substituted,
                &mut validation
            ),
            Err(CertificationError::Mismatch(
                "current group outside selected binding closure"
            ))
        ));
    }

    #[test]
    fn original_binding_receipts_require_selected_pair_symbol_and_permission() {
        use crate::artifact_inventory::{
            ArtifactEntry, ArtifactInventory, CompilerInputProjection, CompilerSourceSupport,
            NativeGroupKey,
        };
        use crate::declaration_context::{
            ExactCompileContext, ExactDeclarationContext, OriginalCompilerInputs,
        };
        use crate::declaration_join::ExactLexicalNode;
        let producer = crate::artifact_inventory::CanonicalProducerIdentity::from_producer_bytes(
            b"original-binding-test",
        )
        .sha256();
        let product = fixture_finalized_product(
            full_native_fixture("BoundOriginal", vec![(7, vec![]), (11, vec![])], 1),
            producer,
        );
        let entry = Arc::new(ArtifactEntry::original(producer, product.clone()).unwrap());
        let other_product = fixture_finalized_product(
            full_native_fixture("OtherSelected", vec![(7, vec![])], 2),
            producer,
        );
        let other_entry = Arc::new(ArtifactEntry::original(producer, other_product).unwrap());
        let projection =
            CompilerInputProjection::from_issued_entries(&[entry.clone(), other_entry.clone()])
                .unwrap();
        let inventory = ArtifactInventory::default();
        let physical = inventory
            .admit_shared(
                &inventory.empty_view(),
                vec![entry.clone(), other_entry.clone()],
            )
            .unwrap();
        let operation = Arc::new(InventoryOperation::new(Default::default()));
        let mut selected = CertifiedSourceSelection::from_compiler_projection(
            &projection,
            &physical.metadata_snapshot(),
            &operation,
        )
        .unwrap();
        let output = OriginalCompilerInputs::issue_segment_native_availability(
            &mut selected,
            &physical,
            vec![entry.clone(), other_entry.clone()],
            &mut crate::recovery_artifacts::PackageInterfaceValidation::default(),
        )
        .unwrap();
        let completed = Arc::new(CompilerSourceSupport::close_complete_output(&output).unwrap());
        let owner = entry.descriptor.owner.clone();
        let primary = completed.compiler_primary_input(&owner).unwrap().unwrap();
        let interface = primary.interface();
        let original = primary.original().unwrap();
        let binder = testing::identity("BoundOriginal", "entry_7");
        let resolve = |source: &Arc<CompilerSourceSupport>,
                       owner: &crate::declaration_join::ExactModuleIdentity,
                       interface,
                       original,
                       binder: &SymbolIdentity,
                       operation: &Arc<InventoryOperation>| {
            let reference = ReceiptImportOwner::OriginalBinding {
                unit: owner.unit.clone(),
                module: owner.module.clone(),
                interface,
                original,
                binder: binder.clone(),
            };
            ResolvedOriginalBindings::issue(Arc::clone(source), Arc::clone(operation), [&reference])
                .map(|resolved| resolved.get(&reference).unwrap().clone())
        };
        assert_eq!(
            resolve(&completed, &owner, interface, original, &binder, &operation).unwrap(),
            (product.owner().clone(), 7)
        );

        // A genuine different artifact for the same owner cannot replace the selected pair.
        let alternate = Arc::new(
            ArtifactEntry::original([3; 32], fixture_finalized_product(product.clone(), [3; 32]))
                .unwrap(),
        );
        let alternate_view = inventory
            .admit_shared(&inventory.empty_view(), vec![alternate.clone()])
            .unwrap();
        let alternate_pair = *alternate_view
            .capture_graph_selection()
            .namespace
            .iter()
            .find(|binding| binding.artifact == alternate.descriptor.id)
            .unwrap();
        assert_ne!(original, alternate_pair);
        assert!(matches!(
            resolve(
                &completed,
                &owner,
                interface,
                alternate_pair,
                &binder,
                &operation
            ),
            Err(CertificationError::InputDecision {
                reason: InputDecisionRefusal::ArtifactIdentityMismatch,
                ..
            })
        ));
        let foreign_owner = crate::declaration_join::ExactModuleIdentity {
            unit: owner.unit.clone(),
            module: "Other".into(),
        };
        assert!(matches!(
            resolve(
                &completed,
                &foreign_owner,
                interface,
                original,
                &binder,
                &operation
            ),
            Err(CertificationError::InputDecision {
                reason: InputDecisionRefusal::RoleMismatch,
                ..
            })
        ));
        assert!(matches!(
            resolve(
                &completed,
                &other_entry.descriptor.owner,
                interface,
                original,
                &binder,
                &operation
            ),
            Err(CertificationError::InputDecision {
                reason: InputDecisionRefusal::ArtifactIdentityMismatch,
                ..
            })
        ));
        let missing = testing::identity("BoundOriginal", "absent");
        assert!(matches!(resolve(&completed, &owner, interface, original,
                &missing, &operation), Err(CertificationError::OriginalMembership(reason))
                    if *reason == OriginalMembershipFailure::MissingSymbol { owner: product.owner().clone(), symbol: missing })
        );
        let custody = Arc::new(completed.for_source_owners(&BTreeSet::new()).unwrap());
        assert!(custody
            .artifacts()
            .metadata_snapshot()
            .artifacts
            .contains_key(&entry.descriptor.id));
        assert!(matches!(
            resolve(&custody, &owner, interface, original, &binder, &operation),
            Err(CertificationError::InputDecision {
                reason: InputDecisionRefusal::RoleMismatch,
                ..
            })
        ));

        // The production recovery/input issuer owns the bounded offer; membership alone
        // cannot expand ordinal 7 permission to another binder in the same artifact.
        let partial = inventory
            .admit_recovery_selection(
                &inventory.empty_view(),
                vec![entry.clone()],
                &BTreeSet::from([NativeGroupKey {
                    artifact: entry.descriptor.id,
                    original_ordinal: 7,
                }]),
            )
            .unwrap();
        let context = ExactDeclarationContext::from_authenticated_execution(
            producer,
            &partial,
            CompilerInputProjection::from_issued_entries(&[entry.clone()]).unwrap(),
            vec![ExactLexicalNode {
                owner: owner.clone(),
                imports: vec![],
            }],
            owner.clone(),
            &[],
        )
        .unwrap();
        let directory = tempfile::tempdir().unwrap();
        let request = ExactCompileContext::new(Arc::new(context))
            .prepare_compilation(directory.path(), b"original-binding-test")
            .unwrap();
        let source = request.compiler_inputs().compiler_source_support();
        let primary = source.compiler_primary_input(&owner).unwrap().unwrap();
        let interface = primary.interface();
        let original = primary.original().unwrap();
        let crate::artifact_inventory::ArtifactPayload::Original(product) = &primary.entry().payload
        else {
            unreachable!()
        };
        let source_selection =
            CertifiedSourceSelection::from_compiler_inputs(request.compiler_inputs(), &operation)
                .unwrap();
        assert!(matches!(
            source_selection.receipt_source_member(&owner.unit, &owner.module, None),
            Err(CertificationError::Mismatch(
                "missing cached source version"
            ))
        ));
        let wrong_version = ModuleVersion([0xff; 32]);
        assert_ne!(wrong_version, product.owner().module_version);
        assert!(matches!(
            source_selection.receipt_source_member(
                &owner.unit,
                &owner.module,
                Some(&wrong_version)
            ),
            Err(CertificationError::Mismatch("source module version"))
        ));
        assert_eq!(
            source_selection
                .receipt_source_member(
                    &owner.unit,
                    &owner.module,
                    Some(&product.owner().module_version)
                )
                .unwrap(),
            product.owner()
        );
        assert_eq!(
            source_selection
                .receipt_source_owner(
                    &owner.unit,
                    &owner.module,
                    Some(&product.owner().module_version),
                    7
                )
                .unwrap(),
            product.owner()
        );
        assert!(matches!(
            source_selection.receipt_source_owner(
                &owner.unit,
                &owner.module,
                Some(&product.owner().module_version),
                11
            ),
            Err(CertificationError::OriginalAvailability(_))
        ));
        let acquisition = request.compiler_inputs().shared_compiler_source_support();
        let references = [7, 11].map(|ordinal| ReceiptImportOwner::OriginalBinding {
            unit: owner.unit.clone(),
            module: owner.module.clone(),
            interface,
            original,
            binder: testing::identity("BoundOriginal", &format!("entry_{ordinal}")),
        });
        let resolved = ResolvedOriginalBindings::issue(
            Arc::clone(&acquisition),
            Arc::clone(&operation),
            [&references[0]],
        )
        .unwrap();
        let initial = OriginalBindingSelection::from_resolved(Arc::clone(&resolved));
        let before = operation.work_usage().unwrap();
        let repeated = initial
            .with_metadata([&references[0], &references[0]])
            .unwrap();
        assert_eq!(operation.work_usage().unwrap(), before);
        assert_eq!(
            repeated.executable(&references[0], &operation).unwrap(),
            initial.executable(&references[0], &operation).unwrap(),
        );
        let before = operation.work_usage().unwrap().0;
        let extended = initial.with_metadata([&references[1]]).unwrap();
        let only_new_work = operation.work_usage().unwrap().0 - before;
        assert!(only_new_work > 0);
        let before = operation.work_usage().unwrap().0;
        let mixed = initial
            .with_metadata([
                &references[0],
                &references[1],
                &references[0],
                &references[1],
            ])
            .unwrap();
        assert_eq!(operation.work_usage().unwrap().0 - before, only_new_work);
        assert_eq!(
            extended.metadata(&references[1]),
            Some(&(product.owner().clone(), 11))
        );
        assert_eq!(
            mixed.metadata(&references[0]),
            initial.metadata(&references[0])
        );
        assert_eq!(
            mixed.metadata(&references[1]),
            extended.metadata(&references[1])
        );
        assert_eq!(
            mixed.executable(&references[0], &operation).unwrap(),
            initial.executable(&references[0], &operation).unwrap()
        );
        assert!(mixed
            .executable(&references[1], &operation)
            .unwrap()
            .is_none());
        let granted = mixed
            .available_group(&references[0], &operation)
            .unwrap()
            .unwrap();
        assert_eq!(granted.binding().binding.artifact(), original.artifact);
        assert_eq!(granted.binding().original_ordinal, 7);
        assert_eq!(
            granted
                .contribution()
                .group_carrier_pair(granted.binding(), interface.artifact)
                .unwrap(),
            (original, interface)
        );
        assert!(mixed
            .available_group(&references[1], &operation)
            .unwrap()
            .is_none());
        assert!(mixed
            .available_group(&references[0], &InventoryOperation::new(Default::default()))
            .is_err());
        let before = operation.work_usage().unwrap();
        let unchanged = mixed.with_metadata(&references).unwrap();
        assert_eq!(operation.work_usage().unwrap(), before);
        assert_eq!(
            unchanged.metadata(&references[1]),
            extended.metadata(&references[1])
        );
        // Independent issuer scopes for equal payloads remain distinct metadata custody.
        let receiving_inventory = acquisition.artifacts().inventory();
        let receiving = receiving_inventory
            .admit_recovery_selection(
                &receiving_inventory.empty_view(),
                vec![entry.clone(), other_entry.clone()],
                &BTreeSet::from([NativeGroupKey {
                    artifact: entry.descriptor.id,
                    original_ordinal: 7,
                }]),
            )
            .unwrap();
        let before = receiving.capture_graph_selection();
        let receiving_binding = *before
            .namespace
            .iter()
            .find(|binding| binding.artifact == entry.descriptor.id)
            .unwrap();
        assert_ne!(receiving_binding, original);
        let retained = receiving
            .retain_original_binding_metadata(&mixed, &operation)
            .unwrap();
        let retained_graph = retained.capture_graph_selection();
        assert_eq!(retained_graph.namespace, before.namespace);
        assert_eq!(
            retained.selected_native_groups(),
            receiving.selected_native_groups()
        );
        assert!(retained_graph.bindings.contains(&original));
        assert!(retained_graph.bindings.contains(&receiving_binding));
        assert!(
            !retained.selected_native_groups().contains(&NativeGroupKey {
                artifact: entry.descriptor.id,
                original_ordinal: 11
            })
        );
        assert!(mixed
            .executable(&references[1], &operation)
            .unwrap()
            .is_none());
        let foreign_operation = InventoryOperation::new(Default::default());
        assert!(receiving
            .retain_original_binding_metadata(&mixed, &foreign_operation)
            .is_err());
        let cold = ArtifactInventory::default();
        let recovered = cold
            .recover_selection(
                &cold.empty_view(),
                retained.entries(),
                &retained_graph,
                &retained.binding_dependencies(),
            )
            .unwrap();
        assert_eq!(recovered.capture_graph_selection(), retained_graph);
        assert_eq!(
            recovered.selected_native_groups(),
            receiving.selected_native_groups()
        );
        let mut conflicting = references[0].clone();
        let ReceiptImportOwner::OriginalBinding {
            original: conflicting_original,
            ..
        } = &mut conflicting
        else {
            unreachable!()
        };
        *conflicting_original = alternate_pair;
        assert!(matches!(
            initial.with_metadata([&references[0], &conflicting]),
            Err(CertificationError::InputDecision {
                reason: InputDecisionRefusal::ArtifactIdentityMismatch,
                ..
            })
        ));
        let bindings = OriginalBindingSelection::issue(
            Arc::clone(&acquisition),
            Arc::clone(&operation),
            &references,
            Some(Arc::clone(&resolved)),
        )
        .unwrap();
        assert_eq!(
            bindings.metadata(&references[1]),
            Some(&(product.owner().clone(), 11))
        );
        assert!(bindings
            .executable(&references[1], &operation)
            .unwrap()
            .is_none());
        assert_eq!(
            bindings.executable(&references[0], &operation).unwrap(),
            Some(&(product.owner().clone(), 7))
        );
        let foreign_operation = Arc::new(InventoryOperation::new(Default::default()));
        assert!(bindings
            .executable(&references[0], &foreign_operation)
            .is_err());
        assert!(matches!(
            ResolvedOriginalBindings::issue(
                Arc::clone(&acquisition), Arc::clone(&operation), [&references[1]],
            ),
            Err(CertificationError::OriginalAvailability(reason))
                if reason.owner == *product.owner() && reason.original_ordinal == 11
        ));
        assert!(OriginalBindingSelection::issue(
            Arc::clone(&acquisition),
            Arc::new(InventoryOperation::new(Default::default())),
            &references,
            Some(Arc::clone(&resolved)),
        )
        .is_err());
        assert!(OriginalBindingSelection::issue(
            Arc::new(acquisition.as_ref().clone()),
            Arc::clone(&operation),
            &references,
            Some(Arc::clone(&resolved)),
        )
        .is_err());
        assert!(OriginalBindingSelection::issue(
            Arc::clone(&acquisition),
            Arc::clone(&operation),
            [&references[1]],
            Some(Arc::clone(&resolved)),
        )
        .is_err());
        let foreign_inputs = crate::declaration_context::ProductCompilerInputs::from_exact(
            request.compiler_inputs(),
        );
        let foreign_bindings = OriginalBindingSelection::issue(
            Arc::new(acquisition.as_ref().clone()),
            Arc::clone(&operation),
            &references,
            None,
        )
        .unwrap();
        assert!(foreign_inputs
            .with_original_bindings(foreign_bindings, &operation)
            .is_err());
        let inputs = crate::declaration_context::ProductCompilerInputs::from_exact(
            request.compiler_inputs(),
        )
        .with_original_bindings(bindings, &operation)
        .unwrap()
        .authenticate_original_bindings(&references, &operation)
        .unwrap();
        let selection =
            CertifiedSourceSelection::from_product_compiler_inputs(&inputs, &operation).unwrap();
        assert!(CertifiedSourceSelection::from_product_compiler_inputs(
            &inputs,
            &foreign_operation,
        )
        .is_err());
        assert_eq!(
            selection
                .original_bindings
                .as_ref()
                .unwrap()
                .metadata(&references[1]),
            Some(&(product.owner().clone(), 11))
        );
        let membership = request
            .compiler_inputs()
            .available_original_sources(std::slice::from_ref(product), &operation)
            .unwrap();
        let sources = membership.overlay(&request.groups, &operation).unwrap();
        // Availability may issue a fresh sibling whose exact child proof is
        // held, while preserving the other sibling as nominal metadata only.
        let held_groups = source
            .artifacts()
            .original_group_bindings(&operation)
            .unwrap();
        assert_eq!(held_groups.len(), 1);
        assert_eq!(held_groups[0].binding.artifact(), original.artifact);
        assert_eq!(held_groups[0].original_ordinal, 7);
        let cohort = |local_owner: &CachedHomeOwner| {
            let external = |ordinal| PendingImportOwner::Source {
                owner: product.owner().clone(),
                original_ordinal: ordinal,
                binder: testing::identity("BoundOriginal", &format!("entry_{ordinal}")),
            };
            let local = |ordinal| PendingImportOwner::Source {
                owner: local_owner.clone(),
                original_ordinal: ordinal,
                binder: testing::identity("LatentSiblingConsumer", &format!("entry_{ordinal}")),
            };
            original_groups_fixture(
                "LatentSiblingConsumer",
                vec![
                    (2, vec![external(7)]),
                    (3, vec![external(11)]),
                    (4, vec![local(5)]),
                    (5, vec![local(4)]),
                    (6, vec![local(7), local(3)]),
                    (7, vec![local(6)]),
                ],
                8,
                &BTreeMap::new(),
            )
        };
        // Native bytes determine the owner independently of the HOME import
        // coordinates. Re-encode those untrusted coordinates with that actual
        // owner before physical admission, including the local cycles.
        let draft = cohort(product.owner());
        let fresh = fixture_finalized_product_with_requirements(
            cohort(draft.owner()),
            producer,
            Some(BTreeMap::from([(
                (owner.unit.clone(), owner.module.clone()),
                product.module_interface().unwrap().interface_sha256(),
            )])),
        );
        let fresh_entry = Arc::new(ArtifactEntry::original(producer, fresh.clone()).unwrap());
        let mut fresh_selection = selection.clone();
        fresh_selection
            .admit_current(
                fresh.owner(),
                ProductOrigin::Fresh,
                fresh.module_interface().unwrap(),
                &operation,
            )
            .unwrap();
        fresh_selection
            .bind_produced_originals(&IssuedGroupCandidates::bind(Arc::from([]), &[fresh]).unwrap())
            .unwrap();
        let before = source.artifacts().capture_graph_selection();
        let fresh_id = fresh_entry.descriptor.id;
        let issued = OriginalCompilerInputs::issue_segment_native_availability(
            &mut fresh_selection,
            source.artifacts(),
            vec![fresh_entry],
            &mut crate::recovery_artifacts::PackageInterfaceValidation::with_inventory(Arc::clone(
                &operation,
            )),
        )
        .unwrap();
        let row = issued.native_availability().issued_row(fresh_id).unwrap();
        for ordinal in [2, 4, 5] {
            assert!(row.permits(ordinal), "supported local closure {ordinal}");
        }
        for ordinal in [3, 6, 7] {
            assert!(!row.permits(ordinal), "unavailable local closure {ordinal}");
        }
        assert!(row
            .offers()
            .all(|offer| offer.full_qualification().is_none()));
        assert!(issued
            .issued_artifacts()
            .observed_payload(&fresh_id)
            .unwrap()
            .native_group_ordinals
            .contains(&3));
        assert_eq!(source.artifacts().capture_graph_selection(), before);
        let produced_owner = issued
            .issued_artifacts()
            .observed_payload(&fresh_id)
            .unwrap()
            .descriptor
            .owner
            .clone();
        let publication = fresh_selection
            .produced_authored_original_publication(
                issued.physical_cohort().unwrap(),
                &produced_owner,
            )
            .unwrap();
        let receipt = fresh_selection
            .produced_source_receipt(&produced_owner, issued.issued_artifacts())
            .unwrap()
            .unwrap();
        assert!(Arc::ptr_eq(
            publication.produced_availability().unwrap(),
            &receipt
        ));
        for ordinal in [2, 4, 5] {
            let key = NativeGroupKey {
                artifact: fresh_id,
                original_ordinal: ordinal,
            };
            let selected = receipt.choose_own_group(key, &operation).unwrap().unwrap();
            assert_eq!(
                receipt.groups(key).collect::<Vec<_>>(),
                vec![selected.binding()]
            );
            assert!(selected
                .contribution()
                .offer()
                .same_issuance(receipt.own_offer()));
        }
        for ordinal in [3, 6, 7] {
            assert!(receipt
                .choose_own_group(
                    NativeGroupKey {
                        artifact: fresh_id,
                        original_ordinal: ordinal,
                    },
                    &operation
                )
                .unwrap()
                .is_none());
        }
        assert!(
            receipt
                .choose_own_group(
                    NativeGroupKey {
                        artifact: entry.descriptor.id,
                        original_ordinal: 7,
                    },
                    &operation
                )
                .unwrap()
                .is_none(),
            "dependency custody is not an own root"
        );

        let expected_roots = [2, 4, 5]
            .into_iter()
            .map(|ordinal| {
                crate::artifact_inventory::ArtifactBindingNode::Group(
                    receipt
                        .groups(NativeGroupKey {
                            artifact: fresh_id,
                            original_ordinal: ordinal,
                        })
                        .next()
                        .unwrap(),
                )
            })
            .collect::<BTreeSet<_>>();
        assert_eq!(
            publication
                .native_closure()
                .capture_graph_selection()
                .roots
                .into_iter()
                .collect::<BTreeSet<_>>(),
            expected_roots
        );
        let closed = CompilerSourceSupport::close_complete_output(&issued).unwrap();
        let published = closed.certify_original_closure(&publication).unwrap();
        let canonical = ArtifactEntry::canonical_artifact_id(
            publication.products()[0].module_interface().unwrap(),
        );
        let crate::artifact_inventory::InputNativeDecision::IssuedChoices(choices) = published
            .checked_native_input_decision(fresh_id, canonical, row.original_owner())
            .unwrap()
        else {
            panic!("publication records its exact future input choices")
        };
        assert_eq!(
            choices.keys().copied().collect::<BTreeSet<_>>(),
            BTreeSet::from([2, 4, 5])
        );
        for (&ordinal, &binding) in choices {
            assert_eq!(
                receipt
                    .groups(NativeGroupKey {
                        artifact: fresh_id,
                        original_ordinal: ordinal
                    })
                    .collect::<Vec<_>>(),
                vec![binding]
            );
        }
        assert!(published
            .native_offers()
            .iter()
            .any(|offer| offer.same_issuance(receipt.own_offer())));
        let native_roots = |graph: crate::artifact_inventory::ArtifactGraphSelection| {
            graph
                .roots
                .into_iter()
                .filter(|root| {
                    matches!(
                        root,
                        crate::artifact_inventory::ArtifactBindingNode::Group(_)
                    )
                })
                .collect::<BTreeSet<_>>()
        };
        assert_eq!(
            native_roots(issued.issued_artifacts().capture_graph_selection()),
            native_roots(source.artifacts().capture_graph_selection()),
            "physical issuance preserves inherited demand without selecting new bodies",
        );
        let carried_context = ExactDeclarationContext::new(&[], &[], vec![])
            .unwrap()
            .extend_issued_compiler_support(&published)
            .unwrap();
        let carried_directory = tempfile::tempdir().unwrap();
        let carried_request = ExactCompileContext::new(Arc::new(carried_context))
            .prepare_compilation(carried_directory.path(), b"original-binding-test")
            .unwrap();
        let carried = CertifiedSourceSelection::from_compiler_inputs(
            carried_request.compiler_inputs(),
            &operation,
        )
        .unwrap();
        assert!(carried
            .produced_authored_original_publication(
                issued.physical_cohort().unwrap(),
                &produced_owner,
            )
            .is_err());
        assert!(fresh_selection
            .produced_authored_original_publication(
                output.physical_cohort().unwrap(),
                &produced_owner,
            )
            .is_err());

        let empty_product = fixture_finalized_product(
            full_native_fixture(
                "EmptyPublished",
                vec![(
                    17,
                    vec![PendingImportOwner::Source {
                        owner: product.owner().clone(),
                        original_ordinal: 11,
                        binder: testing::identity("BoundOriginal", "entry_11"),
                    }],
                )],
                9,
            ),
            producer,
        );
        let empty_entry =
            Arc::new(ArtifactEntry::original(producer, empty_product.clone()).unwrap());
        let empty_id = empty_entry.descriptor.id;
        let empty_owner = empty_entry.descriptor.owner.clone();
        let mut empty_selection = selection.clone();
        empty_selection
            .admit_current(
                empty_product.owner(),
                ProductOrigin::Fresh,
                empty_product.module_interface().unwrap(),
                &operation,
            )
            .unwrap();
        empty_selection
            .bind_produced_originals(
                &IssuedGroupCandidates::bind(Arc::from([]), &[empty_product]).unwrap(),
            )
            .unwrap();
        let empty_output = OriginalCompilerInputs::issue_segment_native_availability(
            &mut empty_selection,
            source.artifacts(),
            vec![empty_entry],
            &mut PackageInterfaceValidation::with_inventory(Arc::clone(&operation)),
        )
        .unwrap();
        let empty_publication = empty_selection
            .produced_authored_original_publication(
                empty_output.physical_cohort().unwrap(),
                &empty_owner,
            )
            .unwrap();
        assert!(empty_publication
            .native_closure()
            .selected_native_groups()
            .is_empty());
        assert!(empty_publication
            .produced_availability()
            .unwrap()
            .choose_own_group(
                NativeGroupKey {
                    artifact: empty_id,
                    original_ordinal: 17
                },
                &operation,
            )
            .unwrap()
            .is_none());

        assert!(empty_publication.products()[0]
            .original_native()
            .unwrap()
            .group(17)
            .is_some());
        let empty_support = CompilerSourceSupport::close_complete_output(&empty_output)
            .unwrap()
            .certify_original_closure(&empty_publication)
            .unwrap();
        let empty_row = empty_output
            .native_availability()
            .issued_row(empty_id)
            .unwrap();
        let crate::artifact_inventory::InputNativeDecision::IssuedChoices(choices) = empty_support
            .checked_native_input_decision(
                empty_id,
                ArtifactEntry::canonical_artifact_id(
                    empty_publication.products()[0].module_interface().unwrap(),
                ),
                empty_row.original_owner(),
            )
            .unwrap()
        else {
            panic!("empty publication records an explicit empty choice")
        };
        assert!(choices.is_empty());
        assert!(!empty_support
            .native_availability()
            .issued_row(empty_id)
            .unwrap()
            .permits(17));
        let mut validation = PackageInterfaceValidation::with_inventory(Arc::clone(&operation));
        for (reference, ordinal) in references.into_iter().zip([7, 11]) {
            let result = resolve_receipt_owner_with_validation(
                reference,
                &sources,
                Some(&selection),
                &BTreeMap::new(),
                &mut validation,
            );
            if ordinal == 7 {
                assert_eq!(
                    result.unwrap(),
                    PendingImportOwner::Source {
                        owner: product.owner().clone(),
                        original_ordinal: ordinal,
                        binder: testing::identity("BoundOriginal", "entry_7"),
                    }
                );
            } else {
                assert!(matches!(
                    result,
                    Err(CertificationError::InputDecision {
                        reason: InputDecisionRefusal::MissingContinuationOwner,
                        ..
                    })
                ));
            }
        }
    }

    #[test]
    fn receipt_original_identity_selects_exact_issued_artifact_among_equal_owners() {
        use crate::artifact_inventory::{
            ArtifactEntry, ArtifactInventory, CompilerInputProjection,
        };
        let product = full_native_fixture("ExactReceiptIdentity", vec![(7, vec![])], 1);
        let producer = product.module_interface().unwrap().producer_sha256();
        let entry = Arc::new(ArtifactEntry::original(producer, product.clone()).unwrap());
        let other = Arc::new(
            ArtifactEntry::original([3; 32], fixture_finalized_product(product.clone(), [3; 32]))
                .unwrap(),
        );
        let crate::artifact_inventory::ArtifactPayload::Original(other_product) = &other.payload
        else {
            unreachable!();
        };
        assert_eq!(product.owner(), other_product.owner());
        assert_ne!(entry.descriptor.id, other.descriptor.id);
        let inventory = ArtifactInventory::default();
        let left = inventory
            .admit_shared(&inventory.empty_view(), vec![entry.clone()])
            .unwrap();
        let right = inventory
            .admit_shared(&inventory.empty_view(), vec![other.clone()])
            .unwrap();
        let projection = CompilerInputProjection::from_issued_entries(&[entry.clone()]).unwrap();
        let both = left.retain_custody(&right).unwrap();
        let metadata = both.metadata_snapshot();
        assert!(metadata.artifacts.contains_key(&entry.descriptor.id));
        assert!(metadata.artifacts.contains_key(&other.descriptor.id));
        let operation = InventoryOperation::new(Default::default());
        let mut selected =
            CertifiedSourceSelection::from_compiler_projection(&projection, &metadata, &operation)
                .unwrap();
        let output =
            crate::declaration_context::OriginalCompilerInputs::issue_segment_native_availability(
                &mut selected,
                &both,
                vec![entry.clone()],
                &mut crate::recovery_artifacts::PackageInterfaceValidation::default(),
            )
            .unwrap();
        let issued = output.native_availability();
        assert_eq!(
            selected
                .compiler_projection_from_metadata(&metadata, &BTreeSet::new())
                .unwrap(),
            projection
        );
        let native = selected.native_selections().next().unwrap();
        let actual = native
            .original_entry(projection.roles()[0].interface(), &metadata)
            .unwrap();
        assert!(Arc::ptr_eq(
            &actual,
            issued
                .issued_row(entry.descriptor.id)
                .unwrap()
                .target_original(product.owner())
                .unwrap()
        ));
        let current = selected
            .current_product(
                crate::artifact_inventory::NativeGroupKey {
                    artifact: entry.descriptor.id,
                    original_ordinal: 7,
                },
                &entry,
            )
            .unwrap()
            .unwrap();
        assert!(Arc::ptr_eq(current.entry(), &entry));
        assert!(current
            .dependency_product(
                crate::artifact_inventory::NativeGroupKey {
                    artifact: other.descriptor.id,
                    original_ordinal: 7,
                },
                &other,
            )
            .unwrap()
            .is_none());
        let actual_dependency = current
            .dependency_product(current.key(), &entry)
            .unwrap()
            .unwrap();
        assert!(Arc::ptr_eq(actual_dependency.entry(), &entry));
        let groups = current.own_group_candidates().unwrap();
        assert_eq!(groups.bindings().len(), 1);
        let CertifiedNativeGroupSupport::Issued(own) = current
            .own_group_support(*groups.bindings().first().unwrap())
            .unwrap()
        else {
            panic!("completed current product owns its issued proof");
        };
        let offered = output
            .native_offers()
            .iter()
            .find(|offer| offer.original() == entry.descriptor.id && offer.proof().is_some())
            .unwrap();
        assert!(own.same_issuance(offered));
        assert_eq!(
            selected
                .artifact_ids_from_entries(&metadata.artifacts)
                .unwrap(),
            BTreeSet::from([entry.descriptor.id, projection.roles()[0].interface()]),
        );
        let wrong_owner = BTreeMap::from([(
            crate::artifact_inventory::NativeOwnerKey::from_owner(product.owner()),
            other.descriptor.id,
        )]);
        assert!(matches!(
            selected.artifact_ids_from_bound_entries(
                &metadata.artifacts,
                &wrong_owner,
                &both,
                &BTreeSet::new(),
            ),
            Err(CertificationError::Mismatch(
                "issued compiler native artifact"
            )),
        ));
        let mut missing = metadata.as_ref().clone();
        missing.artifacts.remove(&entry.descriptor.id);
        assert!(matches!(
            selected.artifact_ids_from_entries(&missing.artifacts),
            Err(CertificationError::MissingRetainedCustody { artifact })
                if artifact == entry.descriptor.id,
        ));
        assert!(
            selected
                .compiler_projection_from_metadata(&missing, &BTreeSet::new())
                .is_err(),
            "another artifact with equal CachedHomeOwner cannot replace the actual issued Original"
        );
    }

    #[test]
    fn receipt_new_product_identity_binds_only_actual_producing_cohort() {
        use crate::artifact_inventory::{
            ArtifactEntry, ArtifactInventory, CompilerInputProjection,
        };
        let product = full_native_fixture("ProducedReceiptIdentity", vec![(7, vec![])], 1);
        let canonical = product.module_interface().unwrap();
        let entry = Arc::new(
            ArtifactEntry::original(canonical.producer_sha256(), product.clone()).unwrap(),
        );
        let inventory = ArtifactInventory::default();
        let view = inventory
            .admit_shared(&inventory.empty_view(), vec![entry.clone()])
            .unwrap();
        let projection = CompilerInputProjection::from_issued_entries(&[entry.clone()]).unwrap();
        let operation = InventoryOperation::new(Default::default());
        let mut selected = CertifiedSourceSelection::new_product_ingress();
        selected
            .admit_current(product.owner(), ProductOrigin::Fresh, canonical, &operation)
            .unwrap();
        assert!(
            selected.compiler_projection(&view).is_err(),
            "unfinished producer identity cannot enter Original projection"
        );
        assert!(selected
            .bind_produced_originals(&IssuedGroupCandidates::empty())
            .is_err());
        let produced =
            IssuedGroupCandidates::bind(Arc::from([]), std::slice::from_ref(&product)).unwrap();
        selected.bind_produced_originals(&produced).unwrap();
        assert_eq!(
            selected
                .native_selections()
                .next()
                .unwrap()
                .original_artifact_id()
                .unwrap(),
            entry.descriptor.id
        );
        assert_eq!(selected.compiler_projection(&view).unwrap(), projection);
        let completed = selected.complete_native_entries(&view, &operation).unwrap();
        assert_eq!(completed.len(), 1);
        assert!(Arc::ptr_eq(
            &completed[0],
            &view.metadata_snapshot().artifacts[&entry.descriptor.id]
        ));
        let output =
            crate::declaration_context::OriginalCompilerInputs::issue_segment_native_availability(
                &mut selected,
                &view,
                vec![entry.clone()],
                &mut crate::recovery_artifacts::PackageInterfaceValidation::default(),
            )
            .unwrap();
        let issued = output.native_availability();
        assert!(Arc::ptr_eq(
            issued
                .issued_row(entry.descriptor.id)
                .unwrap()
                .target_original(product.owner())
                .unwrap(),
            &entry,
        ));
        let current = selected
            .current_product(
                crate::artifact_inventory::NativeGroupKey {
                    artifact: entry.descriptor.id,
                    original_ordinal: 7,
                },
                &entry,
            )
            .unwrap()
            .unwrap();
        assert!(Arc::ptr_eq(current.entry(), &entry));
        let groups = current.own_group_candidates().unwrap();
        assert_eq!(groups.bindings().len(), 1);
        let CertifiedNativeGroupSupport::Issued(own) = current
            .own_group_support(*groups.bindings().first().unwrap())
            .unwrap()
        else {
            panic!("completed current product owns its issued proof");
        };
        let offered = output
            .native_offers()
            .iter()
            .find(|offer| offer.original() == entry.descriptor.id && offer.proof().is_some())
            .unwrap();
        assert!(own.same_issuance(offered));
        assert!(
            selected
                .complete_native_entries(&view, &operation)
                .unwrap()
                .is_empty(),
            "already-issued body is not a new product to reissue"
        );
    }

    #[test]
    fn issued_interface_upgrade_preserves_exact_choice_and_native_authority() {
        use crate::artifact_inventory::{
            ArtifactEntry, ArtifactInventory, CompilerInputProjection,
        };
        let original = full_native_fixture("Upgrade", vec![(3, vec![])], 7);
        let canonical = original.module_interface().unwrap();
        let interface = Arc::new(ArtifactEntry::canonical(canonical.clone()));
        let native = Arc::new(
            ArtifactEntry::original(canonical.producer_sha256(), original.clone()).unwrap(),
        );
        let inventory = ArtifactInventory::default();
        let view = inventory
            .admit_recovery_selection(
                &inventory.empty_view(),
                vec![native, interface.clone()],
                &BTreeSet::new(),
            )
            .unwrap();
        let issued = CompilerInputProjection::from_issued_entries(&[interface]).unwrap();
        let operation = InventoryOperation::new(Default::default());
        let mut selection = CertifiedSourceSelection::from_compiler_projection(
            &issued,
            &view.metadata_snapshot(),
            &operation,
        )
        .unwrap();
        assert_eq!(selection.receipt_native_body_owners().count(), 0);
        assert_eq!(selection.compiler_projection(&view).unwrap(), issued);
        let sources =
            available_original_source_map(std::slice::from_ref(&original), &[], &operation)
                .unwrap();
        assert!(matches!(
            resolve_receipt_owner_with_validation(
                ReceiptImportOwner::Source {
                    unit: original.owner().unit.clone(),
                    module: original.owner().module.clone(),
                    module_version: Some(original.owner().module_version.clone()),
                    original_ordinal: 3,
                    binder: testing::identity("Upgrade", "entry_3")
                },
                &sources,
                Some(&selection),
                &BTreeMap::new(),
                &mut PackageInterfaceValidation::default(),
            ),
            Err(CertificationError::SourceOutsideCompilerSelection {
                owner,
                requested_version,
                original_ordinal: Some(3),
            }) if owner.unit == original.owner().unit
                && owner.module == original.owner().module
                && requested_version == original.owner().module_version
        ));

        let other = recovered_witness_fixtures(&[fixture_finalized_product(
            original_groups_fixture_with_interface(
                "Upgrade",
                vec![(3, vec![])],
                9,
                &BTreeMap::new(),
                vec![0x43],
            ),
            [1; 32],
        )])
        .remove(0)
        .product;
        assert_ne!(
            ArtifactEntry::canonical(other.module_interface().unwrap().clone())
                .descriptor
                .id,
            issued.roles()[0].interface()
        );
        assert!(matches!(
            selection.admit_current(
                other.owner(),
                ProductOrigin::Fresh,
                other.module_interface().unwrap(),
                &operation
            ),
            Err(CertificationError::Mismatch(
                "compiler selected interface replaced"
            ))
        ));
        assert_eq!(selection.compiler_projection(&view).unwrap(), issued);
        selection
            .admit_current(
                original.owner(),
                ProductOrigin::Fresh,
                canonical,
                &operation,
            )
            .unwrap();
        selection
            .bind_produced_originals(
                &IssuedGroupCandidates::bind(Arc::from([]), &[original.clone()]).unwrap(),
            )
            .unwrap();
        assert_eq!(
            selection.receipt_native_body_owners().collect::<Vec<_>>(),
            vec![original.owner()]
        );
        let upgraded = selection.compiler_projection(&view).unwrap();
        assert_eq!(
            upgraded.roles()[0].interface(),
            issued.roles()[0].interface()
        );
        assert!(upgraded.roles()[0].original().is_some());
        selection
            .admit_current(
                original.owner(),
                ProductOrigin::Cached,
                canonical,
                &operation,
            )
            .unwrap();
        selection
            .bind_produced_originals(
                &IssuedGroupCandidates::bind(Arc::from([]), &[original.clone()]).unwrap(),
            )
            .unwrap();
        assert_eq!(selection.compiler_projection(&view).unwrap(), upgraded);
        assert!(matches!(
            selection.admit_current(
                original.owner(),
                ProductOrigin::Fresh,
                canonical,
                &operation
            ),
            Err(CertificationError::Mismatch(
                "compiler original owner replaced"
            ))
        ));
        assert_eq!(selection.compiler_projection(&view).unwrap(), upgraded);
    }

