    proptest::proptest! {
        #![proptest_config(proptest::test_runner::Config::with_cases(12))]
        #[test]
        fn completed_request_native_owners_survive_historical_custody(
            current in 0u8..8,
            historical in 8u8..16,
        ) {
            check_continuation_namespace_with_historical_custody(current, historical);
        }
    }

    fn check_continuation_namespace_with_historical_custody(current: u8, historical: u8) {
        use crate::artifact_inventory::{
            ArtifactEntry, ArtifactInventory, CompilerInputProjection,
        };
        let producer_bytes = b"continuation-role-cycle";
        let producer = crate::artifact_inventory::CanonicalProducerIdentity::from_producer_bytes(
            producer_bytes,
        );
        let product = |version| {
            recovered_witness_fixtures(&[fixture_finalized_product(
                original_groups_fixture(
                    "RoleCycle",
                    vec![(3, vec![]), (9, vec![])],
                    version,
                    &BTreeMap::new(),
                ),
                producer.sha256(),
            )])
            .remove(0)
            .product
        };
        let original = product(current);
        let historical = product(historical);
        assert_eq!(original.module_interface(), historical.module_interface());
        assert_ne!(original.owner(), historical.owner());
        let canonical = original.module_interface().unwrap();
        let interface = Arc::new(ArtifactEntry::canonical(canonical.clone()));
        let native = Arc::new(
            ArtifactEntry::original(canonical.producer_sha256(), original.clone()).unwrap(),
        );
        let inventory = ArtifactInventory::default();
        let view = inventory
            .admit_recovery_selection(
                &inventory.empty_view(),
                vec![native.clone(), interface.clone()],
                &BTreeSet::new(),
            )
            .unwrap();
        let historical_view = inventory
            .admit_recovery_selection(
                &inventory.empty_view(),
                vec![
                    Arc::new(ArtifactEntry::original(producer.sha256(), historical).unwrap()),
                    interface.clone(),
                ],
                &BTreeSet::new(),
            )
            .unwrap();
        let view = view.retain_custody(&historical_view).unwrap();
        assert!(view.metadata_snapshot().ambiguous_native_owners.contains(
            &crate::declaration_join::ExactModuleIdentity {
                unit: original.owner().unit.clone(),
                module: original.owner().module.clone(),
            }
        ));
        let operation = InventoryOperation::new(Default::default());
        let assert_namespace_ids = |selection: &CertifiedSourceSelection,
                                    view: &crate::artifact_inventory::ArtifactView,
                                    namespace_original: bool| {
            let metadata = view.metadata_snapshot();
            let native_owners = metadata
                .artifacts
                .iter()
                .filter_map(|(id, entry)| match &entry.payload {
                    crate::artifact_inventory::ArtifactPayload::Original(product) => Some((
                        crate::artifact_inventory::NativeOwnerKey::from_owner(product.owner()),
                        *id,
                    )),
                    _ => None,
                })
                .collect();
            let expected = std::iter::once(interface.descriptor.id)
                .chain(namespace_original.then_some(native.descriptor.id))
                .collect::<BTreeSet<_>>();
            let projected = selection
                .compiler_projection(view)
                .unwrap()
                .roles()
                .into_iter()
                .flat_map(|role| std::iter::once(role.interface()).chain(role.original()))
                .collect::<BTreeSet<_>>();
            assert_eq!(projected, expected);
            assert_eq!(
                selection
                    .artifact_ids_from_entries(&metadata.artifacts)
                    .unwrap(),
                expected
            );
            assert_eq!(
                selection
                    .artifact_ids_from_bound_entries(
                        &metadata.artifacts,
                        &native_owners,
                        view,
                        &BTreeSet::new()
                    )
                    .unwrap(),
                expected
            );
        };
        for (origin, namespace_original) in [
            (ProductOrigin::Fresh, true),
            (ProductOrigin::Cached, true),
            (ProductOrigin::RetainedCore, false),
        ] {
            let projection =
                CompilerInputProjection::from_issued_entries(&[interface.clone()]).unwrap();
            let mut selection = CertifiedSourceSelection::from_compiler_projection(
                &projection,
                &view.metadata_snapshot(),
                &operation,
            )
            .unwrap();
            selection
                .admit_current(original.owner(), origin, canonical, &operation)
                .unwrap();
            selection
                .bind_produced_originals(
                    &IssuedGroupCandidates::bind(Arc::from([]), &[original.clone()]).unwrap(),
                )
                .unwrap();
            assert_eq!(
                selection.receipt_native_body_owners().collect::<Vec<_>>(),
                vec![original.owner()]
            );
            assert_eq!(
                selection.compiler_namespace_originals().count(),
                usize::from(namespace_original)
            );
            assert_eq!(
                selection
                    .complete_native_entries(&view, &operation)
                    .unwrap(),
                vec![native.clone()]
            );
            assert!(selection.permits_native_group(native.descriptor.id, original.owner(), 9));
            let projected = selection.compiler_projection(&view).unwrap();
            assert_eq!(
                projected.roles()[0].original().is_some(),
                namespace_original
            );
            assert_eq!(
                projected.roles()[0].interface(),
                projection.roles()[0].interface()
            );
            assert_eq!(
                selection.compiler_support_projection(&view, &[]).unwrap(),
                projected
            );
            assert_namespace_ids(&selection, &view, namespace_original);
            let mut carried = selection;
            for _ in 0..3 {
                let owner = crate::declaration_join::ExactModuleIdentity {
                    unit: original.owner().unit.clone(),
                    module: original.owner().module.clone(),
                };
                let context =
                    crate::declaration_context::ExactDeclarationContext::from_source_selection(
                        producer.sha256(),
                        &carried,
                        &view,
                        vec![crate::declaration_join::ExactLexicalNode {
                            owner: owner.clone(),
                            imports: vec![],
                        }],
                        owner,
                        &[],
                    )
                    .unwrap();
                assert!(context
                    .compiler_source_support()
                    .native_offers()
                    .iter()
                    .any(|offer| offer.original() == native.descriptor.id && offer.is_full()));
                let root = tempfile::tempdir().unwrap();
                let request =
                    crate::declaration_context::ExactCompileContext::new(Arc::new(context))
                        .prepare_compilation(root.path(), producer_bytes)
                        .unwrap();
                assert!(request.groups.is_empty());
                assert!(request
                    .compiler_inputs()
                    .artifacts()
                    .selected_native_groups()
                    .is_empty());
                let inputs = request.compiler_inputs();
                carried =
                    CertifiedSourceSelection::from_compiler_inputs(inputs, &operation).unwrap();
                assert_eq!(
                    carried.compiler_namespace_originals().count(),
                    usize::from(namespace_original)
                );
                assert!(carried.permits_native_group(native.descriptor.id, original.owner(), 9));
                assert_namespace_ids(&carried, inputs.artifacts(), namespace_original);
            }
            if !namespace_original {
                assert_eq!(carried.receipt_native_body_owners().count(), 0);
                carried
                    .admit_current(
                        original.owner(),
                        ProductOrigin::Cached,
                        canonical,
                        &operation,
                    )
                    .unwrap();
                carried
                    .bind_produced_originals(
                        &IssuedGroupCandidates::bind(Arc::from([]), &[original.clone()]).unwrap(),
                    )
                    .unwrap();
                assert_eq!(carried.compiler_namespace_originals().count(), 1);
                assert!(carried.compiler_projection(&view).unwrap().roles()[0]
                    .original()
                    .is_some());
            }
        }
        let prior = CompilerInputProjection::from_issued_entries(&[interface, native]).unwrap();
        let mut selection = CertifiedSourceSelection::from_compiler_projection(
            &prior,
            &view.metadata_snapshot(),
            &operation,
        )
        .unwrap();
        selection
            .admit_current(
                original.owner(),
                ProductOrigin::Cached,
                canonical,
                &operation,
            )
            .unwrap();
        selection
            .bind_produced_originals(
                &IssuedGroupCandidates::bind(Arc::from([]), &[original.clone()]).unwrap(),
            )
            .unwrap();
        assert_eq!(selection.compiler_projection(&view).unwrap(), prior);
        assert!(selection
            .admit_current(
                original.owner(),
                ProductOrigin::RetainedCore,
                canonical,
                &operation
            )
            .is_err());
        assert_eq!(selection.compiler_projection(&view).unwrap(), prior);
        let interface_only = inventory
            .admit_recovery_selection(
                &inventory.empty_view(),
                vec![Arc::new(ArtifactEntry::canonical(canonical.clone()))],
                &BTreeSet::new(),
            )
            .unwrap();
        for (missing, available) in [
            (original.clone(), &interface_only),
            (product(current + 32), &view),
        ] {
            let expected_missing = ArtifactEntry::original(producer.sha256(), missing.clone())
                .unwrap()
                .descriptor
                .id;
            let projection = CompilerInputProjection::from_issued_entries(&[Arc::new(
                ArtifactEntry::canonical(canonical.clone()),
            )])
            .unwrap();
            let mut absent = CertifiedSourceSelection::from_compiler_projection(
                &projection,
                &available.metadata_snapshot(),
                &operation,
            )
            .unwrap();
            absent
                .admit_current(
                    missing.owner(),
                    ProductOrigin::RetainedCore,
                    canonical,
                    &operation,
                )
                .unwrap();
            absent
                .bind_produced_originals(
                    &IssuedGroupCandidates::bind(Arc::from([]), &[missing.clone()]).unwrap(),
                )
                .unwrap();
            let owner = crate::declaration_join::ExactModuleIdentity {
                unit: missing.owner().unit.clone(),
                module: missing.owner().module.clone(),
            };
            let result = crate::declaration_context::ExactDeclarationContext::from_source_selection(
                producer.sha256(),
                &absent,
                available,
                vec![],
                owner,
                &[],
            );
            assert!(matches!(result,
                Err(crate::CompileError::CompilerEvidence(error))
                if matches!(*error, CertificationError::MissingRetainedCustody { artifact }
                    if artifact == expected_missing)));
        }
    }

    #[test]
    fn completed_new_product_request_preserves_input_group_permissions() {
        use crate::artifact_inventory::{
            ArtifactEntry, ArtifactInventory, CompilerInputProjection, NativeArtifactDemand,
            NativeGroupKey,
        };
        use crate::declaration_context::{
            ExactCompileContext, ExactDeclarationContext, OriginalCompilerInputs,
        };
        let producer_bytes = b"completed-request-input-permissions";
        let producer = crate::artifact_inventory::CanonicalProducerIdentity::from_producer_bytes(
            producer_bytes,
        );
        let dependency = fixture_finalized_product(
            original_groups_fixture_with_interface(
                "RequestInput",
                vec![(7, vec![]), (9001, vec![])],
                21,
                &BTreeMap::new(),
                b"RequestInput interface".to_vec(),
            ),
            producer.sha256(),
        );
        let fresh = fixture_finalized_product(
            original_groups_fixture_with_interface(
                "RequestFresh",
                vec![(
                    3,
                    vec![PendingImportOwner::Source {
                        owner: dependency.owner().clone(),
                        original_ordinal: 7,
                        binder: testing::identity("RequestInput", "entry_7"),
                    }],
                )],
                22,
                &BTreeMap::new(),
                b"RequestFresh interface".to_vec(),
            ),
            producer.sha256(),
        );
        let replacement = fixture_finalized_product(
            original_groups_fixture_with_interface(
                "RequestInput",
                vec![(7, vec![]), (9001, vec![])],
                23,
                &BTreeMap::new(),
                b"RequestInput interface".to_vec(),
            ),
            producer.sha256(),
        );
        let products = recovered_witness_fixtures(&[dependency, fresh, replacement]);
        let dependency = &products[0].product;
        let fresh = &products[1].product;
        let input =
            Arc::new(ArtifactEntry::original(producer.sha256(), dependency.clone()).unwrap());
        let fresh_entry =
            Arc::new(ArtifactEntry::original(producer.sha256(), fresh.clone()).unwrap());
        let replacement = &products[2].product;
        assert_eq!(
            dependency.module_interface(),
            replacement.module_interface()
        );
        assert_ne!(dependency.owner(), replacement.owner());
        let replacement_id = ArtifactEntry::original(producer.sha256(), replacement.clone())
            .unwrap()
            .descriptor
            .id;
        let mut histories = 0;
        let mut accepted = 0;
        for (sibling_count, selected_siblings) in [(0, false), (2, false), (2, true)] {
            let siblings = (0..sibling_count)
                .map(|index| {
                    fixture_finalized_product(
                        original_groups_fixture_with_interface(
                            &format!("UnrelatedRequestHistory{index}"),
                            vec![(9001, vec![])],
                            24 + index as u8,
                            &BTreeMap::new(),
                            format!("unrelated interface {index}").into_bytes(),
                        ),
                        producer.sha256(),
                    )
                })
                .collect::<Vec<_>>();
            let recovered_siblings = if siblings.is_empty() {
                vec![]
            } else {
                recovered_witness_fixtures(&siblings)
            };
            let sibling_entries = recovered_siblings
                .into_iter()
                .map(|row| {
                    Arc::new(ArtifactEntry::original(producer.sha256(), row.product).unwrap())
                })
                .collect::<Vec<_>>();
            let entries = std::iter::once(input.clone())
                .chain(sibling_entries.iter().cloned())
                .collect::<Vec<_>>();
            for (ordinals, permitted) in [
                (vec![7, 9001], true),
                (vec![7], true),
                (vec![9001], false),
                (vec![], false),
            ] {
                let inventory = ArtifactInventory::default();
                let projection = CompilerInputProjection::from_issued_entries(&entries).unwrap();
                let full = inventory
                    .admit_shared(&inventory.empty_view(), entries.clone())
                    .unwrap();
                let full_support = crate::declaration_context::issue_fixture_compiler_support(
                    projection.clone(),
                    full,
                )
                .unwrap();
                let selected = ordinals
                    .iter()
                    .map(|ordinal| NativeGroupKey {
                        artifact: input.descriptor.id,
                        original_ordinal: *ordinal,
                    })
                    .chain(
                        sibling_entries
                            .iter()
                            .filter(|_| selected_siblings)
                            .map(|entry| NativeGroupKey {
                                artifact: entry.descriptor.id,
                                original_ordinal: 9001,
                            }),
                    )
                    .collect();
                let view = inventory
                    .admit_recovery_selection(&inventory.empty_view(), entries.clone(), &selected)
                    .unwrap();
                let owner = input.descriptor.owner.clone();
                let mut context = ExactDeclarationContext::from_authenticated_execution(
                    producer.sha256(),
                    &view,
                    projection,
                    vec![],
                    owner,
                    &[],
                )
                .unwrap()
                .retain_issued_native_offers(full_support.native_offers().iter().cloned())
                .unwrap();
                let baseline = context.compiler_source_support().clone();
                let root = tempfile::tempdir().unwrap();
                for (step, available) in [true, false, true, false].into_iter().enumerate() {
                    let candidates = crate::module_candidates::CandidateSet {
                        manifest_path: root.path().join("not-read-by-receiver"),
                        by_owner: BTreeMap::new(),
                        contextual_native_availability: if available {
                            vec![replacement.clone()]
                        } else {
                            vec![]
                        },
                        catalog_owner: None,
                        input_transport: Vec::new(),
                    };
                    let private =
                        OriginalCompilerInputs::from_candidates(&context, producer, &candidates)
                            .unwrap();
                    let exact_request = ExactCompileContext::new(Arc::new(context.clone()))
                        .prepare_compilation_with_private_input(
                            &root.path().join(step.to_string()),
                            producer_bytes,
                            None,
                            private,
                        )
                        .unwrap();
                    histories += 1;
                    let request = exact_request.compiler_inputs();
                    assert!(request.native_availability(replacement_id).is_none());
                    assert!(!request
                        .shared_compiler_source_support()
                        .native_offers()
                        .iter()
                        .any(|offer| offer.original() == replacement_id));
                    assert_eq!(request.projection(), baseline.projection());
                    assert_eq!(
                        request
                            .shared_compiler_source_support()
                            .input_decisions()
                            .recorded_facts(),
                        baseline.input_decisions().recorded_facts()
                    );
                    assert_eq!(
                        request.artifacts().capture_graph_selection().namespace,
                        baseline.artifacts().capture_graph_selection().namespace
                    );
                    assert_eq!(
                        request.artifacts().selected_native_groups(),
                        baseline.artifacts().selected_native_groups()
                    );
                    for sibling in &sibling_entries {
                        assert_eq!(
                            request
                                .native_availability(sibling.descriptor.id)
                                .unwrap()
                                .permits(9001),
                            selected_siblings
                        );
                    }
                    let row = request.native_availability(input.descriptor.id).unwrap();
                    assert_eq!(row.permits(7), permitted);
                    assert_eq!(
                        row.offers().any(|offer| offer.is_full()),
                        ordinals.len() == 2
                    );
                    assert!(
                        request
                            .shared_compiler_source_support()
                            .native_offers()
                            .iter()
                            .any(|offer| offer.is_full()),
                        "broader Full proof custody must not widen the normalized input row"
                    );
                    assert_eq!(row.permits(9001), ordinals.contains(&9001));
                    let operation = InventoryOperation::new(Default::default());
                    let mut selection =
                        CertifiedSourceSelection::from_compiler_inputs(&request, &operation)
                            .unwrap();
                    let input_only =
                        OriginalCompilerInputs::from_selection(&selection, request.artifacts())
                            .unwrap();
                    let source =
                        crate::artifact_inventory::CompilerSourceSupport::close_complete_output(
                            &input_only,
                        )
                        .unwrap();
                    let source_row = source
                        .native_availability()
                        .rows()
                        .find(|row| row.original_owner() == dependency.owner())
                        .unwrap();
                    assert_eq!(source_row.permits(7), permitted);
                    assert_eq!(
                        source.artifacts().selected_native_groups(),
                        input_only.issued_artifacts().selected_native_groups()
                    );
                    selection
                        .admit_current(
                            fresh.owner(),
                            ProductOrigin::RetainedCore,
                            fresh.module_interface().unwrap(),
                            &operation,
                        )
                        .unwrap();
                    selection
                        .bind_produced_originals(
                            &IssuedGroupCandidates::bind(Arc::from([]), &[fresh.clone()]).unwrap(),
                        )
                        .unwrap();
                    let physical = request
                        .artifacts()
                        .inventory()
                        .admit_shared_with_demand(
                            request.artifacts(),
                            vec![fresh_entry.clone()],
                            NativeArtifactDemand::ScopeInterfaces,
                        )
                        .unwrap();
                    let result = OriginalCompilerInputs::from_selection(&selection, &physical);
                    assert_eq!(
                        result.is_ok(),
                        permitted,
                        "request permissions {ordinals:?} siblings={sibling_count} selected_siblings={selected_siblings} step={step} available={available}; actual_error={:?}",
                        result.as_ref().err()
                    );
                    if permitted {
                        accepted += 1;
                        let completed = result.unwrap();
                        assert!(completed.native_offers().iter().any(|offer| {
                            offer.original() == fresh_entry.descriptor.id && offer.is_full()
                        }));
                        let dependency_row = completed
                            .native_availability()
                            .rows()
                            .find(|row| row.original_owner() == dependency.owner())
                            .unwrap();
                        assert!(dependency_row.permits(7));
                        assert_eq!(
                    dependency_row.permits(9001),
                    ordinals.contains(&9001),
                    "request rows preserve actual input grants across unrelated history and optional custody"
                );
                        assert_eq!(
                            completed.issued_artifacts().selected_native_groups(),
                            request.artifacts().selected_native_groups()
                        );
                        assert!(completed
                            .issued_artifacts()
                            .selected_native_groups()
                            .iter()
                            .all(|key| key.artifact != fresh_entry.descriptor.id));
                    } else {
                        assert!(
                            matches!(result, Err(crate::CompileError::ArtifactInventory(error))
                    if matches!(error.failure,
                        crate::artifact_inventory::ArtifactInventoryFailure::NativeGroupUnavailable {
                            artifact, original_ordinal: 7,
                        } if artifact == input.descriptor.id)),
                            "request must refuse unavailable input group 7"
                        );
                    }
                    let retained = context
                        .compiler_source_support()
                        .retain_custody(request.artifacts())
                        .unwrap();
                    context = context.extend_issued_compiler_support(&retained).unwrap();
                    assert!(context
                        .artifact_view()
                        .artifact_ids()
                        .contains(&replacement_id));
                    assert_eq!(
                        context.compiler_source_support().projection(),
                        baseline.projection()
                    );
                    assert_eq!(
                        context.compiler_source_support().native_availability(),
                        baseline.native_availability()
                    );
                    assert_eq!(
                        context.compiler_source_support().native_offers(),
                        baseline.native_offers()
                    );
                }
            }
        }
        assert_eq!(histories, 48);
        assert_eq!(accepted, 24);
        eprintln!(
            "request_input_permission_histories={} accepted={} refused={}",
            histories,
            accepted,
            histories - accepted
        );
    }

    #[test]
    fn completed_request_keeps_two_input_permissions_separate_from_fresh_outputs() {
        use crate::artifact_inventory::{
            ArtifactBindingNode, ArtifactEntry, ArtifactInventory, ArtifactInventoryFailure,
            CanonicalProducerIdentity, CompilerInputProjection, ExactArtifactSelection,
            NativeArtifactDemand, NativeGroupKey,
        };
        use crate::declaration_context::{
            issue_fixture_compiler_support, ExactCompileContext, ExactDeclarationContext,
            NativeTransportMode, OriginalCompilerInputs,
        };
        use crate::CompileError;
        let producer_bytes = b"two-input-request-obligations";
        let producer = CanonicalProducerIdentity::from_producer_bytes(producer_bytes);
        let product = |module: &str, version, groups| {
            fixture_finalized_product(
                original_groups_fixture_with_interface(
                    module,
                    groups,
                    version,
                    &BTreeMap::new(),
                    format!("{module} interface").into_bytes(),
                ),
                producer.sha256(),
            )
        };
        let import = |product: &crate::recovery_artifacts::CertifiedRecoveryProduct, ordinal| {
            let mut binder =
                testing::identity(&product.owner().module, &format!("entry_{ordinal}"));
            binder.unit = product.owner().unit.clone();
            PendingImportOwner::Source {
                owner: product.owner().clone(),
                original_ordinal: ordinal,
                binder,
            }
        };
        let unused = product("UnusedRequestInput", 31, vec![(7, vec![])]);
        let baseline = product(
            "FixedRequestInput",
            32,
            vec![(7, vec![]), (9001, vec![import(&unused, 7)])],
        );
        let required = product(
            "VariableRequestInput",
            33,
            vec![(7, vec![]), (9001, vec![])],
        );
        let extra = product("UnrelatedRequestOutput", 34, vec![(9001, vec![])]);
        let mut histories = 0;
        let mut accepted = 0;
        for demanded in [7, 9001] {
            let fresh = product(
                "FreshRequestOutput",
                35,
                vec![
                    (7, vec![import(&baseline, 7)]),
                    (9001, vec![import(&required, demanded)]),
                ],
            );
            let products = recovered_witness_fixtures(&[
                unused.clone(),
                baseline.clone(),
                required.clone(),
                fresh,
                extra.clone(),
            ]);
            let entries = products
                .iter()
                .map(|row| {
                    Arc::new(
                        ArtifactEntry::original(producer.sha256(), row.product.clone()).unwrap(),
                    )
                })
                .collect::<Vec<_>>();
            let unused_interface = Arc::new(ArtifactEntry::canonical(
                products[0].product.module_interface().unwrap().clone(),
            ));
            for selected in [None, Some(7), Some(9001)] {
                for grant_full in [false, true] {
                    for extra_output in [false, true] {
                        histories += 1;
                        let inventory = ArtifactInventory::default();
                        let full_baseline = inventory
                            .admit_shared(
                                &inventory.empty_view(),
                                vec![entries[0].clone(), entries[1].clone()],
                            )
                            .unwrap();
                        let full_baseline = issue_fixture_compiler_support(
                            CompilerInputProjection::from_issued_entries(&[
                                entries[0].clone(),
                                entries[1].clone(),
                            ])
                            .unwrap(),
                            full_baseline,
                        )
                        .unwrap();
                        let baseline_entries = vec![unused_interface.clone(), entries[1].clone()];
                        let baseline_view = inventory
                            .admit_recovery_selection(
                                &inventory.empty_view(),
                                baseline_entries.clone(),
                                &BTreeSet::from([NativeGroupKey {
                                    artifact: entries[1].descriptor.id,
                                    original_ordinal: 7,
                                }]),
                            )
                            .unwrap();
                        let baseline_support = issue_fixture_compiler_support(
                            CompilerInputProjection::from_issued_entries(&baseline_entries)
                                .unwrap(),
                            baseline_view,
                        )
                        .unwrap()
                        .retain_offers(
                            full_baseline
                                .native_offers()
                                .iter()
                                .filter(|offer| offer.original() == entries[1].descriptor.id)
                                .cloned(),
                        )
                        .unwrap();
                        assert!(baseline_support
                            .native_availability()
                            .rows()
                            .all(|row| row.original_owner() != products[0].product.owner()));
                        let full_required = inventory
                            .admit_shared(&inventory.empty_view(), vec![entries[2].clone()])
                            .unwrap();
                        let required_projection =
                            CompilerInputProjection::from_issued_entries(&[entries[2].clone()])
                                .unwrap();
                        let full_required = issue_fixture_compiler_support(
                            required_projection.clone(),
                            full_required,
                        )
                        .unwrap();
                        let selected_groups = selected
                            .into_iter()
                            .map(|ordinal| NativeGroupKey {
                                artifact: entries[2].descriptor.id,
                                original_ordinal: ordinal,
                            })
                            .collect::<BTreeSet<_>>();
                        let mut required_support = if grant_full {
                            // Retain this same issued Full carrier while changing only
                            // execution demand. A fresh admission would change bindings.
                            let mut graph = full_required.artifacts().capture_graph_selection();
                            let namespace = graph.namespace.clone();
                            let unused = graph
                                .roots
                                .iter()
                                .filter(|node| match node {
                                    ArtifactBindingNode::Group(group) => {
                                        !selected_groups.contains(&NativeGroupKey {
                                            artifact: group.binding.artifact(),
                                            original_ordinal: group.original_ordinal,
                                        })
                                    }
                                    ArtifactBindingNode::Artifact(_) => false,
                                })
                                .copied()
                                .collect::<Vec<_>>();
                            graph.roots.retain(|node| !unused.contains(node));
                            graph.custody_roots.extend(unused);
                            graph.custody_roots.sort();
                            graph.custody_roots.dedup();
                            let chosen = full_required
                                .artifacts()
                                .select_issued(
                                    namespace.iter().map(|binding| binding.artifact).collect(),
                                    &ExactArtifactSelection::from_recovered_graph_selection(graph),
                                )
                                .unwrap();
                            let support =
                                issue_fixture_compiler_support(required_projection.clone(), chosen)
                                    .unwrap()
                                    .retain_normalized_availability(
                                        full_required.native_availability(),
                                    )
                                    .unwrap();
                            if selected.is_none() {
                                support.for_source_owners(&BTreeSet::new()).unwrap()
                            } else {
                                support
                            }
                        } else if selected.is_some() {
                            let chosen = inventory
                                .admit_recovery_selection(
                                    &inventory.empty_view(),
                                    vec![entries[2].clone()],
                                    &selected_groups,
                                )
                                .unwrap();
                            issue_fixture_compiler_support(required_projection, chosen).unwrap()
                        } else {
                            full_required
                                .selected_interfaces()
                                .unwrap()
                                .support_for_owners(vec![entries[2].descriptor.owner.clone()])
                                .unwrap()
                                .retain_custody(full_required.artifacts())
                                .unwrap()
                        };
                        required_support = required_support
                            .retain_offers(full_required.native_offers().iter().cloned())
                            .unwrap();
                        let support = baseline_support.merge(&required_support).unwrap();
                        let context = Arc::new(
                            ExactDeclarationContext::new(&[], &[], vec![])
                                .unwrap()
                                .extend_issued_compiler_support(&support)
                                .unwrap(),
                        );
                        let before = context.artifact_view().capture_graph_selection();
                        let before_context = context.as_ref().clone();
                        let root = tempfile::tempdir().unwrap();
                        let request = ExactCompileContext::new(context.clone())
                            .prepare_compilation(&root.path().join("input"), producer_bytes)
                            .unwrap();
                        let input = request.compiler_inputs();
                        let baseline_row =
                            input.native_availability(entries[1].descriptor.id).unwrap();
                        assert!(baseline_row.permits(7));
                        assert!(!baseline_row.permits(9001));
                        assert!(input
                            .native_availability(entries[0].descriptor.id)
                            .is_none());
                        let required_row = input.native_availability(entries[2].descriptor.id);
                        for ordinal in [7, 9001] {
                            assert_eq!(
                                required_row
                                    .as_ref()
                                    .is_some_and(|row| row.permits(ordinal)),
                                grant_full || selected == Some(ordinal)
                            );
                        }
                        let operation = InventoryOperation::new(Default::default());
                        let mut selection =
                            CertifiedSourceSelection::from_compiler_inputs(input, &operation)
                                .unwrap();
                        let output_indices = if extra_output { vec![3, 4] } else { vec![3] };
                        for index in &output_indices {
                            let output = &products[*index].product;
                            selection
                                .admit_current(
                                    output.owner(),
                                    ProductOrigin::RetainedCore,
                                    output.module_interface().unwrap(),
                                    &operation,
                                )
                                .unwrap();
                            selection
                                .bind_produced_originals(
                                    &IssuedGroupCandidates::bind(Arc::from([]), &[output.clone()])
                                        .unwrap(),
                                )
                                .unwrap();
                        }
                        let physical = input
                            .artifacts()
                            .inventory()
                            .admit_shared_with_demand(
                                input.artifacts(),
                                output_indices
                                    .iter()
                                    .map(|index| entries[*index].clone())
                                    .collect(),
                                NativeArtifactDemand::ScopeInterfaces,
                            )
                            .unwrap();
                        let result = OriginalCompilerInputs::from_selection(&selection, &physical);
                        let expected = grant_full || selected == Some(demanded);
                        if !expected {
                            assert!(matches!(result, Err(CompileError::ArtifactInventory(error))
                                if matches!(error.failure,
                                    ArtifactInventoryFailure::NativeGroupUnavailable {
                                        artifact, original_ordinal,
                                    } if artifact == entries[2].descriptor.id
                                        && original_ordinal == demanded)),
                                "demanded={demanded} selected={selected:?} full={grant_full} extra={extra_output}");
                        } else {
                            accepted += 1;
                            let completed = result.unwrap_or_else(|error| panic!(
                                "demanded={demanded} selected={selected:?} full={grant_full} extra={extra_output}: {error:?}"
                            ));
                            assert!(completed
                                .issued_artifacts()
                                .selected_native_groups()
                                .iter()
                                .all(|group| output_indices
                                    .iter()
                                    .all(|index| group.artifact != entries[*index].descriptor.id)));
                            let next_request = ExactCompileContext::new(context.clone())
                                .prepare_compilation_with_private_input(
                                    &root.path().join("output"),
                                    producer_bytes,
                                    None,
                                    Some(completed),
                                )
                                .unwrap();
                            let bytes = std::fs::read(&next_request.manifest).unwrap();
                            let scope: Value = ciborium::de::from_reader(bytes.as_slice()).unwrap();
                            let scope = scope.as_array().unwrap();
                            assert_eq!(scope.len(), 11);
                            assert_eq!(scope[0], Value::Text("TPEXACTSCOPE".into()));
                            assert_eq!(scope[1], Value::Text("16".into()));
                            let mut wire_rows = BTreeMap::new();
                            for value in scope[6].as_array().unwrap() {
                                let [unit, module, _, _, _, _, ordinals, _, mode, _] =
                                    value.as_array().unwrap().as_slice()
                                else {
                                    panic!("native row has ten fields")
                                };
                                assert_eq!(unit.as_text(), Some("fixture"));
                                let ordinals = ordinals
                                    .as_array()
                                    .unwrap()
                                    .iter()
                                    .map(|ordinal| {
                                        u32::try_from(ordinal.as_integer().unwrap()).unwrap()
                                    })
                                    .collect::<Vec<_>>();
                                assert!(wire_rows
                                    .insert(
                                        module.as_text().unwrap().to_owned(),
                                        (ordinals, mode.clone())
                                    )
                                    .is_none());
                            }
                            let issued_mode = |ordinals: &[u32]| {
                                Value::Array(vec![
                                    Value::Text("issued-groups".into()),
                                    Value::Array(
                                        ordinals
                                            .iter()
                                            .map(|ordinal| Value::Integer((*ordinal).into()))
                                            .collect(),
                                    ),
                                ])
                            };
                            let full_mode = Value::Array(vec![Value::Text("full-carrier".into())]);
                            assert_eq!(
                                wire_rows["FixedRequestInput"],
                                (vec![7], issued_mode(&[7]))
                            );
                            assert_eq!(
                                wire_rows["FreshRequestOutput"],
                                (vec![], full_mode.clone())
                            );
                            assert_eq!(
                                wire_rows["VariableRequestInput"],
                                (
                                    selected.into_iter().collect::<Vec<_>>(),
                                    if grant_full {
                                        full_mode.clone()
                                    } else {
                                        issued_mode(&[demanded])
                                    },
                                )
                            );
                            if extra_output {
                                assert_eq!(
                                    wire_rows["UnrelatedRequestOutput"],
                                    (vec![], full_mode)
                                );
                            }
                            assert_eq!(wire_rows.len(), if extra_output { 4 } else { 3 });
                            let next = next_request.compiler_inputs();
                            assert_eq!(
                                next.artifacts().selected_native_groups(),
                                input.artifacts().selected_native_groups()
                            );
                            assert!(next
                                .native_availability(entries[1].descriptor.id)
                                .unwrap()
                                .permits(7));
                            assert!(!next
                                .native_availability(entries[1].descriptor.id)
                                .unwrap()
                                .permits(9001));
                            assert!(next.native_availability(entries[0].descriptor.id).is_none());
                            let required =
                                next.native_availability(entries[2].descriptor.id).unwrap();
                            for ordinal in [7, 9001] {
                                assert_eq!(
                                    required.permits(ordinal),
                                    grant_full || selected == Some(ordinal)
                                );
                            }
                            let facts =
                                next.private_native_availability().snapshot_facts().unwrap();
                            assert_eq!(
                                facts[&entries[1].descriptor.id].mode,
                                NativeTransportMode::IssuedGroups
                            );
                            assert_eq!(
                                facts[&entries[2].descriptor.id].mode == NativeTransportMode::Full,
                                grant_full
                            );
                            for index in &output_indices {
                                assert_eq!(
                                    facts[&entries[*index].descriptor.id].mode,
                                    NativeTransportMode::Full
                                );
                            }
                            assert_eq!(facts.contains_key(&entries[4].descriptor.id), extra_output);
                        }
                        assert_eq!(context.artifact_view().capture_graph_selection(), before);
                        assert_eq!(context.as_ref(), &before_context);
                        assert_eq!(request.context().as_ref(), &before_context);
                    }
                }
            }
        }
        assert_eq!(histories, 24);
        assert_eq!(accepted, 16);
        eprintln!(
            "two_input_request_histories={histories} accepted={accepted} refused={}",
            histories - accepted
        );
    }

    #[test]
    fn completed_request_preserves_selected_issuer_beside_historical_offer() {
        use crate::artifact_inventory::{
            ArtifactEntry, ArtifactInventory, ArtifactInventoryFailure, ArtifactPayload,
            ArtifactView, CanonicalProducerIdentity, CompilerInputProjection, IssuedNativeOffer,
            NativeArtifactDemand, NativeGroupKey, NativeOriginalRequirement,
        };
        use crate::declaration_context::{
            issue_fixture_compiler_support, ExactCompileContext, ExactDeclarationContext,
            OriginalCompilerInputs,
        };
        use crate::CompileError;
        use std::path::PathBuf;
        const PRODUCER: &[u8] = b"request-selected-issuer-history";
        let product = |module: &str, version| {
            let raw = fixture_finalized_product(
                original_groups_fixture_with_interface(
                    module,
                    vec![(7, vec![]), (9001, vec![])],
                    version,
                    &BTreeMap::new(),
                    module.as_bytes().to_vec(),
                ),
                CanonicalProducerIdentity::from_producer_bytes(PRODUCER).sha256(),
            );
            recovered_witness_fixtures(&[raw]).remove(0).product
        };

        for shared_carrier in [false, true] {
            let producer = CanonicalProducerIdentity::from_producer_bytes(PRODUCER);
            let native = product("SelectedIssuerHistory", 131);
            let entry =
                Arc::new(ArtifactEntry::original(producer.sha256(), native.clone()).unwrap());
            let projection =
                CompilerInputProjection::from_issued_entries(&[entry.clone()]).unwrap();
            let inventory = ArtifactInventory::default();
            let carrier = if shared_carrier {
                inventory
                    .admit_shared_with_demand(
                        &inventory.empty_view(),
                        vec![entry.clone()],
                        NativeArtifactDemand::ScopeInterfaces,
                    )
                    .unwrap()
            } else {
                inventory.empty_view()
            };
            let issue = |marker, version| {
                let view = inventory
                    .admit_recovery_selection(
                        &carrier,
                        vec![
                            entry.clone(),
                            Arc::new(ArtifactEntry::canonical(
                                product(marker, version).module_interface().unwrap().clone(),
                            )),
                        ],
                        &BTreeSet::from([7, 9001].map(|original_ordinal| NativeGroupKey {
                            artifact: entry.descriptor.id,
                            original_ordinal,
                        })),
                    )
                    .unwrap();
                let proof =
                    NativeOriginalRequirement::from_selected_view(entry.descriptor.id, &view)
                        .unwrap()
                        .expect("the actual issuer selected native groups");
                let offer =
                    IssuedNativeOffer::issue(entry.descriptor.id, &view, Some(proof)).unwrap();
                assert!(offer.is_full());
                (view, offer)
            };
            let (left, a) = issue("HistoricalIssuerA", 132);
            let (right, b) = issue("CurrentIssuerB", 133);
            let exact_groups = |view: &ArtifactView| {
                view.capture_graph_selection()
                    .roots
                    .into_iter()
                    .filter_map(|node| match node {
                        crate::artifact_inventory::ArtifactBindingNode::Group(group)
                            if group.binding.artifact() == entry.descriptor.id =>
                        {
                            Some(group)
                        }
                        _ => None,
                    })
                    .collect::<BTreeSet<_>>()
            };
            let a_groups = exact_groups(&left);
            let b_groups = exact_groups(&right);
            assert_eq!(a_groups.len(), 2);
            assert_eq!(b_groups.len(), 2);
            assert!(a_groups.is_disjoint(&b_groups));
            for id in [
                entry.descriptor.id,
                ArtifactEntry::canonical(native.module_interface().unwrap().clone())
                    .descriptor
                    .id,
            ] {
                let binding = |view: &ArtifactView| {
                    view.capture_graph_selection()
                        .namespace
                        .into_iter()
                        .find(|binding| binding.artifact == id)
                        .unwrap()
                };
                assert_eq!(binding(&left) == binding(&right), shared_carrier);
            }
            let mut binder = testing::identity(&native.owner().module, "entry_7");
            binder.unit = native.owner().unit.clone();
            let parent = fixture_finalized_product(
                original_groups_fixture_with_interface(
                    "HistoricalDependencyParent",
                    vec![(
                        7,
                        vec![PendingImportOwner::Source {
                            owner: native.owner().clone(),
                            original_ordinal: 7,
                            binder,
                        }],
                    )],
                    134,
                    &BTreeMap::new(),
                    b"historical parent interface".to_vec(),
                ),
                producer.sha256(),
            );
            let parent = recovered_witness_fixtures(&[native.clone(), parent])
                .remove(1)
                .product;
            let parent_entry =
                Arc::new(ArtifactEntry::original(producer.sha256(), parent).unwrap());
            let support = issue_fixture_compiler_support(projection.clone(), left.clone())
                .unwrap()
                .retain_offers([a.clone()])
                .unwrap();
            let parent_context = Arc::new(
                ExactDeclarationContext::new(&[], &[], vec![])
                    .unwrap()
                    .extend_issued_compiler_support(&support)
                    .unwrap(),
            );
            let parent_root = tempfile::tempdir().unwrap();
            let parent_request = ExactCompileContext::new(parent_context.clone())
                .prepare_compilation(parent_root.path(), PRODUCER)
                .unwrap();
            let operation = InventoryOperation::new(Default::default());
            let mut selection = CertifiedSourceSelection::from_compiler_inputs(
                parent_request.compiler_inputs(),
                &operation,
            )
            .unwrap();
            let ArtifactPayload::Original(parent_product) = &parent_entry.payload else {
                unreachable!()
            };
            selection
                .admit_current(
                    parent_product.owner(),
                    ProductOrigin::RetainedCore,
                    parent_product.module_interface().unwrap(),
                    &operation,
                )
                .unwrap();
            selection
                .bind_produced_originals(
                    &IssuedGroupCandidates::bind(Arc::from([]), &[parent_product.clone()]).unwrap(),
                )
                .unwrap();
            let physical = parent_request
                .compiler_inputs()
                .artifacts()
                .inventory()
                .admit_shared_with_demand(
                    parent_request.compiler_inputs().artifacts(),
                    vec![parent_entry.clone()],
                    NativeArtifactDemand::ScopeInterfaces,
                )
                .unwrap();
            let parent_input =
                OriginalCompilerInputs::from_selection(&selection, &physical).unwrap();
            assert_eq!(
                parent_input.issued_artifacts().selected_native_groups(),
                parent_request
                    .compiler_inputs()
                    .artifacts()
                    .selected_native_groups()
            );
            let parent_offer = parent_input
                .native_offers()
                .iter()
                .find(|offer| offer.original() == parent_entry.descriptor.id)
                .unwrap()
                .clone();
            let groups = parent_offer.issued_group_carriers().unwrap();
            let parent_group = *groups
                .keys()
                .find(|group| {
                    group.binding.artifact() == parent_entry.descriptor.id
                        && group.original_ordinal == 7
                })
                .unwrap();
            let historical_child = *a_groups
                .iter()
                .find(|group| group.original_ordinal == 7)
                .unwrap();
            let historical_edge = (
                crate::artifact_inventory::ArtifactBindingNode::Group(parent_group),
                crate::artifact_inventory::ArtifactBindingNode::Group(historical_child),
                crate::artifact_inventory::ArtifactDependency::NativeGroup {
                    dependent_ordinal: 7,
                    required_ordinal: 7,
                },
            );
            assert!(parent_offer
                .custody_snapshot()
                .binding_dependencies()
                .unwrap()
                .contains(&historical_edge));
            assert!(!b_groups.contains(&historical_child));
            let support =
                issue_fixture_compiler_support(projection.clone(), right.clone()).unwrap();
            let original_graph = support.artifacts().capture_graph_selection();
            let assert_retained_offer =
                |stage: &str,
                 case: usize,
                 support: &crate::artifact_inventory::CompilerSourceSupport,
                 expected: &IssuedNativeOffer| {
                    let retained = support
                        .native_offers()
                        .iter()
                        .find(|retained| retained.same_issuance(expected))
                        .unwrap_or_else(|| {
                            let actual = support.native_offers().iter()
                                .map(|offer| (offer.original(), offer.is_full()))
                                .collect::<Vec<_>>();
                            panic!("same opaque issuance missing: stage={stage} case={case} shared_carrier={shared_carrier} expected_original={:?} expected_full={} actual={actual:?}", expected.original(), expected.is_full());
                        });
                    assert_eq!(
                        retained.custody_snapshot().binding_dependencies().unwrap(),
                        expected.custody_snapshot().binding_dependencies().unwrap()
                    );
                };
            let fresh = product("FreshAlongsideSelectedIssuer", 135);
            for (case, (extra, mixed_fresh)) in [
                (vec![b.clone()], false),
                (vec![a.clone(), b.clone()], false),
                (vec![b.clone(), a.clone()], false),
                (vec![a.clone(), b.clone(), parent_offer.clone()], false),
                (vec![a.clone(), b.clone(), parent_offer.clone()], true),
                (vec![b.clone(), a.clone()], true),
            ]
            .into_iter()
            .enumerate()
            {
                let includes_a = extra.iter().any(|offer| offer == &a);
                let includes_parent = extra.iter().any(|offer| offer == &parent_offer);
                let carried = support.retain_offers(extra).unwrap();
                let graph = carried.artifacts().capture_graph_selection();
                assert_eq!(
                    graph.roots, original_graph.roots,
                    "adding availability cannot change selected demand"
                );
                assert_eq!(
                    graph.namespace, original_graph.namespace,
                    "adding availability cannot change selected namespace"
                );
                assert_eq!(exact_groups(carried.artifacts()), b_groups);
                if includes_parent {
                    assert_retained_offer("carried-parent", case, &carried, &parent_offer);
                    assert!(parent_offer
                        .custody_snapshot()
                        .binding_dependencies()
                        .unwrap()
                        .contains(&historical_edge));
                }
                if includes_a {
                    assert_retained_offer("carried-historical", case, &carried, &a);
                }
                assert_eq!(
                    NativeOriginalRequirement::from_selected_view(
                        entry.descriptor.id,
                        carried.artifacts()
                    )
                    .unwrap()
                    .as_ref(),
                    b.proof()
                );
                let context = Arc::new(
                    ExactDeclarationContext::new(&[], &[], vec![])
                        .unwrap()
                        .extend_issued_compiler_support(&carried)
                        .unwrap(),
                );
                let baseline_root = tempfile::tempdir().unwrap();
                let baseline = ExactCompileContext::new(context.clone())
                .prepare_compilation(baseline_root.path(), PRODUCER)
                .expect(
                    "independently selected B remains valid with A only in availability custody",
                );
                assert_eq!(
                    exact_groups(baseline.compiler_inputs().artifacts()),
                    b_groups
                );
                let candidates = crate::module_candidates::CandidateSet {
                    manifest_path: PathBuf::from("native-issuance-does-not-read-manifest"),
                    by_owner: BTreeMap::new(),
                    contextual_native_availability: if mixed_fresh {
                        vec![native.clone(), fresh.clone()]
                    } else {
                        vec![native.clone()]
                    },
                    catalog_owner: None,
                    input_transport: Vec::new(),
                };
                let reused =
                    OriginalCompilerInputs::from_candidates(&context, producer, &candidates)
                        .expect(
                            "reusing a candidate cannot promote historical A into a second root",
                        )
                        .unwrap();
                assert_eq!(
                    exact_groups(reused.issued_artifacts()),
                    b_groups,
                    "candidate fragment preserves the receiver's independently selected B roots"
                );
                let root = tempfile::tempdir().unwrap();
                let request = ExactCompileContext::new(context)
                    .prepare_compilation_with_private_input(
                        root.path(),
                        PRODUCER,
                        None,
                        Some(reused),
                    )
                    .unwrap();
                assert_eq!(
                    exact_groups(request.compiler_inputs().artifacts()),
                    b_groups
                );
                assert_eq!(
                    request
                        .compiler_inputs()
                        .artifacts()
                        .selected_native_groups()
                        .len(),
                    2,
                    "fresh availability cannot add executable demand beside selected B"
                );
                if includes_a {
                    assert_retained_offer(
                        "request-historical",
                        case,
                        request.compiler_inputs().compiler_source_support(),
                        &a,
                    );
                }
                if includes_parent {
                    assert!(
                        request
                            .compiler_inputs()
                            .artifacts()
                            .capture_graph_selection()
                            .roots
                            .iter()
                            .all(|node| match node {
                                crate::artifact_inventory::ArtifactBindingNode::Group(group) =>
                                    group.binding.artifact() != parent_entry.descriptor.id,
                                crate::artifact_inventory::ArtifactBindingNode::Artifact(
                                    binding,
                                ) => binding.artifact != parent_entry.descriptor.id,
                            }),
                        "historical parent availability cannot become a current root"
                    );
                    assert_retained_offer(
                        "request-parent",
                        case,
                        request.compiler_inputs().compiler_source_support(),
                        &parent_offer,
                    );
                    assert!(
                    parent_offer
                        .custody_snapshot()
                        .binding_dependencies()
                        .unwrap()
                        .contains(&historical_edge),
                    "historical parent retains its exact child without becoming selected demand"
                );
                }
            }
            // Two actual selected decision owners conflict; broader offer custody alone
            // does not create a second selected choice.
            let input_b = support
                .native_offers()
                .iter()
                .find(|offer| *offer == &b)
                .unwrap()
                .clone();
            assert_eq!(input_b, b);
            assert_eq!(
                input_b.issued_group_carriers().unwrap(),
                b.issued_group_carriers().unwrap()
            );
            assert!(
                !input_b.same_issuance(&b),
                "recovery checked the same B proof through its own input issuer"
            );
            let left_support =
                issue_fixture_compiler_support(projection.clone(), left.clone()).unwrap();
            let joined = left_support.merge(&support);
            if shared_carrier {
                assert!(matches!(joined, Err(CompileError::ArtifactInventory(error))
                if matches!(error.failure, ArtifactInventoryFailure::BindingAmbiguity { artifact }
                    if artifact == entry.descriptor.id)));
            } else {
                let joined = joined.unwrap();
                assert_eq!(exact_groups(joined.artifacts()), a_groups);
                assert_eq!(
                    joined.artifacts().capture_graph_selection().namespace,
                    left_support.artifacts().capture_graph_selection().namespace
                );
                assert_eq!(
                    joined.input_decisions().recorded_facts(),
                    left_support.input_decisions().recorded_facts()
                );
                assert_retained_offer("joined-current", 6, &joined, &input_b);
            }
            assert_eq!(
                right
                    .selected_native_groups()
                    .into_iter()
                    .collect::<BTreeSet<_>>(),
                BTreeSet::from([
                    NativeGroupKey {
                        artifact: entry.descriptor.id,
                        original_ordinal: 7
                    },
                    NativeGroupKey {
                        artifact: entry.descriptor.id,
                        original_ordinal: 9001
                    }
                ])
            );
            let selected_fragment = |view: ArtifactView| {
                let issued = issue_fixture_compiler_support(projection.clone(), view).unwrap();
                let context = ExactDeclarationContext::new(&[], &[], vec![])
                    .unwrap()
                    .extend_issued_compiler_support(&issued)
                    .unwrap();
                let candidates = crate::module_candidates::CandidateSet {
                    manifest_path: PathBuf::from("selected-fragment-native-issuance-only"),
                    by_owner: BTreeMap::new(),
                    contextual_native_availability: vec![native.clone()],
                    catalog_owner: None,
                    input_transport: Vec::new(),
                };
                OriginalCompilerInputs::from_candidates(&context, producer, &candidates)
                    .unwrap()
                    .unwrap()
            };
            let explicit_a = selected_fragment(left);
            let explicit_b = selected_fragment(right);
            assert_ne!(
                explicit_a
                    .issued_input_decisions()
                    .map(|decisions| decisions.recorded_facts()),
                explicit_b
                    .issued_input_decisions()
                    .map(|decisions| decisions.recorded_facts()),
                "selected demand identity includes exact scoped issuer choices"
            );
            for (left, right) in [(&explicit_a, &explicit_b), (&explicit_b, &explicit_a)] {
                let selected =
                    crate::artifact_inventory::CompilerSourceSupport::close_complete_output(left)
                        .unwrap();
                let context = Arc::new(
                    ExactDeclarationContext::new(&[], &[], vec![])
                        .unwrap()
                        .extend_issued_compiler_support(&selected)
                        .unwrap(),
                );
                let root = tempfile::tempdir().unwrap();
                let result = ExactCompileContext::new(context)
                    .prepare_compilation_with_private_input(
                        root.path(),
                        PRODUCER,
                        None,
                        Some(right.clone()),
                    );
                if shared_carrier {
                    assert!(
                        matches!(result, Err(CompileError::ArtifactInventory(error))
                    if matches!(error.failure, ArtifactInventoryFailure::BindingAmbiguity { artifact }
                        if artifact == entry.descriptor.id)),
                        "two choices over one selected carrier must refuse in either order"
                    );
                } else {
                    let request = result.unwrap();
                    assert_eq!(
                        exact_groups(request.compiler_inputs().artifacts()),
                        exact_groups(left.issued_artifacts())
                    );
                    assert_eq!(
                        request
                            .compiler_inputs()
                            .artifacts()
                            .capture_graph_selection()
                            .namespace,
                        left.issued_artifacts().capture_graph_selection().namespace
                    );
                }
            }
        }
    }

    #[test]
    fn completed_request_retained_generation_history_uses_exact_input_permissions() {
        use crate::artifact_inventory::{
            ArtifactBindingNode, ArtifactEntry, ArtifactInventory, CanonicalProducerIdentity,
            CompilerInputProjection, ExactArtifactSelection, IssuedNativeOffer,
            NativeArtifactDemand, NativeGroupKey, NativeOriginalRequirement,
        };
        use crate::declaration_context::{
            issue_fixture_compiler_support, recover_fixture_compiler_support, ExactCompileContext,
            ExactDeclarationContext, OriginalCompilerInputs, RequestNativeAvailability,
            RetainedGenerationPolicy,
        };
        let producer_bytes = b"request-retained-generations";
        let producer = CanonicalProducerIdentity::from_producer_bytes(producer_bytes);
        let retained = |generation: u64, occurrence: &str| SymbolIdentity {
            unit: "main".into(),
            module: format!("Tidepool.Session.Val.G{generation}"),
            namespace: "value".into(),
            occurrence: occurrence.into(),
            record_parent: None,
        };
        let generation_one = retained(1, "x");
        let generation_two = retained(2, "y");
        let raw = fixture_finalized_product(
            original_groups_fixture_with_interface(
                "RequestRetainedBody",
                vec![
                    (
                        7,
                        vec![PendingImportOwner::Retained {
                            identity: generation_two.clone(),
                            generation: 2,
                        }],
                    ),
                    (
                        9001,
                        vec![PendingImportOwner::Retained {
                            identity: generation_one.clone(),
                            generation: 1,
                        }],
                    ),
                ],
                36,
                &BTreeMap::new(),
                b"retained request interface".to_vec(),
            ),
            producer.sha256(),
        );
        let product = recovered_witness_fixtures(&[raw]).remove(0).product;
        let original =
            Arc::new(ArtifactEntry::original(producer.sha256(), product.clone()).unwrap());
        let mut interfaces = Vec::new();
        interfaces.extend(
            [&generation_one, &generation_two]
                .into_iter()
                .map(|binder| {
                    Arc::new(ArtifactEntry::canonical(fixture_module_interface(
                        producer.sha256(),
                        &binder.unit,
                        &binder.module,
                        BTreeMap::new(),
                    )))
                }),
        );
        let inventory = ArtifactInventory::default();
        let view = inventory
            .admit_shared(&inventory.empty_view(), interfaces.clone())
            .unwrap();
        let support = issue_fixture_compiler_support(
            CompilerInputProjection::from_issued_entries(&interfaces).unwrap(),
            view,
        )
        .unwrap();
        let context = Arc::new(
            ExactDeclarationContext::new(&[], &[], vec![])
                .unwrap()
                .extend_issued_compiler_support(&support)
                .unwrap(),
        );
        let before = context.artifact_view().capture_graph_selection();
        assert!(
            !context
                .compiler_input_projection()
                .snapshot_roles()
                .contains_key(&original.descriptor.owner),
            "C is a genuine new output, not a current Input interface"
        );
        let root = tempfile::tempdir().unwrap();
        let request = ExactCompileContext::new(context.clone())
            .prepare_compilation(&root.path().join("input"), producer_bytes)
            .unwrap();
        let input = request.compiler_inputs();
        let operation = InventoryOperation::new(Default::default());
        let mut selection =
            CertifiedSourceSelection::from_compiler_inputs(input, &operation).unwrap();
        selection
            .admit_current(
                product.owner(),
                ProductOrigin::RetainedCore,
                product.module_interface().unwrap(),
                &operation,
            )
            .unwrap();
        selection
            .bind_produced_originals(
                &IssuedGroupCandidates::bind(Arc::from([]), &[product.clone()]).unwrap(),
            )
            .unwrap();
        let physical = input
            .artifacts()
            .inventory()
            .admit_shared_with_demand(
                input.artifacts(),
                vec![original.clone()],
                NativeArtifactDemand::ScopeInterfaces,
            )
            .unwrap();
        let completed = OriginalCompilerInputs::from_selection(&selection, &physical).unwrap();
        assert!(
            matches!(completed.role_projection().snapshot_roles()[&original.descriptor.owner],
            crate::artifact_inventory::CompilerInputRole::InterfaceOnly { interface }
                if interface == ArtifactEntry::canonical(product.module_interface().unwrap().clone()).descriptor.id),
            "RetainedCore availability does not select a compiler Original"
        );
        assert_eq!(
            completed.native_availability().snapshot_facts().unwrap()[&original.descriptor.id].mode,
            crate::declaration_context::NativeTransportMode::Full
        );
        let closed =
            crate::artifact_inventory::CompilerSourceSupport::close_complete_output(&completed)
                .unwrap();
        let full = closed
            .native_offers()
            .iter()
            .find(|offer| offer.original() == original.descriptor.id)
            .unwrap()
            .clone();
        assert!(full.is_full());
        assert!(closed.artifacts().selected_native_groups().is_empty());
        let input_roles = closed
            .projection()
            .merge(&CompilerInputProjection::from_issued_entries(&[original.clone()]).unwrap())
            .unwrap();
        let catalog =
            crate::artifact_inventory::NativeDependencyCatalog::from_source(&closed).unwrap();
        let selected_input = input_roles
            .admit_interfaces_with_native_offers(
                closed.artifacts(),
                vec![original.clone()],
                closed.native_offers(),
                &catalog,
            )
            .unwrap();
        let input_graph = selected_input.capture_graph_selection();
        let canonical_id = ArtifactEntry::canonical(product.module_interface().unwrap().clone())
            .descriptor
            .id;
        assert_eq!(
            input_roles.snapshot_roles()[&original.descriptor.owner].original(),
            Some(original.descriptor.id)
        );
        assert_eq!(
            input_graph
                .namespace
                .iter()
                .find(|binding| binding.artifact == canonical_id),
            closed
                .artifacts()
                .capture_graph_selection()
                .namespace
                .iter()
                .find(|binding| binding.artifact == canonical_id)
        );
        let carriers = full
            .issued_group_carriers()
            .unwrap()
            .into_iter()
            .filter_map(|(group, carrier)| {
                (group.binding.artifact() == original.descriptor.id).then_some(carrier)
            })
            .collect::<BTreeSet<_>>();
        assert_eq!(carriers.len(), 1);
        assert_eq!(
            input_graph
                .namespace
                .iter()
                .find(|binding| binding.artifact == original.descriptor.id),
            carriers.first()
        );
        assert!(selected_input.selected_native_groups().is_empty());
        let partial = selected_input
            .inventory()
            .admit_recovery_selection(
                &selected_input,
                selected_input.entries(),
                &BTreeSet::from([NativeGroupKey {
                    artifact: original.descriptor.id,
                    original_ordinal: 7,
                }]),
            )
            .unwrap();
        let partial_offer = IssuedNativeOffer::issue(
            original.descriptor.id,
            &partial,
            Some(
                NativeOriginalRequirement::from_selected_view(original.descriptor.id, &partial)
                    .unwrap()
                    .unwrap(),
            ),
        )
        .unwrap();
        assert!(!partial_offer.is_full());
        let empty = selected_input.clone();
        let empty_offer = IssuedNativeOffer::issue(original.descriptor.id, &empty, None).unwrap();
        for (label, view, offer, expected_one, expected_two) in [
            ("full", selected_input, full, Some(1), Some(2)),
            ("partial", partial, partial_offer, None, Some(2)),
            ("empty", empty, empty_offer, None, None),
        ] {
            let availability = RequestNativeAvailability::issue_checked(
                &input_roles,
                &view,
                std::slice::from_ref(&offer),
            )
            .unwrap();
            let row = availability
                .rows()
                .find(|row| row.original_owner() == product.owner())
                .unwrap_or_else(|| {
                    let observed = availability.rows().map(|row| (
                        row.target_original(row.original_owner()).unwrap().descriptor.id,
                        row.original_owner().clone(), row.permits(7), row.permits(9001),
                    )).collect::<Vec<_>>();
                    panic!("retained generation native row missing: label={label} owner={:?} original={:?} roles={:?} observed={observed:?}", product.owner(), original.descriptor.id, input_roles.snapshot_roles());
                });
            assert_eq!(row.permits(7), expected_two.is_some(), "{label}");
            assert_eq!(row.permits(9001), expected_one.is_some(), "{label}");
            let mut graph = view.capture_graph_selection();
            let namespace = graph.namespace.clone();
            let execution = graph
                .roots
                .iter()
                .filter(|root| matches!(root, ArtifactBindingNode::Group(_)))
                .copied()
                .collect::<Vec<_>>();
            graph.roots.retain(|root| !execution.contains(root));
            graph.custody_roots.extend(execution);
            graph.custody_roots.sort();
            graph.custody_roots.dedup();
            let view = view
                .select_issued(
                    namespace.iter().map(|binding| binding.artifact).collect(),
                    &ExactArtifactSelection::from_recovered_graph_selection(graph),
                )
                .unwrap();
            let support = recover_fixture_compiler_support(input_roles.clone(), view, [offer])
                .unwrap()
                .retain_normalized_availability(&availability)
                .unwrap()
                .for_source_owners(&BTreeSet::new())
                .unwrap();
            assert!(support
                .projection()
                .roles()
                .iter()
                .all(|role| role.original().is_none()));
            assert!(support.artifacts().selected_native_groups().is_empty());
            let private = OriginalCompilerInputs::from_issued_support(&support);
            let request = ExactCompileContext::new(context.clone())
                .prepare_compilation_with_private_input(
                    &root.path().join(label),
                    producer_bytes,
                    None,
                    Some(private),
                )
                .unwrap();
            assert!(request.groups.is_empty(), "{label}");
            assert!(request
                .compiler_inputs()
                .artifacts()
                .selected_native_groups()
                .is_empty());
            for (policy, expected) in [
                (
                    RetainedGenerationPolicy::PreserveCertifiedDemand,
                    [expected_one, expected_two],
                ),
                (
                    RetainedGenerationPolicy::PureActivationPreview,
                    [None, None],
                ),
            ] {
                let mut command = tidepool_extract_cmd::ExtractCmd::with_bin(
                    tidepool_extract_cmd::ResolvedExtractBin::assume_resolved(
                        "unused-fixture-extractor",
                    ),
                );
                command.input("unused-fixture-input.hs");
                request.apply_to(&mut command, policy).unwrap();
                let decoded =
                    tidepool_extract_cmd::ExtractRequest::decode(&command.request_bytes()).unwrap();
                for (identity, expected) in
                    [&generation_one, &generation_two].into_iter().zip(expected)
                {
                    let key = tidepool_extract_cmd::SymbolIdentity {
                        unit: identity.unit.clone(),
                        module: identity.module.clone(),
                        namespace: identity.namespace.clone(),
                        occurrence: identity.occurrence.clone(),
                        record_parent: identity.record_parent.clone(),
                    };
                    assert_eq!(
                        decoded.retained_generations().get(&key).copied(),
                        expected,
                        "{label}"
                    );
                }
                if matches!(policy, RetainedGenerationPolicy::PureActivationPreview) {
                    assert!(decoded.retained_generations().is_empty());
                }
            }
            assert_eq!(context.artifact_view().capture_graph_selection(), before);
        }
    }

    #[test]
    #[ignore = "requires the matched Haskell worker and frontend"]
    fn compiled_new_output_refuses_absent_input_native_permission() {
        use crate::artifact_inventory::{
            ArtifactBindingNode, ArtifactDependency, ArtifactEntry, ArtifactInventory,
            ArtifactInventoryFailure, CanonicalProducerIdentity, CompilerInputProjection,
            CompilerInputRole, IssuedNativeOffer, NativeArtifactDemand,
        };
        use crate::declaration_context::{
            issue_fixture_compiler_support, recover_fixture_compiler_support, ExactCompileContext,
            ExactDeclarationContext, NativeTransportMode, OriginalCompilerInputs,
            RequestNativeAvailability,
        };
        use crate::declaration_join::ExactModuleIdentity;
        use crate::CompileError;
        let directory = tempfile::tempdir().unwrap();
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let root = directory.path();
            let module = tidepool_repr::SessionModule::lib(tidepool_repr::Generation(1));
            let source = include_str!("../tests/fixtures/checked-prefix-publication/G1.hs");
            let support_source = include_str!(
                "../tests/fixtures/checked-prefix-publication/PrefixSelectedSupport.hs"
            );
            let source_path = root.join(module.relative_hs_path());
            std::fs::create_dir_all(source_path.parent().unwrap()).unwrap();
            std::fs::write(&source_path, source).unwrap();
            std::fs::write(root.join("PrefixSelectedSupport.hs"), support_source).unwrap();
            let includes = vec![root.to_path_buf()];
            let certificate = crate::artifacts::test_support::certify_authored_declaration(
                module,
                &source_path,
                source,
                &includes,
                root,
            )
            .expect("actual compiler issues C with its exact Support A dependency");
            let (endpoint, _) = crate::toolchain::bind_extract_endpoint().unwrap();
            let producer = CanonicalProducerIdentity::from_compiler(endpoint.identity());
            assert_eq!(certificate.toolchain_identity_sha256(), producer.sha256());
            let support_owner = ExactModuleIdentity {
                unit: "main".into(),
                module: "PrefixSelectedSupport".into(),
            };
            let products = certificate.recovery_products();
            let supports = products
                .iter()
                .filter(|product| {
                    product.owner().unit == support_owner.unit
                        && product.owner().module == support_owner.module
                })
                .collect::<Vec<_>>();
            assert_eq!(supports.len(), 1);
            let support_product = supports[0];
            let output_product = certificate.product();
            assert_ne!(output_product.owner(), support_product.owner());
            let support_entry = Arc::new(
                ArtifactEntry::original(producer.sha256(), support_product.clone()).unwrap(),
            );
            let output_entry = Arc::new(
                ArtifactEntry::original(producer.sha256(), output_product.clone()).unwrap(),
            );
            let canonical_support = Arc::new(ArtifactEntry::canonical(
                support_product.module_interface().unwrap().clone(),
            ));
            assert!(output_entry.requirements.contains(&support_owner));
            let mut required = BTreeSet::new();
            let mut required_edges = Vec::new();
            for group in original_available_groups(output_product).unwrap() {
                for import in
                    original_native_group_imports(output_product, group.original_ordinal()).unwrap()
                {
                    if let ReceiptImportOwner::Source {
                        unit,
                        module,
                        module_version,
                        original_ordinal,
                        binder,
                    } = import
                    {
                        if unit == &support_product.owner().unit
                            && module == &support_product.owner().module
                            && module_version.as_ref()
                                == Some(&support_product.owner().module_version)
                        {
                            assert!(authenticates_original_native_entry(
                                support_product,
                                *original_ordinal,
                                binder
                            ));
                            required.insert(*original_ordinal);
                            required_edges.push((
                                group.original_ordinal(),
                                *original_ordinal,
                                binder.clone(),
                            ));
                        }
                    }
                }
            }
            assert_eq!(
                required.len(),
                1,
                "actual compiled C has one exact required A ordinal"
            );
            assert!(!required_edges.is_empty());
            let required_ordinal = *required.first().unwrap();
            assert!(required_edges
                .iter()
                .any(|(_, _, binder)| binder.occurrence == "selected"));
            let inventory = ArtifactInventory::default();
            let interface_view = inventory
                .admit_shared_with_demand(
                    &inventory.empty_view(),
                    vec![canonical_support.clone()],
                    NativeArtifactDemand::ScopeInterfaces,
                )
                .unwrap();
            let type_only = issue_fixture_compiler_support(
                CompilerInputProjection::from_issued_entries(&[canonical_support.clone()]).unwrap(),
                interface_view,
            )
            .unwrap();
            assert!(type_only.native_offers().is_empty());
            assert!(type_only.native_availability().rows().next().is_none());
            // A is an independently compiled closed support module. Self-group
            // edges are its own body, while foreign home/live dependencies would
            // require another actual input issuer and must fail this premise.
            assert!(support_entry.requirements.is_empty());
            let requirements = original_native_requirements(support_product).unwrap();
            assert!(requirements
                .artifact_edges
                .iter()
                .all(|(owner, edge)| owner == &support_owner
                    && matches!(edge, ArtifactDependency::NativeGroup { .. })));
            let support_view = inventory
                .admit_shared_with_demand(
                    &inventory.empty_view(),
                    vec![support_entry.clone()],
                    NativeArtifactDemand::ScopeInterfaces,
                )
                .unwrap();
            let support_projection =
                CompilerInputProjection::from_issued_entries(&[support_entry.clone()]).unwrap();
            let support_selection = CertifiedSourceSelection::from_compiler_projection(
                &support_projection,
                &support_view.metadata_snapshot(),
                &InventoryOperation::new(Default::default()),
            )
            .unwrap();
            let support_output =
                OriginalCompilerInputs::from_selection(&support_selection, &support_view).unwrap();
            let issued_view = support_output.issued_artifacts();
            let issued_graph = issued_view.capture_graph_selection();
            let empty_offer =
                IssuedNativeOffer::issue(support_entry.descriptor.id, issued_view, None).unwrap();
            let empty_rows = RequestNativeAvailability::issue_checked(
                support_output.role_projection(),
                issued_view,
                std::slice::from_ref(&empty_offer),
            )
            .unwrap();
            let empty_support = recover_fixture_compiler_support(
                support_output.role_projection().clone(),
                issued_view.clone(),
                [empty_offer],
            )
            .unwrap()
            .retain_normalized_availability(&empty_rows)
            .unwrap()
            .for_source_owners(&BTreeSet::new())
            .unwrap();
            assert_eq!(empty_support.projection(), type_only.projection());
            let issued_a_binding = *issued_graph
                .namespace
                .iter()
                .find(|binding| binding.artifact == support_entry.descriptor.id)
                .unwrap();
            let empty_graph = empty_support.artifacts().capture_graph_selection();
            assert!(empty_graph.bindings.contains(&issued_a_binding));
            assert_eq!(empty_graph.namespace, issued_graph.namespace);
            assert!(empty_support
                .artifacts()
                .artifact_ids()
                .contains(&support_entry.descriptor.id));
            let empty_row = empty_support
                .native_availability()
                .rows()
                .find(|row| row.original_owner() == support_product.owner())
                .unwrap();
            assert!(!empty_row.permits(required_ordinal));
            assert_eq!(
                empty_support
                    .native_availability()
                    .snapshot_facts()
                    .unwrap()[&support_entry.descriptor.id]
                    .mode,
                NativeTransportMode::IssuedGroups
            );
            assert!(empty_support
                .native_offers()
                .iter()
                .all(|offer| !offer.is_full()));
            assert!(empty_support
                .artifacts()
                .selected_native_groups()
                .is_empty());
            let issued_support =
                crate::artifact_inventory::CompilerSourceSupport::close_complete_output(
                    &support_output,
                )
                .unwrap()
                .for_source_owners(&BTreeSet::new())
                .unwrap();
            assert_eq!(issued_support.projection().roles().len(), 1);
            for (label, support, expected) in [
                ("empty", empty_support, false),
                ("issued", issued_support, true),
            ] {
                let context = Arc::new(
                    ExactDeclarationContext::new(&[], &[], vec![])
                        .unwrap()
                        .extend_issued_compiler_support(&support)
                        .unwrap(),
                );
                let roles = context.compiler_input_projection().snapshot_roles();
                assert!(
                    matches!(roles[&support_owner], CompilerInputRole::InterfaceOnly { interface }
                    if interface == canonical_support.descriptor.id)
                );
                assert!(!roles.contains_key(&output_entry.descriptor.owner));
                assert!(context.artifact_view().selected_native_groups().is_empty());
                let before = context.artifact_view().capture_graph_selection();
                let request = ExactCompileContext::new(context.clone())
                    .prepare_compilation(
                        &root.join(format!("request-{label}")),
                        endpoint.identity().producer_bytes(),
                    )
                    .unwrap();
                let input = request.compiler_inputs();
                assert!(input
                    .native_availability(output_entry.descriptor.id)
                    .is_none());
                assert_eq!(
                    input
                        .native_availability(support_entry.descriptor.id)
                        .is_some_and(|row| row.permits(required_ordinal)),
                    expected
                );
                if !expected {
                    assert!(input
                        .compiler_source_support()
                        .native_offers()
                        .iter()
                        .all(|offer| !offer.is_full()));
                    let row = input
                        .native_availability(support_entry.descriptor.id)
                        .expect("bounded-empty A is an actual input permission row");
                    assert_eq!(
                        row.target_original(support_product.owner())
                            .unwrap()
                            .descriptor
                            .id,
                        support_entry.descriptor.id
                    );
                    assert!(!row.permits(required_ordinal));
                    assert!(input
                        .artifacts()
                        .capture_graph_selection()
                        .bindings
                        .contains(&issued_a_binding));
                }
                // Save the input owner's exact group/carrier/canonical tuple
                // before C can issue anything. Logical A identity is insufficient.
                let mut input_bindings = BTreeSet::new();
                for offer in input
                    .compiler_source_support()
                    .native_offers()
                    .iter()
                    .filter(|offer| {
                        offer.original() == support_entry.descriptor.id && offer.is_full()
                    })
                {
                    let edges = offer.custody_snapshot().binding_dependencies().unwrap();
                    for (group, carrier) in offer.issued_group_carriers().unwrap() {
                        if group.binding.artifact() != support_entry.descriptor.id
                            || group.original_ordinal != required_ordinal
                        {
                            continue;
                        }
                        let canonical = edges
                            .iter()
                            .filter_map(|(from, to, edge)| match to {
                                ArtifactBindingNode::Artifact(binding)
                                    if *from == ArtifactBindingNode::Artifact(carrier)
                                        && *edge == ArtifactDependency::Interface
                                        && binding.artifact == canonical_support.descriptor.id =>
                                {
                                    Some(*binding)
                                }
                                _ => None,
                            })
                            .collect::<BTreeSet<_>>();
                        assert_eq!(canonical.len(), 1);
                        input_bindings.insert((group, carrier, *canonical.first().unwrap()));
                    }
                }
                let expected_input = if expected {
                    assert_eq!(input_bindings.len(), 1);
                    Some(*input_bindings.first().unwrap())
                } else {
                    assert!(input_bindings.is_empty());
                    None
                };
                let operation = InventoryOperation::new(Default::default());
                let mut selection =
                    CertifiedSourceSelection::from_compiler_inputs(input, &operation).unwrap();
                selection
                    .admit_current(
                        output_product.owner(),
                        ProductOrigin::RetainedCore,
                        output_product.module_interface().unwrap(),
                        &operation,
                    )
                    .unwrap();
                selection
                    .bind_produced_originals(
                        &IssuedGroupCandidates::bind(Arc::from([]), &[output_product.clone()])
                            .unwrap(),
                    )
                    .unwrap();
                let completed = OriginalCompilerInputs::issue_segment_native_availability(
                    &mut selection,
                    input.artifacts(),
                    vec![output_entry.clone()],
                    &mut crate::recovery_artifacts::PackageInterfaceValidation::default(),
                );
                if !expected {
                    let outcome = match &completed {
                        Ok(completed) => {
                            let rows = completed
                                .native_availability()
                                .rows()
                                .map(|row| {
                                    (
                                        row.target_original(row.original_owner())
                                            .unwrap()
                                            .descriptor
                                            .id,
                                        row.original_owner().clone(),
                                        row.permits(required_ordinal),
                                    )
                                })
                                .collect::<Vec<_>>();
                            format!(
                                "success roles={:?} rows={rows:?} offers={} selected_groups={}",
                                completed.role_projection().snapshot_roles(),
                                completed.native_offers().len(),
                                completed.issued_artifacts().selected_native_groups().len()
                            )
                        }
                        Err(error) => format!("typed_error={error:?}"),
                    };
                    assert!(
                        matches!(completed, Err(CompileError::ArtifactInventory(error))
                        if error.failure == ArtifactInventoryFailure::NativeGroupUnavailable {
                            artifact: support_entry.descriptor.id, original_ordinal: required_ordinal,
                        }),
                        "actual NEW C must consult the receiving Request's absent A permission; label={label} inputA={:?} newC={:?} required_ordinal={required_ordinal} required_edges={required_edges:?} outcome={outcome}",
                        support_entry.descriptor.id, output_entry.descriptor.id,
                    );
                } else {
                    let completed = completed.unwrap();
                    assert!(
                        matches!(completed.role_projection().snapshot_roles()[&output_entry.descriptor.owner],
                        CompilerInputRole::InterfaceOnly { interface }
                            if interface == ArtifactEntry::canonical(output_product.module_interface().unwrap().clone()).descriptor.id),
                        "RetainedCore output availability does not grant Original selection"
                    );
                    let mut expected_namespace = input
                        .compiler_source_support()
                        .projection()
                        .roles()
                        .into_iter()
                        .flat_map(|role| std::iter::once(role.interface()).chain(role.original()))
                        .collect::<BTreeSet<_>>();
                    expected_namespace.insert(ArtifactEntry::canonical_artifact_id(
                        output_product.module_interface().unwrap(),
                    ));
                    let completed_graph = completed.issued_artifacts().capture_graph_selection();
                    assert_eq!(
                        completed_graph.namespace.iter().map(|binding| binding.artifact)
                            .collect::<BTreeSet<_>>(),
                        expected_namespace,
                        "private proof construction cannot publish its temporary Original namespace",
                    );
                    for binding in input.artifacts().capture_graph_selection().namespace {
                        if expected_namespace.contains(&binding.artifact) {
                            assert!(completed_graph.namespace.contains(&binding));
                        }
                    }
                    assert_eq!(
                        completed.native_availability().snapshot_facts().unwrap()
                            [&output_entry.descriptor.id]
                            .mode,
                        NativeTransportMode::Full
                    );
                    assert!(completed
                        .issued_artifacts()
                        .selected_native_groups()
                        .is_empty());
                    let completed_offer = completed
                        .native_offers()
                        .iter()
                        .find(|offer| offer.original() == output_entry.descriptor.id)
                        .expect("actual completed C has its issued native offer")
                        .clone();
                    assert!(completed_offer.is_full());
                    let (expected_a, expected_carrier, expected_canonical) =
                        expected_input.unwrap();
                    let carriers = completed_offer.issued_group_carriers().unwrap();
                    let edges = completed_offer
                        .custody_snapshot()
                        .binding_dependencies()
                        .unwrap();
                    for (dependent_ordinal, imported_ordinal, _) in &required_edges {
                        let dependent = carriers
                            .iter()
                            .filter_map(|(group, carrier)| {
                                (group.binding.artifact() == output_entry.descriptor.id
                                    && group.original_ordinal == *dependent_ordinal)
                                    .then_some((*group, *carrier))
                            })
                            .collect::<Vec<_>>();
                        assert_eq!(dependent.len(), 1);
                        let (dependent, carrier) = dependent[0];
                        assert_eq!(*imported_ordinal, expected_a.original_ordinal);
                        assert!(edges.contains(&(
                            ArtifactBindingNode::Group(dependent),
                            ArtifactBindingNode::Group(expected_a),
                            ArtifactDependency::NativeGroup {
                                dependent_ordinal: *dependent_ordinal,
                                required_ordinal: *imported_ordinal,
                            },
                        )));
                        assert!(edges.contains(&(
                            ArtifactBindingNode::Group(dependent),
                            ArtifactBindingNode::Artifact(carrier),
                            ArtifactDependency::Interface,
                        )));
                    }
                    assert!(edges.contains(&(
                        ArtifactBindingNode::Group(expected_a),
                        ArtifactBindingNode::Artifact(expected_carrier),
                        ArtifactDependency::Interface,
                    )));
                    assert!(edges.contains(&(
                        ArtifactBindingNode::Artifact(expected_carrier),
                        ArtifactBindingNode::Artifact(expected_canonical),
                        ArtifactDependency::Interface,
                    )));
                    let next = ExactCompileContext::new(context.clone())
                        .prepare_compilation_with_private_input(
                            &root.join("completed"),
                            endpoint.identity().producer_bytes(),
                            None,
                            Some(completed),
                        )
                        .unwrap();
                    assert!(next
                        .compiler_inputs()
                        .native_availability(support_entry.descriptor.id)
                        .unwrap()
                        .permits(required_ordinal));
                    assert_eq!(
                        next.compiler_inputs()
                            .compiler_source_support()
                            .native_availability()
                            .snapshot_facts()
                            .unwrap()[&output_entry.descriptor.id]
                            .mode,
                        NativeTransportMode::Full
                    );
                    assert!(next
                        .compiler_inputs()
                        .compiler_source_support()
                        .native_offers()
                        .iter()
                        .any(|offer| offer.same_issuance(&completed_offer)));
                    assert!(next
                        .compiler_inputs()
                        .artifacts()
                        .selected_native_groups()
                        .is_empty());
                }
                assert_eq!(context.artifact_view().capture_graph_selection(), before);
            }
            eprintln!("compiled_new_output_permission_controls=2 accepted=1 typed_refusals=1 required_ordinal={required_ordinal} compiled_edges={required_edges:?}");
        }));
        if let Err(panic) = result {
            let retained = directory.keep();
            eprintln!(
                "compiled Request permission inputs retained at {}",
                retained.display()
            );
            std::panic::resume_unwind(panic);
        }
    }

    #[test]
    fn completed_type_output_preserves_baseline_original_permissions() {
        use crate::artifact_inventory::{
            ArtifactEntry, ArtifactInventory, CanonicalProducerIdentity, CompilerInputProjection,
            NativeArtifactDemand, NativeGroupKey,
        };
        use crate::declaration_context::{
            ExactCompileContext, ExactDeclarationContext, NativeTransportMode,
            OriginalCompilerInputs,
        };
        let producer_bytes = b"baseline-permission-type-output";
        let producer = CanonicalProducerIdentity::from_producer_bytes(producer_bytes);
        let dependency = fixture_finalized_product(
            original_groups_fixture_with_interface(
                "BaselineTypePermission",
                vec![(7, vec![]), (9001, vec![])],
                93,
                &BTreeMap::new(),
                b"baseline type permission".to_vec(),
            ),
            producer.sha256(),
        );
        let fresh = fixture_finalized_product_with_requirements(
            original_groups_fixture_with_interface(
                "FreshTypePermission",
                vec![(3, vec![])],
                94,
                &BTreeMap::new(),
                b"fresh type permission".to_vec(),
            ),
            producer.sha256(),
            Some(BTreeMap::from([(
                (
                    dependency.owner().unit.clone(),
                    dependency.owner().module.clone(),
                ),
                dependency.module_interface().unwrap().interface_sha256(),
            )])),
        );
        let products = recovered_witness_fixtures(&[dependency, fresh]);
        let dependency = &products[0].product;
        let fresh = &products[1].product;
        let input =
            Arc::new(ArtifactEntry::original(producer.sha256(), dependency.clone()).unwrap());
        let output = Arc::new(ArtifactEntry::original(producer.sha256(), fresh.clone()).unwrap());
        for ordinals in [vec![7, 9001], vec![7], vec![]] {
            let inventory = ArtifactInventory::default();
            let selected = ordinals
                .iter()
                .map(|ordinal| NativeGroupKey {
                    artifact: input.descriptor.id,
                    original_ordinal: *ordinal,
                })
                .collect();
            let view = inventory
                .admit_recovery_selection(&inventory.empty_view(), vec![input.clone()], &selected)
                .unwrap();
            let baseline = Arc::new(
                ExactDeclarationContext::from_authenticated_execution(
                    producer.sha256(),
                    &view,
                    CompilerInputProjection::from_issued_entries(&[input.clone()]).unwrap(),
                    vec![],
                    input.descriptor.owner.clone(),
                    &[],
                )
                .unwrap(),
            );
            let root = tempfile::tempdir().unwrap();
            let request = ExactCompileContext::new(baseline.clone())
                .prepare_compilation(&root.path().join("inputs"), producer_bytes)
                .unwrap();
            let operation = InventoryOperation::new(Default::default());
            let mut selection = CertifiedSourceSelection::from_compiler_inputs(
                request.compiler_inputs(),
                &operation,
            )
            .unwrap();
            selection
                .admit_current(
                    fresh.owner(),
                    ProductOrigin::RetainedCore,
                    fresh.module_interface().unwrap(),
                    &operation,
                )
                .unwrap();
            selection
                .bind_produced_originals(
                    &IssuedGroupCandidates::bind(Arc::from([]), &[fresh.clone()]).unwrap(),
                )
                .unwrap();
            let physical = request
                .compiler_inputs()
                .artifacts()
                .inventory()
                .admit_shared_with_demand(
                    request.compiler_inputs().artifacts(),
                    vec![output.clone()],
                    NativeArtifactDemand::ScopeInterfaces,
                )
                .unwrap();
            let completed = OriginalCompilerInputs::from_selection(&selection, &physical).unwrap();
            assert_eq!(
                completed
                    .native_availability()
                    .rows()
                    .map(|row| row
                        .target_original(row.original_owner())
                        .unwrap()
                        .descriptor
                        .id)
                    .collect::<BTreeSet<_>>(),
                BTreeSet::from([input.descriptor.id, output.descriptor.id])
            );
            assert!(completed
                .issued_artifacts()
                .selected_native_groups()
                .iter()
                .all(|group| group.artifact != output.descriptor.id));
            let next = ExactCompileContext::new(baseline)
                .prepare_compilation_with_private_input(
                    &root.path().join("output"),
                    producer_bytes,
                    None,
                    Some(completed),
                )
                .unwrap();
            let inherited = next
                .compiler_inputs()
                .native_availability(input.descriptor.id)
                .unwrap();
            assert_eq!(
                next.compiler_inputs()
                    .private_native_availability()
                    .snapshot_facts()
                    .unwrap()[&input.descriptor.id]
                    .mode
                    == NativeTransportMode::Full,
                ordinals.len() == 2
            );
            assert_eq!(inherited.permits(7), ordinals.contains(&7));
            assert_eq!(inherited.permits(9001), ordinals.contains(&9001));
            assert_eq!(
                next.compiler_inputs().artifacts().selected_native_groups(),
                request
                    .compiler_inputs()
                    .artifacts()
                    .selected_native_groups()
            );
        }
    }

    // Replay actual Request continuation and new-output admission with independent
    // input permission and selected execution demand. Unrelated prior roots cannot
    // widen permissions or become fresh-output obligations.
    fn replay_completed_request_obligations(
        permitted: &[u32],
        inherited: &[u32],
        siblings: usize,
        grant_full: bool,
    ) -> BTreeSet<u32> {
        use crate::artifact_inventory::{
            ArtifactBindingNode, ArtifactEntry, ArtifactInventory, ArtifactInventoryFailure,
            CanonicalProducerIdentity, CompilerInputProjection, NativeArtifactDemand,
            NativeGroupKey,
        };
        use crate::declaration_context::{
            ExactCompileContext, ExactDeclarationContext, NativeTransportMode,
            OriginalCompilerInputs,
        };
        use crate::CompileError;
        let producer_bytes = b"request-obligation-history";
        let producer = CanonicalProducerIdentity::from_producer_bytes(producer_bytes);
        let product = |module: &str, version, groups| {
            fixture_finalized_product(
                original_groups_fixture_with_interface(
                    module,
                    groups,
                    version,
                    &BTreeMap::new(),
                    format!("{module} interface").into_bytes(),
                ),
                producer.sha256(),
            )
        };
        let dependency = product(
            "ObligationBaseline",
            95,
            vec![(7, vec![]), (9001, vec![]), (42, vec![]), (43, vec![])],
        );
        let mut binder = testing::identity("ObligationBaseline", "entry_7");
        binder.unit = dependency.owner().unit.clone();
        let fresh = product(
            "ObligationFresh",
            96,
            vec![(
                3,
                vec![PendingImportOwner::Source {
                    owner: dependency.owner().clone(),
                    original_ordinal: 7,
                    binder,
                }],
            )],
        );
        let mut products = vec![dependency, fresh];
        products.extend((0..siblings).map(|index| {
            product(
                &format!("ObligationSibling{index}"),
                97,
                vec![(9001, vec![])],
            )
        }));
        let products = recovered_witness_fixtures(&products);
        let dependency = &products[0].product;
        let fresh = &products[1].product;
        let input =
            Arc::new(ArtifactEntry::original(producer.sha256(), dependency.clone()).unwrap());
        let fresh_id = ArtifactEntry::original(producer.sha256(), fresh.clone())
            .unwrap()
            .descriptor
            .id;
        let mut entries = vec![input.clone()];
        entries.extend(products[2..].iter().map(|row| {
            Arc::new(ArtifactEntry::original(producer.sha256(), row.product.clone()).unwrap())
        }));
        let projection = CompilerInputProjection::from_issued_entries(&entries).unwrap();
        let inventory = ArtifactInventory::default();
        let full = inventory
            .admit_shared(&inventory.empty_view(), entries.clone())
            .unwrap();
        let full_support =
            crate::declaration_context::issue_fixture_compiler_support(projection.clone(), full)
                .unwrap();
        let selected = inherited
            .iter()
            .map(|ordinal| NativeGroupKey {
                artifact: input.descriptor.id,
                original_ordinal: *ordinal,
            })
            .chain(entries[1..].iter().map(|entry| NativeGroupKey {
                artifact: entry.descriptor.id,
                original_ordinal: 9001,
            }))
            .collect::<BTreeSet<_>>();
        let chosen = if grant_full {
            // Change demand under this same issued carrier and canonical namespace.
            // A separate admission would issue different bindings and correctly
            // demote the earlier Full qualification during normalization.
            let issued = full_support.artifacts();
            let mut graph = issued.capture_graph_selection();
            let namespace = graph.namespace.clone();
            let unused = graph
                .roots
                .iter()
                .filter(|node| match node {
                    ArtifactBindingNode::Group(group) => !selected.contains(&NativeGroupKey {
                        artifact: group.binding.artifact(),
                        original_ordinal: group.original_ordinal,
                    }),
                    ArtifactBindingNode::Artifact(_) => false,
                })
                .copied()
                .collect::<Vec<_>>();
            graph.roots.retain(|node| !unused.contains(node));
            graph.custody_roots.extend(unused);
            graph.custody_roots.sort();
            graph.custody_roots.dedup();
            let chosen = issued
                .select_issued(
                    namespace.iter().map(|binding| binding.artifact).collect(),
                    &crate::artifact_inventory::ExactArtifactSelection::from_recovered_graph_selection(
                        graph,
                    ),
                )
                .unwrap();
            assert_eq!(chosen.capture_graph_selection().namespace, namespace);
            assert_eq!(chosen.selected_native_groups(), selected);
            chosen
        } else {
            inventory
                .admit_recovery_selection(&inventory.empty_view(), entries, &selected)
                .unwrap()
        };
        let mut support =
            crate::declaration_context::issue_fixture_compiler_support(projection, chosen)
                .unwrap()
                .retain_offers(full_support.native_offers().iter().cloned())
                .unwrap();
        if grant_full {
            support = support
                .retain_normalized_availability(full_support.native_availability())
                .unwrap();
        }
        let input_row = support
            .native_availability()
            .rows()
            .find(|row| row.original_owner() == dependency.owner())
            .unwrap();
        assert!(
            support
                .native_offers()
                .iter()
                .any(|offer| { offer.original() == input.descriptor.id && offer.is_full() }),
            "all cases retain genuine broader Full proof custody"
        );
        assert_eq!(
            support.native_availability().snapshot_facts().unwrap()[&input.descriptor.id].mode
                == NativeTransportMode::Full,
            grant_full
        );
        for ordinal in [7, 9001, 42, 43] {
            assert_eq!(input_row.permits(ordinal), permitted.contains(&ordinal));
        }
        let context = Arc::new(
            ExactDeclarationContext::new(&[], &[], vec![])
                .unwrap()
                .extend_issued_compiler_support(&support)
                .unwrap(),
        );
        let source_before = context.artifact_view().capture_graph_selection();
        let root = tempfile::tempdir().unwrap();
        let exact_request = ExactCompileContext::new(context.clone())
            .prepare_compilation(root.path(), producer_bytes)
            .unwrap();
        let request = exact_request.compiler_inputs();
        let operation = InventoryOperation::new(Default::default());
        let mut selection =
            CertifiedSourceSelection::from_compiler_inputs(request, &operation).unwrap();
        selection
            .admit_current(
                fresh.owner(),
                ProductOrigin::RetainedCore,
                fresh.module_interface().unwrap(),
                &operation,
            )
            .unwrap();
        selection
            .bind_produced_originals(
                &IssuedGroupCandidates::bind(Arc::from([]), &[fresh.clone()]).unwrap(),
            )
            .unwrap();
        let physical = request
            .artifacts()
            .inventory()
            .admit_shared_with_demand(
                request.artifacts(),
                vec![Arc::new(
                    ArtifactEntry::original(producer.sha256(), fresh.clone()).unwrap(),
                )],
                NativeArtifactDemand::ScopeInterfaces,
            )
            .unwrap();
        let result = OriginalCompilerInputs::from_selection(&selection, &physical);
        let allowed = permitted.contains(&7);
        let consumer = "request";
        {
            if !allowed {
                let actual_error = format!("{:?}", result.as_ref().err());
                assert!(
                    matches!(result, Err(CompileError::ArtifactInventory(error))
                    if matches!(error.failure, ArtifactInventoryFailure::NativeGroupUnavailable {
                        artifact, original_ordinal: 7,
                    } if artifact == input.descriptor.id)),
                    "{consumer}: broader proof cannot grant unavailable B7; actual_error={actual_error}"
                );
                assert_eq!(
                    context.artifact_view().capture_graph_selection(),
                    source_before
                );
                return BTreeSet::new();
            }
            let fragment = result.unwrap_or_else(|error| {
                panic!("{consumer}: inherited={inherited:?} siblings={siblings}: {error:?}")
            });
            let fresh_row = fragment
                .native_availability()
                .rows()
                .find(|row| row.original_owner() == fresh.owner())
                .unwrap();
            assert_eq!(
                fragment.native_availability().snapshot_facts().unwrap()[&fresh_id].mode,
                NativeTransportMode::Full
            );
            let fresh_groups = fresh_row
                .offers()
                .flat_map(|offer| offer.issued_group_carriers().unwrap().into_keys())
                .filter(|group| group.binding.artifact() == fresh_id)
                .map(|group| group.original_ordinal)
                .collect::<BTreeSet<_>>();
            assert_eq!(fresh_groups, BTreeSet::from([3]));
            assert!(
                !fragment
                    .issued_artifacts()
                    .selected_native_groups()
                    .iter()
                    .any(|group| { group.artifact == fresh_id }),
                "fresh availability does not select fresh execution"
            );
            let dependency_row = fragment
                .native_availability()
                .rows()
                .find(|row| row.original_owner() == dependency.owner())
                .unwrap();
            assert_eq!(
                fragment.native_availability().snapshot_facts().unwrap()[&input.descriptor.id].mode
                    == NativeTransportMode::Full,
                grant_full
            );
            assert_eq!(
                fragment
                    .native_availability()
                    .rows()
                    .map(|row| row
                        .target_original(row.original_owner())
                        .unwrap()
                        .descriptor
                        .id)
                    .collect::<BTreeSet<_>>(),
                std::iter::once(fresh_id)
                    .chain(
                        support
                            .projection()
                            .roles()
                            .iter()
                            .filter_map(|role| role.original())
                    )
                    .collect::<BTreeSet<_>>(),
            );
            let expected = permitted.iter().copied().collect::<BTreeSet<_>>();
            let actual = [7, 9001, 42, 43]
                .into_iter()
                .filter(|ordinal| dependency_row.permits(*ordinal))
                .collect::<BTreeSet<_>>();
            assert_eq!(actual, expected, "{consumer} retains exactly the input permissions, independently of selected execution");
            assert_eq!(
                context.artifact_view().capture_graph_selection(),
                source_before
            );
            actual
        }
    }

    #[test]
    fn completed_request_obligations_exclude_unrelated_selected_groups() {
        for permitted in [vec![7, 9001, 42, 43], vec![7], vec![9001], vec![]] {
            replay_completed_request_obligations(&permitted, &permitted, 0, permitted.len() == 4);
        }
    }

    #[test]
    fn generated_completed_request_obligations_ignore_unrelated_selected_history() {
        use proptest::prelude::*;
        use proptest::test_runner::{contextualize_config, Config, TestCaseError, TestRunner};
        let config = Config {
            cases: 24,
            source_file: Some(file!()),
            test_name: Some(concat!(
                module_path!(),
                "::generated_completed_request_obligations_ignore_unrelated_selected_history"
            )),
            ..Config::default()
        };
        let callbacks = std::cell::Cell::new(0usize);
        let completed = std::cell::Cell::new(0usize);
        TestRunner::new(contextualize_config(config))
            .run(
                &(any::<[bool; 3]>(), 0usize..4),
                |(extra_groups, siblings)| {
                    callbacks.set(callbacks.get() + 1);
                    let mut inherited = vec![7];
                    inherited.extend(
                        [9001, 42, 43]
                            .into_iter()
                            .zip(extra_groups)
                            .filter_map(|(ordinal, selected)| selected.then_some(ordinal)),
                    );
                    std::panic::catch_unwind(|| {
                        let allowed = [7, 9001, 42, 43];
                        let baseline =
                            replay_completed_request_obligations(&allowed, &[7], 0, true);
                        let varied = replay_completed_request_obligations(
                            &allowed, &inherited, siblings, true,
                        );
                        assert_eq!(
                            varied, baseline,
                            "request permission must ignore unrelated inherited demand"
                        );
                    })
                    .map(|()| completed.set(completed.get() + 1))
                    .map_err(|panic| {
                        let message = panic
                            .downcast_ref::<String>()
                            .cloned()
                            .or_else(|| {
                                panic
                                    .downcast_ref::<&str>()
                                    .map(|value| (*value).to_owned())
                            })
                            .unwrap_or_else(|| "non-string panic".into());
                        TestCaseError::fail(format!(
                            "extra_groups={extra_groups:?} siblings={siblings}: {message}"
                        ))
                    })
                },
            )
            .unwrap();
        eprintln!("completed_request_obligation_property configured_fresh_cases=24 callbacks={} completed={}", callbacks.get(), completed.get());
    }

    #[test]
    fn full_original_availability_is_read_only_and_checks_selected_authority() {
        let operation = InventoryOperation::new(Default::default());
        let original = full_native_fixture("Available", vec![(8, vec![]), (11, vec![])], 7);
        let sources =
            available_original_source_map(std::slice::from_ref(&original), &[], &operation)
                .unwrap();
        let owner = original.owner();
        let key = (owner.clone(), 8, testing::identity("Available", "entry_8"));
        assert_eq!(
            sources.get(&key),
            Some(&(owner.clone(), ProductOrigin::Cached))
        );
        assert_eq!(original.original_native().unwrap().groups.len(), 2);
        let selected = original.original_native().unwrap().groups[0]
            .admitted(original.original_native().unwrap())
            .unwrap();
        available_original_source_map(
            std::slice::from_ref(&original),
            std::slice::from_ref(&selected),
            &operation,
        )
        .unwrap();
        let mut wrong = selected.clone();
        wrong.owner.module_version = ModuleVersion([9; 32]);
        assert!(available_original_source_map(
            std::slice::from_ref(&original),
            &[wrong],
            &operation
        )
        .is_err());
        let mut wrong = selected.clone();
        wrong.imports = vec![PendingImportOwner::Retained {
            identity: testing::identity("Available", "captured"),
            generation: 9,
        }]
        .into();
        assert!(available_original_source_map(
            std::slice::from_ref(&original),
            &[wrong],
            &operation
        )
        .is_err());
        let duplicate = available_original_source_map(
            std::slice::from_ref(&original),
            &[selected.clone(), selected.clone()],
            &operation,
        );
        let Err(CertificationError::DuplicateSourceBinder(conflict)) = duplicate else {
            panic!("duplicate selected groups must retain their exact conflict");
        };
        assert_eq!(
            *conflict,
            SourceBinderConflict {
                phase: SourceBinderPhase::SelectedGroups,
                owner: selected.owner.clone(),
                original_ordinal: selected.group.original_ordinal(),
                binder: selected.group.binders()[0].clone(),
                existing_origin: selected.origin,
                incoming_origin: selected.origin,
            }
        );
        assert!(available_original_source_map(
            &[original.clone(), original.clone()],
            &[],
            &operation
        )
        .is_err());
        let other = full_native_fixture("Available", vec![(8, vec![]), (11, vec![])], 9);
        available_original_source_map(&[original.clone(), other], &[], &operation).unwrap();
        let empty = full_native_fixture("EmptyNative", vec![], 7);
        let empty_sources = available_original_source_map(&[empty], &[], &operation).unwrap();
        let directory = tempfile::tempdir().unwrap();
        let selected_path = directory.path().join("EmptyNative.hi");
        std::fs::write(&selected_path, b"otherwise valid package interface").unwrap();
        let interface_digest = sha(b"otherwise valid package interface");
        let packages = BTreeMap::from([(
            ("fixture".into(), "EmptyNative".into()),
            PackageInterfaceWitness {
                selected_path,
                sha256: interface_digest,
            },
        )]);
        let package = ReceiptImportOwner::Package {
            unit: "fixture".into(),
            module: "EmptyNative".into(),
            binder: testing::identity("EmptyNative", "unavailable"),
            interface_digest,
        };
        resolve_receipt_owner(package.clone(), &SourceGroupMap::new(), &packages).unwrap();
        assert!(matches!(
            resolve_receipt_owner(package, &empty_sources, &packages),
            Err(CertificationError::Mismatch(
                "home owner downgraded to package"
            ))
        ));
        assert!(operation.work_usage().unwrap().0 > 0);
        let exhausted = InventoryOperation::new(InventoryDecodeLimits {
            max_work: 0,
            ..Default::default()
        });
        assert!(available_original_source_map(&[original], &[], &exhausted).is_err());
    }

    #[test]
    fn retained_original_membership_reuses_only_its_admission_and_exact_bytes() {
        let product = full_native_fixture("Membership", vec![(8, vec![]), (11, vec![])], 7);
        let inventory = crate::artifact_inventory::ArtifactInventory::default();
        let entry = Arc::new(
            crate::artifact_inventory::ArtifactEntry::original(
                product.module_interface().unwrap().producer_sha256(),
                product.clone(),
            )
            .unwrap(),
        );
        let basis_view = inventory
            .admit_recovery_selection(&inventory.empty_view(), vec![entry], &BTreeSet::new())
            .unwrap();
        let metadata = crate::artifact_inventory::CompilerInputProjection::default()
            .project_metadata(basis_view.metadata_snapshot())
            .unwrap();
        let basis = metadata.original_source_membership_basis();
        let retained = RetainedOriginalSources::default();
        let operation = Arc::new(InventoryOperation::new(Default::default()));
        let first = retained
            .admit(&basis, std::slice::from_ref(&product), &operation)
            .unwrap();
        let charged = operation.work_usage().unwrap();
        let repeated = retained
            .admit(&basis, std::slice::from_ref(&product), &operation)
            .unwrap();
        assert!(Arc::ptr_eq(&first, &repeated));
        let observed = operation.work_usage().unwrap();
        assert!(
            observed.0 > charged.0,
            "the small borrowed owner census remains charged"
        );
        assert!(
            observed.0 - charged.0 < charged.0,
            "reuse must not rebuild the full binder membership"
        );
        let independently_recovered = recovered_witness_fixtures(std::slice::from_ref(&product))
            .remove(0)
            .product;
        assert!(!Arc::ptr_eq(
            &product.original_byte_anchors()[0],
            &independently_recovered.original_byte_anchors()[0]
        ));
        assert!(
            Arc::ptr_eq(
                &first,
                &retained
                    .admit(&basis, &[independently_recovered], &operation)
                    .unwrap()
            ),
            "equal authenticated bytes may be independently recovered"
        );
        let all_keys = first
            .sources
            .groups
            .keys()
            .cloned()
            .collect::<BTreeSet<_>>();
        for count in 0..=2 {
            let groups = product.original_native().unwrap().groups[..count]
                .iter()
                .map(|group| group.admitted(product.original_native().unwrap()).unwrap())
                .collect::<Vec<_>>();
            let overlay = first.overlay(&groups, &operation).unwrap();
            assert_eq!(overlay.groups.len(), count);
            assert_eq!(
                overlay
                    .iter()
                    .map(|(key, _)| key.clone())
                    .collect::<BTreeSet<_>>(),
                all_keys
            );
            assert_eq!(
                first.sources.groups.len(),
                2,
                "overlay never modifies retained membership"
            );
        }
        assert!(matches!(retained.admit(&basis, &[], &operation),
            Err(CertificationError::OriginalMembership(reason))
                if *reason == OriginalMembershipFailure::MissingOwner(product.owner().clone())));
        assert!(
            matches!(retained.admit(&basis, &[product.clone(), product.clone()], &operation),
            Err(CertificationError::OriginalMembership(reason))
                if *reason == OriginalMembershipFailure::DuplicateOwner(product.owner().clone()))
        );
        let other = full_native_fixture("Membership", vec![(8, vec![]), (11, vec![])], 9);
        assert!(
            matches!(retained.admit(&basis, &[other.clone()], &operation),
            Err(CertificationError::OriginalMembership(reason))
                if *reason == OriginalMembershipFailure::UnexpectedOwner(other.owner().clone()))
        );
        let altered = crate::recovery_artifacts::CertifiedRecoveryProduct::from_certification(
            product.owner().clone(),
            product.interface_bytes().to_vec(),
            product.product_bytes().to_vec(),
            product.package_imports_bytes().to_vec(),
            product.certification_bytes().to_vec(),
        );
        assert!(matches!(retained.admit(&basis, &[altered], &operation),
            Err(CertificationError::OriginalMembership(reason))
                if *reason == OriginalMembershipFailure::OriginalBytes(product.owner().clone())));
        assert!(
            Arc::ptr_eq(
                &first,
                &retained
                    .admit(&basis, std::slice::from_ref(&product), &operation)
                    .unwrap()
            ),
            "refusal preserves the prior issued membership"
        );
        let exhausted = Arc::new(InventoryOperation::new(InventoryDecodeLimits {
            max_work: 0,
            ..Default::default()
        }));
        assert!(
            retained
                .admit(&basis, std::slice::from_ref(&product), &exhausted)
                .is_err(),
            "a new admission cannot borrow another operation's paid budget"
        );
        let fresh = Arc::new(InventoryOperation::new(Default::default()));
        let next = retained
            .admit(&basis, std::slice::from_ref(&product), &fresh)
            .unwrap();
        assert!(!Arc::ptr_eq(&first, &next));
        assert!(fresh.work_usage().unwrap().0 > 0);
        let weak = Arc::downgrade(&next);
        drop(next);
        drop(retained);
        assert!(
            weak.upgrade().is_none(),
            "retiring the owner releases its retained membership"
        );
    }

    #[test]
    fn retained_original_membership_tracks_changed_input_basis_in_one_operation() {
        use crate::artifact_inventory::{
            ArtifactEntry, ArtifactInventory, CompilerInputProjection,
        };

        let first_product = full_native_fixture("MembershipPrefix", vec![(8, vec![])], 7);
        let added_product = full_native_fixture("Scientific", vec![(26, vec![])], 9);
        let entry = |product: &crate::recovery_artifacts::CertifiedRecoveryProduct| {
            Arc::new(
                ArtifactEntry::original(
                    product.module_interface().unwrap().producer_sha256(),
                    product.clone(),
                )
                .unwrap(),
            )
        };
        let inventory = ArtifactInventory::default();
        let first_view = inventory
            .admit_recovery_selection(
                &inventory.empty_view(),
                vec![entry(&first_product)],
                &BTreeSet::new(),
            )
            .unwrap();
        let first_metadata = CompilerInputProjection::default()
            .project_metadata(first_view.metadata_snapshot())
            .unwrap();
        let first_basis = first_metadata.original_source_membership_basis();
        let retained = RetainedOriginalSources::default();
        let operation = Arc::new(InventoryOperation::new(Default::default()));
        let original = retained
            .admit(
                &first_basis,
                std::slice::from_ref(&first_product),
                &operation,
            )
            .unwrap();
        let expected_first = BTreeSet::from([(
            first_product.owner().clone(),
            8,
            testing::identity("MembershipPrefix", "entry_8"),
        )]);
        assert_eq!(
            original
                .sources
                .iter()
                .map(|(key, _)| key.clone())
                .collect::<BTreeSet<_>>(),
            expected_first
        );
        assert!(Arc::ptr_eq(
            &original,
            &retained
                .admit(
                    &first_basis,
                    std::slice::from_ref(&first_product),
                    &operation,
                )
                .unwrap()
        ));
        let products = [first_product.clone(), added_product.clone()];
        assert!(
            matches!(retained.admit(&first_basis, &products, &operation),
            Err(CertificationError::OriginalMembership(reason))
                if *reason == OriginalMembershipFailure::UnexpectedOwner(added_product.owner().clone()))
        );

        let next_view = inventory
            .admit_recovery_selection(&first_view, vec![entry(&added_product)], &BTreeSet::new())
            .unwrap();
        let next_metadata = CompilerInputProjection::default()
            .project_metadata(next_view.metadata_snapshot())
            .unwrap();
        let next_basis = next_metadata.original_source_membership_basis();
        assert!(!first_basis.same_owner(&next_basis));
        let invalid = crate::recovery_artifacts::CertifiedRecoveryProduct::from_certification(
            added_product.owner().clone(),
            added_product.interface_bytes().to_vec(),
            added_product.product_bytes().to_vec(),
            added_product.package_imports_bytes().to_vec(),
            added_product.certification_bytes().to_vec(),
        );
        assert!(matches!(
            retained.admit(
                &next_basis,
                &[first_product.clone(), invalid.clone()],
                &operation
            ),
            Err(CertificationError::Mismatch(
                "available original native witness"
            ))
        ));
        assert!(
            Arc::ptr_eq(
                &original,
                &retained
                    .admit(
                        &first_basis,
                        std::slice::from_ref(&first_product),
                        &operation,
                    )
                    .unwrap()
            ),
            "failed authentication of another basis preserves the prior slot"
        );
        let expanded = retained.admit(&next_basis, &products, &operation).unwrap();
        assert!(!Arc::ptr_eq(&original, &expanded));
        let expected_next = expected_first
            .iter()
            .cloned()
            .chain([(
                added_product.owner().clone(),
                26,
                testing::identity("Scientific", "entry_26"),
            )])
            .collect::<BTreeSet<_>>();
        assert_eq!(
            expanded
                .sources
                .iter()
                .map(|(key, _)| key.clone())
                .collect::<BTreeSet<_>>(),
            expected_next
        );
        assert!(Arc::ptr_eq(
            &expanded,
            &retained.admit(&next_basis, &products, &operation).unwrap()
        ));
        assert!(
            matches!(retained.admit(&next_basis, std::slice::from_ref(&first_product), &operation),
            Err(CertificationError::OriginalMembership(reason))
                if *reason == OriginalMembershipFailure::MissingOwner(added_product.owner().clone()))
        );
        assert!(
            matches!(retained.admit(&next_basis, &[first_product.clone(), invalid], &operation),
            Err(CertificationError::OriginalMembership(reason))
                if *reason == OriginalMembershipFailure::OriginalBytes(added_product.owner().clone()))
        );
        assert!(Arc::ptr_eq(
            &expanded,
            &retained.admit(&next_basis, &products, &operation).unwrap()
        ));
        let selected = first_product
            .original_native()
            .unwrap()
            .groups
            .iter()
            .map(|group| {
                group
                    .admitted(first_product.original_native().unwrap())
                    .unwrap()
            })
            .collect::<Vec<_>>();
        assert_eq!(
            original
                .overlay(&selected, &operation)
                .unwrap()
                .iter()
                .map(|(key, _)| key.clone())
                .collect::<BTreeSet<_>>(),
            expected_first,
            "the old returned membership remains exact and usable after basis growth"
        );
        let next_owner = Arc::downgrade(&next_metadata.retained);
        drop(next_metadata);
        drop(next_view);
        assert!(
            next_owner.upgrade().is_none(),
            "cache basis identity must not retain old metadata custody"
        );

        let reopened_inventory = ArtifactInventory::default();
        let reopened_view = reopened_inventory
            .admit_recovery_selection(
                &reopened_inventory.empty_view(),
                products.iter().map(entry).collect(),
                &BTreeSet::new(),
            )
            .unwrap();
        let reopened_metadata = CompilerInputProjection::default()
            .project_metadata(reopened_view.metadata_snapshot())
            .unwrap();
        let reopened_basis = reopened_metadata.original_source_membership_basis();
        assert!(!next_basis.same_owner(&reopened_basis));
        let reopened = retained
            .admit(&reopened_basis, &products, &operation)
            .unwrap();
        assert!(
            !Arc::ptr_eq(&expanded, &reopened),
            "a new real owner cannot hit an expired weak basis"
        );
        assert_eq!(
            reopened
                .sources
                .iter()
                .map(|(key, _)| key.clone())
                .collect::<BTreeSet<_>>(),
            expected_next
        );
        assert!(Arc::ptr_eq(
            &reopened,
            &retained
                .admit(&reopened_basis, &products, &operation)
                .unwrap()
        ));
        assert_eq!(
            original
                .sources
                .iter()
                .map(|(key, _)| key.clone())
                .collect::<BTreeSet<_>>(),
            expected_first
        );
    }

    #[test]
    fn retained_original_membership_charges_independently_recovered_bytes() {
        let product = full_native_fixture("RecoveredMembership", vec![(8, vec![])], 7);
        let inventory = crate::artifact_inventory::ArtifactInventory::default();
        let entry = Arc::new(
            crate::artifact_inventory::ArtifactEntry::original(
                product.module_interface().unwrap().producer_sha256(),
                product.clone(),
            )
            .unwrap(),
        );
        let basis_view = inventory
            .admit_recovery_selection(&inventory.empty_view(), vec![entry], &BTreeSet::new())
            .unwrap();
        let metadata = crate::artifact_inventory::CompilerInputProjection::default()
            .project_metadata(basis_view.metadata_snapshot())
            .unwrap();
        let basis = metadata.original_source_membership_basis();
        let independently_recovered = recovered_witness_fixtures(std::slice::from_ref(&product))
            .remove(0)
            .product;
        let comparison_bytes = product
            .original_byte_anchors()
            .into_iter()
            .zip(independently_recovered.original_byte_anchors())
            .map(|(original, recovered)| {
                assert!(!Arc::ptr_eq(original, recovered));
                assert_eq!(original, recovered);
                assert!(!recovered.is_empty());
                recovered.len()
            })
            .sum::<usize>();

        let measured = RetainedOriginalSources::default();
        let measurement = Arc::new(InventoryOperation::new(Default::default()));
        measured
            .admit(&basis, std::slice::from_ref(&product), &measurement)
            .unwrap();
        let construction_work = measurement.work_usage().unwrap().0;
        measured
            .admit(&basis, std::slice::from_ref(&product), &measurement)
            .unwrap();
        let census_work = measurement.work_usage().unwrap().0 - construction_work;
        assert!(census_work > 0);

        let retained = RetainedOriginalSources::default();
        let pointer_budget = Arc::new(InventoryOperation::new(InventoryDecodeLimits {
            max_work: construction_work + census_work,
            ..Default::default()
        }));
        let first = retained
            .admit(&basis, std::slice::from_ref(&product), &pointer_budget)
            .unwrap();
        let repeated = retained
            .admit(&basis, std::slice::from_ref(&product), &pointer_budget)
            .unwrap();
        assert!(Arc::ptr_eq(&first, &repeated));
        assert_eq!(pointer_budget.work_usage().unwrap().1, 0);

        for allowance in [0, comparison_bytes - 1, comparison_bytes] {
            let retained = RetainedOriginalSources::default();
            let recovery_budget = Arc::new(InventoryOperation::new(InventoryDecodeLimits {
                max_work: construction_work + census_work + allowance,
                ..Default::default()
            }));
            let first = retained
                .admit(&basis, std::slice::from_ref(&product), &recovery_budget)
                .unwrap();
            let recovered = retained.admit(
                &basis,
                std::slice::from_ref(&independently_recovered),
                &recovery_budget,
            );
            if allowance < comparison_bytes {
                assert!(matches!(
                    recovered,
                    Err(CertificationError::Product(
                        tidepool_repr::execution_schema::ParseError::LimitExceeded("work")
                    ))
                ));
            } else {
                assert!(Arc::ptr_eq(&first, &recovered.unwrap()));
                assert_eq!(recovery_budget.work_usage().unwrap().1, 0);
            }
        }
    }

    #[test]
    fn source_receipts_use_request_selection_without_collapsing_original_versions() {
        let captured = |generation| PendingImportOwner::Retained {
            identity: testing::identity("Val.G1", "captured"),
            generation,
        };
        let old = full_native_fixture("Shared", vec![(3, vec![captured(1)]), (11, vec![])], 7);
        let new = full_native_fixture("Shared", vec![(3, vec![captured(2)]), (11, vec![])], 9);
        let products = [old.clone(), new.clone()];
        let selected = [
            old.original_native().unwrap().groups[0]
                .admitted(old.original_native().unwrap())
                .unwrap(),
            new.original_native().unwrap().groups[0]
                .admitted(new.original_native().unwrap())
                .unwrap(),
        ];
        let mut validation = PackageInterfaceValidation::default();
        let sources =
            available_original_source_map(&products, &selected, &validation.inventory).unwrap();
        let binder = testing::identity("Shared", "entry_3");
        for product in &products {
            assert!(sources
                .get(&(product.owner().clone(), 3, binder.clone()))
                .is_some());
        }
        assert_eq!(certified_source_map(&selected).unwrap().groups.len(), 2);
        let receipt = |version, ordinal, binder| ReceiptImportOwner::Source {
            unit: "fixture".into(),
            module: "Shared".into(),
            module_version: version,
            original_ordinal: ordinal,
            binder,
        };
        let old_selection = CertifiedSourceSelection::from_projected_originals(
            std::slice::from_ref(&old),
            &validation.inventory,
        )
        .unwrap();
        assert_eq!(
            resolve_receipt_owner_with_validation(
                receipt(Some(old.owner().module_version.clone()), 3, binder.clone()),
                &sources,
                Some(&old_selection),
                &BTreeMap::new(),
                &mut validation
            )
            .unwrap(),
            PendingImportOwner::Source {
                owner: old.owner().clone(),
                original_ordinal: 3,
                binder: binder.clone()
            }
        );
        let mut current_selection = CertifiedSourceSelection::new_product_ingress();
        current_selection
            .admit_current(
                new.owner(),
                ProductOrigin::Fresh,
                new.module_interface().unwrap(),
                &validation.inventory,
            )
            .unwrap();
        current_selection
            .bind_produced_originals(
                &IssuedGroupCandidates::bind(Arc::from([]), &[new.clone()]).unwrap(),
            )
            .unwrap();
        for version in [None, Some(new.owner().module_version.clone())] {
            assert_eq!(
                resolve_receipt_owner_with_validation(
                    receipt(version, 3, binder.clone()),
                    &sources,
                    Some(&current_selection),
                    &BTreeMap::new(),
                    &mut validation
                )
                .unwrap(),
                PendingImportOwner::Source {
                    owner: new.owner().clone(),
                    original_ordinal: 3,
                    binder: binder.clone()
                }
            );
        }
        assert!(matches!(
            resolve_receipt_owner_with_validation(
                receipt(None, 3, binder.clone()),
                &sources,
                None,
                &BTreeMap::new(),
                &mut validation
            ),
            Err(CertificationError::Mismatch(
                "unversioned source lacks compiler selection"
            ))
        ));
        assert!(matches!(
            resolve_receipt_owner_with_validation(
                receipt(Some(old.owner().module_version.clone()), 3, binder.clone()),
                &sources,
                Some(&current_selection),
                &BTreeMap::new(),
                &mut validation
            ),
            Err(CertificationError::Mismatch("source module version"))
        ));
        for (ordinal, wrong_binder) in [
            (4, binder.clone()),
            (3, testing::identity("Shared", "other")),
        ] {
            assert!(matches!(
                resolve_receipt_owner_with_validation(
                    receipt(None, ordinal, wrong_binder),
                    &sources,
                    Some(&current_selection),
                    &BTreeMap::new(),
                    &mut validation
                ),
                Err(CertificationError::Mismatch("source binder/group closure"))
            ));
        }
        let only_new =
            available_original_source_map(std::slice::from_ref(&new), &[], &validation.inventory)
                .unwrap();
        assert!(matches!(
            resolve_receipt_owner_with_validation(
                receipt(Some(old.owner().module_version.clone()), 3, binder.clone()),
                &only_new,
                Some(&old_selection),
                &BTreeMap::new(),
                &mut validation
            ),
            Err(CertificationError::Mismatch("source binder/group closure"))
        ));
        assert!(matches!(
            CertifiedSourceSelection::from_projected_originals(&products, &validation.inventory),
            Err(CertificationError::Mismatch(
                "ambiguous compiler original owner"
            ))
        ));
        assert!(matches!(
            old_selection.clone().admit_current(
                new.owner(),
                ProductOrigin::Fresh,
                new.module_interface().unwrap(),
                &validation.inventory
            ),
            Err(CertificationError::Mismatch(
                "compiler original owner replaced"
            ))
        ));

        // A version alone cannot choose between contradictory original byte seals.
        let conflicting =
            full_native_fixture("Shared", vec![(3, vec![captured(2)]), (11, vec![])], 7);
        assert_ne!(old.owner(), conflicting.owner());
        let conflict_sources =
            available_original_source_map(&[old.clone(), conflicting], &[], &validation.inventory)
                .unwrap();
        assert!(matches!(
            resolve_receipt_owner_with_validation(
                receipt(Some(old.owner().module_version.clone()), 3, binder.clone()),
                &conflict_sources,
                None,
                &BTreeMap::new(),
                &mut validation
            ),
            Err(CertificationError::Mismatch(
                "ambiguous source original identity"
            ))
        ));
        assert!(resolve_receipt_owner_with_validation(
            receipt(Some(old.owner().module_version.clone()), 3, binder),
            &conflict_sources,
            Some(&old_selection),
            &BTreeMap::new(),
            &mut validation
        )
        .is_ok());
    }

    #[test]
    fn cached_reoffer_keeps_original_source_domain_and_byte_anchors() {
        let retained = |generation| PendingImportOwner::Retained {
            identity: testing::identity("Val.G1", "captured"),
            generation,
        };
        let old_helper = full_native_fixture("Helper", vec![(3, vec![retained(1)])], 7);
        let new_helper = full_native_fixture("Helper", vec![(3, vec![retained(2)])], 9);
        let old_edge = PendingImportOwner::Source {
            owner: old_helper.owner().clone(),
            original_ordinal: 3,
            binder: testing::identity("Helper", "entry_3"),
        };
        let original = full_native_fixture("Consumer", vec![(11, vec![old_edge.clone()])], 7);
        let products = [original.clone(), old_helper.clone(), new_helper.clone()];
        let mut validation = PackageInterfaceValidation::default();
        let sources = available_original_source_map(&products, &[], &validation.inventory).unwrap();
        let mut current = CertifiedSourceSelection::new_product_ingress();
        current
            .admit_current(
                new_helper.owner(),
                ProductOrigin::Fresh,
                new_helper.module_interface().unwrap(),
                &validation.inventory,
            )
            .unwrap();
        current
            .bind_produced_originals(
                &IssuedGroupCandidates::bind(Arc::from([]), &[new_helper.clone()]).unwrap(),
            )
            .unwrap();
        let old_receipt = ReceiptImportOwner::Source {
            unit: old_helper.owner().unit.clone(),
            module: old_helper.owner().module.clone(),
            module_version: Some(old_helper.owner().module_version.clone()),
            original_ordinal: 3,
            binder: testing::identity("Helper", "entry_3"),
        };
        let native_group = &original.original_native().unwrap().groups[0];
        let admitted = validate_original_group_receipts(
            native_group.group(),
            &[old_receipt.clone()],
            native_group,
            original.original_native().unwrap(),
            &sources,
            &BTreeMap::new(),
            &mut validation,
        )
        .unwrap();
        assert_eq!(admitted.imports(), &[old_edge]);
        let current_edge = resolve_receipt_owner_with_validation(
            ReceiptImportOwner::Source {
                unit: new_helper.owner().unit.clone(),
                module: new_helper.owner().module.clone(),
                module_version: None,
                original_ordinal: 3,
                binder: testing::identity("Helper", "entry_3"),
            },
            &sources,
            Some(&current),
            &BTreeMap::new(),
            &mut validation,
        )
        .unwrap();
        assert!(
            matches!(current_edge, PendingImportOwner::Source { owner, .. } if owner == *new_helper.owner())
        );
        let mut wrong = old_receipt.clone();
        if let ReceiptImportOwner::Source { module_version, .. } = &mut wrong {
            *module_version = Some(new_helper.owner().module_version.clone());
        }
        assert!(matches!(
            validate_original_group_receipts(
                native_group.group(),
                &[wrong],
                native_group,
                original.original_native().unwrap(),
                &sources,
                &BTreeMap::new(),
                &mut validation
            ),
            Err(CertificationError::Mismatch("shared home import ownership"))
        ));
        let missing = available_original_source_map(
            &[original.clone(), new_helper],
            &[],
            &validation.inventory,
        )
        .unwrap();
        assert!(matches!(
            validate_original_group_receipts(
                native_group.group(),
                &[old_receipt.clone()],
                native_group,
                original.original_native().unwrap(),
                &missing,
                &BTreeMap::new(),
                &mut validation
            ),
            Err(CertificationError::Mismatch("source binder/group closure"))
        ));
        let changed_body = full_native_fixture("Consumer", vec![(11, vec![])], 7);
        assert!(matches!(
            validate_original_group_receipts(
                changed_body.original_native().unwrap().groups[0].group(),
                &[old_receipt],
                native_group,
                original.original_native().unwrap(),
                &sources,
                &BTreeMap::new(),
                &mut validation
            ),
            Err(CertificationError::Mismatch("shared original home groups"))
        ));
        let canonical = original.module_interface().unwrap();
        assert!(matches_cached_original_reoffer(
            &original,
            original.owner(),
            original.product_bytes(),
            original.package_imports_bytes(),
            canonical
        ));
        let mut changed_bytes = original.product_bytes().to_vec();
        changed_bytes[0] ^= 1;
        assert!(!matches_cached_original_reoffer(
            &original,
            original.owner(),
            &changed_bytes,
            original.package_imports_bytes(),
            canonical
        ));
        assert!(!matches_cached_original_reoffer(
            &original,
            original.owner(),
            original.product_bytes(),
            b"different package witness",
            canonical
        ));
        let different_canonical = fixture_finalized_product(
            original_groups_fixture(
                "Consumer",
                vec![(11, vec![retained(3)])],
                7,
                &BTreeMap::new(),
            ),
            [2; 32],
        );
        assert!(!matches_cached_original_reoffer(
            &original,
            original.owner(),
            original.product_bytes(),
            original.package_imports_bytes(),
            different_canonical.module_interface().unwrap()
        ));
        let mut selected = vec![admitted.clone()];
        let inherited = native_group
            .admitted(original.original_native().unwrap())
            .unwrap();
        append_original_selection(
            &mut selected,
            std::slice::from_ref(&inherited),
            &validation.inventory,
            &ValidatedPromotionSharing::default(),
        )
        .unwrap();
        assert_eq!(selected, vec![inherited.clone()]);
        assert!(Arc::ptr_eq(&selected[0].group, &inherited.group));
        assert!(Arc::ptr_eq(&selected[0].imports, &inherited.imports));
        let before = original.original_byte_anchors();
        let retained_original = original.clone();
        assert!(before
            .iter()
            .zip(retained_original.original_byte_anchors())
            .all(|(old, retained)| Arc::ptr_eq(old, retained)));
        assert!(matches!(
            append_original_selection(
                &mut vec![admitted.clone(), admitted.clone()],
                &[],
                &validation.inventory,
                &ValidatedPromotionSharing::default(),
            ),
            Err(CertificationError::Mismatch(
                "duplicate current original ordinal"
            ))
        ));
        let mut unproved_promotion = admitted.clone();
        unproved_promotion.origin = ProductOrigin::RetainedCore;
        assert!(matches!(append_original_selection(
            &mut vec![unproved_promotion], std::slice::from_ref(&inherited),
            &validation.inventory, &ValidatedPromotionSharing::default(),
        ), Err(CertificationError::OriginalGroupConflict(conflict))
            if conflict.owner == *original.owner()
                && conflict.failure == (OriginalGroupFailure::SelectionOverlap {
                    ordinal: 11,
                    current_origin: ProductOrigin::RetainedCore,
                    inherited_origin: ProductOrigin::Cached,
                    body_matches: true,
                    imports_match: true,
                })
        ));
        let mut contradictory = inherited.clone();
        contradictory.imports = vec![retained(99)].into();
        assert!(matches!(
            append_original_selection(&mut vec![admitted], &[contradictory], &validation.inventory,
                &ValidatedPromotionSharing::default()),
            Err(CertificationError::OriginalGroupConflict(conflict))
                if conflict.owner == *original.owner()
                    && conflict.failure == (OriginalGroupFailure::SelectionOverlap {
                        ordinal: 11,
                        current_origin: ProductOrigin::Cached,
                        inherited_origin: ProductOrigin::Cached,
                        body_matches: true,
                        imports_match: false,
                    })
        ));
    }

    #[test]
    fn retained_promotion_rekeys_only_its_exact_source_owner() {
        let original = full_native_fixture("Promoted", vec![(3, vec![])], 7);
        let old = original.owner().clone();
        let mut staged = old.clone();
        staged.module_version = ModuleVersion([0; 32]);
        staged.product_sha256 = [9; 32];
        let binder = testing::identity("Promoted", "entry");
        let mut sources = SourceGroupMap::new();
        sources.insert(
            (old.clone(), 3, binder.clone()),
            (old.clone(), ProductOrigin::RetainedCore),
        );
        sources.insert(
            (staged.clone(), 3, binder.clone()),
            (staged.clone(), ProductOrigin::RetainedCore),
        );
        let operation = InventoryOperation::new(Default::default());
        let mut selection = CertifiedSourceSelection::new_product_ingress();
        selection
            .admit_current(
                &staged,
                ProductOrigin::RetainedCore,
                original.module_interface().unwrap(),
                &operation,
            )
            .unwrap();
        let versions = BTreeMap::from([(
            (staged.unit.clone(), staged.module.clone()),
            ModuleVersion([3; 32]),
        )]);
        selection.promote(&versions).unwrap();
        sources
            .promote(
                &BTreeMap::from([(staged.clone(), ModuleVersion([3; 32]))]),
                &ValidatedPromotionSharing::default(),
            )
            .unwrap();
        let mut final_owner = staged.clone();
        final_owner.module_version = ModuleVersion([3; 32]);
        assert!(sources.get(&(staged, 3, binder.clone())).is_none());
        assert!(sources.get(&(old, 3, binder.clone())).is_some());
        assert_eq!(
            selection.receipt_native_body_owners().collect::<Vec<_>>(),
            vec![&final_owner]
        );
        assert_eq!(
            resolve_receipt_owner_with_validation(
                ReceiptImportOwner::Source {
                    unit: final_owner.unit.clone(),
                    module: final_owner.module.clone(),
                    module_version: None,
                    original_ordinal: 3,
                    binder: binder.clone(),
                },
                &sources,
                Some(&selection),
                &BTreeMap::new(),
                &mut PackageInterfaceValidation::default()
            )
            .unwrap(),
            PendingImportOwner::Source {
                owner: final_owner,
                original_ordinal: 3,
                binder
            }
        );
    }

    #[test]
    fn retained_promotion_conflict_reports_exact_identity_and_provenance() {
        let original = inherited_owner("Promoted");
        let mut staged = original.clone();
        staged.module_version = ModuleVersion([0; 32]);
        let binder = testing::identity("Promoted", "entry");
        let mut sources = SourceGroupMap::new();
        sources.insert(
            (original.clone(), 3, binder.clone()),
            (original.clone(), ProductOrigin::Cached),
        );
        sources.insert(
            (staged.clone(), 3, binder.clone()),
            (staged.clone(), ProductOrigin::RetainedCore),
        );
        let failure = sources.promote(
            &BTreeMap::from([(staged, original.module_version.clone())]),
            &ValidatedPromotionSharing::default(),
        );
        let Err(CertificationError::DuplicateSourceBinder(conflict)) = failure else {
            panic!("convergent promotion must retain its exact conflict");
        };
        assert_eq!(conflict.phase, SourceBinderPhase::NativePromotion);
        assert_eq!(conflict.owner, original);
        assert_eq!(conflict.original_ordinal, 3);
        assert_eq!(conflict.binder, binder);
        assert!(matches!(
            (conflict.existing_origin, conflict.incoming_origin),
            (ProductOrigin::Cached, ProductOrigin::RetainedCore)
                | (ProductOrigin::RetainedCore, ProductOrigin::Cached)
        ));
    }

    #[test]
    fn authenticated_promotion_convergence_requires_exact_sharing_proof() {
        let original =
            full_native_fixture("PromotedAuthenticated", vec![(3, vec![]), (11, vec![])], 7);
        let native = original.original_native().unwrap();
        let selected = [native.groups[0].admitted(native).unwrap()];
        let operation = InventoryOperation::new(Default::default());
        let membership =
            AvailableOriginalSources::authenticate(std::slice::from_ref(&original), &operation)
                .unwrap();
        let mut sources = membership.overlay(&selected, &operation).unwrap();
        let mut staged = original.owner().clone();
        staged.module_version = ModuleVersion([0; 32]);
        let binder = native.groups[0].group.binders()[0].clone();
        sources.insert(
            (staged.clone(), 3, binder.clone()),
            (staged.clone(), ProductOrigin::RetainedCore),
        );
        let failure = sources.promote(
            &BTreeMap::from([(staged, original.owner().module_version.clone())]),
            &ValidatedPromotionSharing::default(),
        );
        let Err(CertificationError::DuplicateSourceBinder(conflict)) = failure else {
            panic!("authenticated convergence cannot infer sharing from equal owner stamps");
        };
        assert_eq!(conflict.phase, SourceBinderPhase::NativePromotion);
        assert_eq!(conflict.owner, *original.owner());
        assert_eq!(conflict.original_ordinal, 3);
        assert_eq!(conflict.binder, binder.clone());
        assert_eq!(conflict.existing_origin, ProductOrigin::Cached);
        assert_eq!(conflict.incoming_origin, ProductOrigin::RetainedCore);
        assert_eq!(
            sources.get(&(original.owner().clone(), 3, binder.clone())),
            Some(&(original.owner().clone(), ProductOrigin::Cached))
        );
        assert_eq!(membership.sources.groups.len(), 2);

        // A matching module name and version with a different exact byte stamp
        // remains a distinct membership, rather than gaining sharing authority.
        let mut different = original.owner().clone();
        different.product_sha256[0] ^= 1;
        different.module_version = ModuleVersion([0; 32]);
        let mut distinct = membership.overlay(&selected, &operation).unwrap();
        distinct.insert(
            (different.clone(), 3, binder.clone()),
            (different.clone(), ProductOrigin::RetainedCore),
        );
        distinct
            .promote(
                &BTreeMap::from([(different.clone(), original.owner().module_version.clone())]),
                &ValidatedPromotionSharing::default(),
            )
            .unwrap();
        different.module_version = original.owner().module_version.clone();
        assert_eq!(
            distinct.get(&(different.clone(), 3, binder.clone())),
            Some(&(different, ProductOrigin::RetainedCore))
        );
        assert_eq!(
            distinct.get(&(original.owner().clone(), 3, binder)),
            Some(&(original.owner().clone(), ProductOrigin::Cached))
        );
    }

    #[test]
    fn source_promotion_removes_all_changed_keys_before_inserting_destinations() {
        let first = inherited_owner("PromotionOrder");
        let mut second = first.clone();
        second.module_version.0[0] ^= 1;
        let binder = testing::identity("PromotionOrder", "entry");
        let mut sources = SourceGroupMap::new();
        sources.insert(
            (first.clone(), 3, binder.clone()),
            (first.clone(), ProductOrigin::Fresh),
        );
        sources.insert(
            (second.clone(), 3, binder.clone()),
            (second.clone(), ProductOrigin::RetainedCore),
        );
        sources
            .promote(
                &BTreeMap::from([
                    (first.clone(), second.module_version.clone()),
                    (second.clone(), first.module_version.clone()),
                ]),
                &ValidatedPromotionSharing::default(),
            )
            .unwrap();
        assert_eq!(sources.groups.len(), 2);
        assert_eq!(
            sources.get(&(first.clone(), 3, binder.clone())),
            Some(&(first, ProductOrigin::RetainedCore))
        );
        assert_eq!(
            sources.get(&(second.clone(), 3, binder)),
            Some(&(second, ProductOrigin::Fresh))
        );
    }

    #[test]
    fn exact_request_bounds_authentic_target_native_groups_before_admission() {
        use crate::artifact_inventory::{
            ArtifactEntry, ArtifactInventory, CanonicalProducerIdentity, CompilerInputProjection,
            NativeGroupKey,
        };
        use crate::declaration_context::{ExactCompileContext, ExactDeclarationContext};
        let producer_bytes = b"request-native-availability-consumer";
        let producer = CanonicalProducerIdentity::from_producer_bytes(producer_bytes);
        let product = recovered_witness_fixtures(&[fixture_finalized_product(
            original_groups_fixture_with_interface(
                "BoundedHelper",
                vec![(7, vec![]), (9001, vec![])],
                71,
                &BTreeMap::new(),
                b"bounded helper".to_vec(),
            ),
            producer.sha256(),
        )])
        .remove(0)
        .product;
        let entry = Arc::new(ArtifactEntry::original(producer.sha256(), product.clone()).unwrap());
        let mut unexpected = Vec::new();
        let mut observed = 0;
        for mode in ["canonical", "issued", "full"] {
            let inventory = ArtifactInventory::default();
            let mut full_selection = None;
            let view = if mode == "full" {
                let complete = inventory
                    .admit_shared(&inventory.empty_view(), vec![entry.clone()])
                    .unwrap();
                let roles = CompilerInputProjection::from_issued_entries(&[entry.clone()]).unwrap();
                let support = crate::declaration_context::recover_fixture_compiler_support(
                    roles.clone(),
                    complete.clone(),
                    [],
                )
                .unwrap();
                let owner = entry.descriptor.owner.clone();
                let seed_context = ExactDeclarationContext::from_authenticated_execution(
                    producer.sha256(),
                    &complete,
                    roles.clone(),
                    vec![crate::declaration_join::ExactLexicalNode {
                        owner: owner.clone(),
                        imports: vec![],
                    }],
                    owner,
                    &[],
                )
                .unwrap();
                let seed_root = tempfile::tempdir().unwrap();
                let seed_request = ExactCompileContext::new(Arc::new(seed_context))
                    .prepare_compilation(seed_root.path(), producer_bytes)
                    .unwrap();
                let seed_availability = seed_request
                    .compiler_inputs()
                    .native_availability(entry.descriptor.id)
                    .unwrap();
                assert!(seed_availability.permits(9001));
                assert!(seed_availability
                    .offers()
                    .any(|offer| offer.original() == entry.descriptor.id && offer.is_full()));
                full_selection = Some(
                    CertifiedSourceSelection::from_compiler_inputs(
                        seed_request.compiler_inputs(),
                        &InventoryOperation::new(Default::default()),
                    )
                    .unwrap(),
                );
                let narrowed = support
                    .select_support_roots(vec![roles.roles()[0].interface()])
                    .unwrap()
                    .finalize_namespace()
                    .unwrap();
                let available = complete
                    .select_issued(
                        roles
                            .roles()
                            .iter()
                            .flat_map(|role| {
                                std::iter::once(role.interface()).chain(role.original())
                            })
                            .collect(),
                        &crate::artifact_inventory::ExactArtifactSelection::capture(
                            narrowed.artifacts(),
                        ),
                    )
                    .unwrap();
                assert!(available.selected_native_groups().is_empty());
                available
            } else {
                inventory
                    .admit_recovery_selection(
                        &inventory.empty_view(),
                        vec![entry.clone()],
                        &BTreeSet::from([NativeGroupKey {
                            artifact: entry.descriptor.id,
                            original_ordinal: 7,
                        }]),
                    )
                    .unwrap()
            };
            let projection =
                CompilerInputProjection::from_issued_entries(&[entry.clone()]).unwrap();
            let projection = if mode == "canonical" {
                projection.interface_only()
            } else {
                projection
            };
            let owner = entry.descriptor.owner.clone();
            let lexical = vec![crate::declaration_join::ExactLexicalNode {
                owner: owner.clone(),
                imports: vec![],
            }];
            let context = if let Some(selection) = &full_selection {
                let context = ExactDeclarationContext::from_source_selection(
                    producer.sha256(),
                    selection,
                    &view,
                    lexical,
                    owner,
                    &[],
                )
                .unwrap();
                assert!(context
                    .compiler_source_support()
                    .native_offers()
                    .iter()
                    .any(|offer| offer.original() == entry.descriptor.id && offer.is_full()));
                assert!(context.artifact_view().selected_native_groups().is_empty());
                context
            } else {
                ExactDeclarationContext::from_authenticated_execution(
                    producer.sha256(),
                    &view,
                    projection,
                    lexical,
                    owner,
                    &[],
                )
                .unwrap()
            };
            let root = tempfile::tempdir().unwrap();
            let request = ExactCompileContext::new(Arc::new(context))
                .prepare_compilation(root.path(), producer_bytes)
                .unwrap();
            if mode == "full" {
                assert!(request
                    .compiler_inputs()
                    .artifacts()
                    .selected_native_groups()
                    .is_empty());
                assert!(
                    request.groups.is_empty(),
                    "carried Full availability does not select executable groups"
                );
            }
            let scope: Value =
                ciborium::de::from_reader(std::fs::read(&request.manifest).unwrap().as_slice())
                    .unwrap();
            let native = scope.as_array().unwrap()[6].as_array().unwrap();
            if mode == "canonical" {
                assert!(native.is_empty());
            } else {
                assert_eq!(native.len(), 1);
                let expected = if mode == "full" {
                    value_array([value_text("full-carrier")])
                } else {
                    value_array([
                        value_text("issued-groups"),
                        value_array([Value::Integer(7.into())]),
                    ])
                };
                assert_eq!(native[0].as_array().unwrap()[8], expected);
                assert_eq!(
                    native[0].as_array().unwrap()[9],
                    value_text("compiler-original")
                );
            }
            let inventory = request.compiler_inputs().artifacts().inventory();
            let mut validation = PackageInterfaceValidation::default();
            let selection = CertifiedSourceSelection::from_compiler_inputs(
                request.compiler_inputs(),
                &validation.inventory,
            )
            .unwrap();
            assert!(
                crate::declaration_context::OriginalCompilerInputs::from_issued_support(
                    request.compiler_inputs().compiler_source_support(),
                )
                .physical_cohort()
                .is_err()
            );
            let physical = inventory
                .bind_segment(
                    request.compiler_inputs().artifacts(),
                    vec![],
                    &selection,
                    &mut validation,
                )
                .unwrap();
            let membership = request
                .compiler_inputs()
                .available_original_sources(std::slice::from_ref(&product), &validation.inventory)
                .unwrap();
            if mode == "issued" {
                // An already certified native body owns its historical child
                // independently of this request's direct compiler selection.
                let edge = PendingImportOwner::Source {
                    owner: product.owner().clone(),
                    original_ordinal: 9001,
                    binder: testing::identity("BoundedHelper", "entry_9001"),
                };
                let historical =
                    full_native_fixture("ProtectedHistory", vec![(11, vec![edge.clone()])], 72);
                let original = &historical.original_native().unwrap().groups[0];
                let receipt = ReceiptImportOwner::Source {
                    unit: product.owner().unit.clone(),
                    module: product.owner().module.clone(),
                    module_version: Some(product.owner().module_version.clone()),
                    original_ordinal: 9001,
                    binder: testing::identity("BoundedHelper", "entry_9001"),
                };
                let sources = membership
                    .overlay(&request.groups, &validation.inventory)
                    .unwrap();
                let checked = validate_original_group_receipts(
                    original.group(),
                    &[receipt],
                    original,
                    historical.original_native().unwrap(),
                    &sources,
                    &BTreeMap::new(),
                    &mut validation,
                )
                .unwrap();
                assert_eq!(checked.imports(), &[edge]);
            }
            let before_targets = inventory.metrics().issued_scope_nodes;
            for ordinal in [7, 9001] {
                observed += 1;
                let accepted = source_target_observations(&[(&product, ordinal)]);
                let target = prepared_target_fixture(&accepted);
                let observed_target =
                    AuthenticatedTargetImports::issue(&target, &accepted, &validation.inventory)
                        .unwrap();
                let outcome = inventory
                    .select_native_target(
                        physical.physical_inputs().physical_cohort().unwrap(),
                        physical.source_selection(),
                        observed_target,
                        None,
                        None,
                        &[],
                        &BTreeMap::new(),
                        &mut validation,
                    )
                    .map(|selected| selected.artifacts().selected_native_groups());
                if mode == "canonical" {
                    assert!(matches!(
                        &outcome,
                        Err(crate::CompileError::CompilerEvidence(error))
                            if matches!(error.as_ref(), CertificationError::SourceOutsideCompilerSelection {
                                owner, requested_version, original_ordinal: None,
                            } if owner == &entry.descriptor.owner
                                && requested_version == &product.owner().module_version)
                    ));
                    let error = outcome.as_ref().unwrap_err();
                    let envelope = crate::classify_compile(error);
                    assert_eq!(envelope.class, crate::FailureClass::VersionSkew);
                    assert_eq!(envelope.phase, crate::Phase::Compile);
                    assert_eq!(
                        envelope.cause,
                        Some(crate::failclass::CompileFailureCause::CompilerEvidence {
                            failure: crate::failclass::CompilerEvidenceFailure::Contract,
                        })
                    );
                    assert_eq!(error.to_string(), "compiler evidence rejected: compiler product certificate disagrees with source outside compiler selection");
                } else if mode == "issued" && ordinal == 9001 {
                    assert!(matches!(
                        &outcome,
                        Err(crate::CompileError::ArtifactInventory(error))
                            if error.failure == crate::artifact_inventory::ArtifactInventoryFailure::NativeGroupUnavailable {
                                artifact: entry.descriptor.id, original_ordinal: 9001,
                            } && matches!(error.native_refusal, Some(crate::artifact_inventory::NativeAdmissionRefusal::InputPermissionDenied {
                                body_present: true, ..
                            }))
                    ));
                }
                let expected = mode == "full" || (mode == "issued" && ordinal == 7);
                if expected {
                    let mut exact = view.selected_native_groups();
                    exact.insert(NativeGroupKey {
                        artifact: entry.descriptor.id,
                        original_ordinal: ordinal,
                    });
                    if outcome.as_ref().is_ok_and(|actual| actual != &exact) {
                        unexpected.push(format!("mode={mode} ordinal={ordinal} expected_groups={exact:?} actual={outcome:?}"));
                    }
                }
                if outcome.is_ok() != expected {
                    unexpected.push(format!("mode={mode} ordinal={ordinal} expected_accept={expected} actual={outcome:?}"));
                }
                eprintln!("native_availability_consumer mode={mode} ordinal={ordinal} expected_accept={expected} actual={outcome:?}");
            }
            assert_eq!(inventory.metrics().issued_scope_nodes, before_targets);
        }
        assert_eq!(observed, 6);
        assert!(unexpected.is_empty(), "{}", unexpected.join("\n"));
    }

    #[test]
    fn request_native_availability_survives_private_input_handoff() {
        use crate::artifact_inventory::{
            ArtifactEntry, ArtifactInventory, CanonicalProducerIdentity, CompilerInputProjection,
            NativeArtifactDemand, NativeGroupKey,
        };
        use crate::declaration_context::{
            ExactCompileContext, ExactDeclarationContext, OriginalCompilerInputs,
        };
        let producer_bytes = b"request-native-availability-handoff";
        let producer = CanonicalProducerIdentity::from_producer_bytes(producer_bytes);
        let product = recovered_witness_fixtures(&[fixture_finalized_product(
            original_groups_fixture_with_interface(
                "HandoffHelper",
                vec![(7, vec![]), (9001, vec![])],
                73,
                &BTreeMap::new(),
                b"handoff helper".to_vec(),
            ),
            producer.sha256(),
        )])
        .remove(0)
        .product;
        let entry = Arc::new(ArtifactEntry::original(producer.sha256(), product.clone()).unwrap());
        let mut unexpected = Vec::new();
        let mut observed = 0;
        for mode in ["full", "current", "empty", "partial"] {
            let inventory = ArtifactInventory::default();
            let projection =
                CompilerInputProjection::from_issued_entries(&[entry.clone()]).unwrap();
            let mut full_support = None;
            let view = if mode == "full" {
                let complete = inventory
                    .admit_shared(&inventory.empty_view(), vec![entry.clone()])
                    .unwrap();
                let no_offer = crate::declaration_context::recover_fixture_compiler_support(
                    projection.clone(),
                    complete.clone(),
                    [],
                )
                .unwrap();
                let no_offer_narrowed = no_offer
                    .select_support_roots(vec![projection.roles()[0].interface()])
                    .unwrap()
                    .finalize_namespace()
                    .unwrap();
                let no_offer_view = complete
                    .select_issued(
                        projection
                            .roles()
                            .iter()
                            .flat_map(|role| {
                                std::iter::once(role.interface()).chain(role.original())
                            })
                            .collect(),
                        &crate::artifact_inventory::ExactArtifactSelection::capture(
                            no_offer_narrowed.artifacts(),
                        ),
                    )
                    .unwrap();
                let no_offer_context = ExactDeclarationContext::from_authenticated_execution(
                    producer.sha256(),
                    &no_offer_view,
                    projection.clone(),
                    vec![crate::declaration_join::ExactLexicalNode {
                        owner: entry.descriptor.owner.clone(),
                        imports: vec![],
                    }],
                    entry.descriptor.owner.clone(),
                    &[],
                )
                .unwrap();
                let no_offer_root = tempfile::tempdir().unwrap();
                let no_offer_request = ExactCompileContext::new(Arc::new(no_offer_context))
                    .prepare_compilation(no_offer_root.path(), producer_bytes)
                    .unwrap();
                assert!(
                    !no_offer_request
                        .compiler_inputs()
                        .native_availability(entry.descriptor.id)
                        .unwrap()
                        .permits(9001),
                    "broad custody without carried Full cannot acquire the body"
                );
                let no_offer_wire: Value = ciborium::de::from_reader(
                    std::fs::read(&no_offer_request.manifest)
                        .unwrap()
                        .as_slice(),
                )
                .unwrap();
                assert_eq!(
                    no_offer_wire.as_array().unwrap()[6].as_array().unwrap()[0]
                        .as_array()
                        .unwrap()[8],
                    value_array([value_text("issued-groups"), value_array([])])
                );
                let available = inventory
                    .admit_shared_with_demand(
                        &inventory.empty_view(),
                        vec![entry.clone()],
                        NativeArtifactDemand::ScopeInterfaces,
                    )
                    .unwrap();
                let mut physical = CertifiedSourceSelection::from_compiler_projection(
                    &projection,
                    &available.metadata_snapshot(),
                    &PackageInterfaceValidation::default().inventory,
                )
                .unwrap();
                let completed = OriginalCompilerInputs::issue_segment_native_availability(
                    &mut physical,
                    &inventory.empty_view(),
                    vec![entry.clone()],
                    &mut crate::recovery_artifacts::PackageInterfaceValidation::default(),
                )
                .unwrap();
                let private = completed;
                let support =
                    crate::artifact_inventory::CompilerSourceSupport::close_complete_output(
                        &private,
                    )
                    .unwrap();
                let view = support.artifacts().clone();
                assert!(view.selected_native_groups().is_empty());
                full_support = Some(support);
                view
            } else {
                let selected = if mode == "partial" {
                    BTreeSet::from([NativeGroupKey {
                        artifact: entry.descriptor.id,
                        original_ordinal: 7,
                    }])
                } else {
                    BTreeSet::new()
                };
                inventory
                    .admit_recovery_selection(
                        &inventory.empty_view(),
                        vec![entry.clone()],
                        &selected,
                    )
                    .unwrap()
            };
            let context = Arc::new(if let Some(support) = full_support {
                ExactDeclarationContext::new(&[], &[], vec![])
                    .unwrap()
                    .extend_issued_compiler_support(&support)
                    .unwrap()
            } else {
                ExactDeclarationContext::from_authenticated_execution(
                    producer.sha256(),
                    &view,
                    projection,
                    vec![crate::declaration_join::ExactLexicalNode {
                        owner: entry.descriptor.owner.clone(),
                        imports: vec![],
                    }],
                    entry.descriptor.owner.clone(),
                    &[],
                )
                .unwrap()
            });
            let root = tempfile::tempdir().unwrap();
            let request = ExactCompileContext::new(context.clone())
                .prepare_compilation(&root.path().join("initial"), producer_bytes)
                .unwrap();
            let inventory = request.compiler_inputs().artifacts().inventory();
            let expected = match mode {
                "full" | "current" => value_array([value_text("full-carrier")]),
                "empty" => value_array([value_text("issued-groups"), value_array([])]),
                "partial" => value_array([
                    value_text("issued-groups"),
                    value_array([Value::Integer(7.into())]),
                ]),
                _ => unreachable!(),
            };
            let wire_mode = |request: &crate::declaration_context::ExactCompilationRequest| {
                let scope: Value =
                    ciborium::de::from_reader(std::fs::read(&request.manifest).unwrap().as_slice())
                        .unwrap();
                scope.as_array().unwrap()[6].as_array().unwrap()[0]
                    .as_array()
                    .unwrap()[8]
                    .clone()
            };
            let initial_expected = if mode == "current" {
                value_array([value_text("issued-groups"), value_array([])])
            } else {
                expected.clone()
            };
            assert_eq!(wire_mode(&request), initial_expected, "initial mode={mode}");
            let mut validation = PackageInterfaceValidation::default();
            let mut selection = CertifiedSourceSelection::from_compiler_inputs(
                request.compiler_inputs(),
                &validation.inventory,
            )
            .unwrap();
            let mut missing_input_owner = selection.clone();
            missing_input_owner.input_origin = CertifiedInputOrigin::NewProducts;
            assert!(matches!(
                OriginalCompilerInputs::from_selection(&missing_input_owner, request.compiler_inputs().artifacts()),
                Err(crate::CompileError::CompilerEvidence(error))
                    if matches!(*error, CertificationError::InputDecision {
                        reason: InputDecisionRefusal::MissingContinuationOwner, ..
                    })
            ), "a continuation cannot fall back to fresh policy when its exact input owner is lost");
            if mode == "current" {
                // A newly certified complete product is issued by the current
                // source owner, independently of this request's empty baseline.
                selection = CertifiedSourceSelection::new_product_ingress();
                selection
                    .admit_current(
                        product.owner(),
                        ProductOrigin::Fresh,
                        product.module_interface().unwrap(),
                        &validation.inventory,
                    )
                    .unwrap();
                selection
                    .bind_produced_originals(
                        &IssuedGroupCandidates::bind(Arc::from([]), &[product.clone()]).unwrap(),
                    )
                    .unwrap();
            }
            let current_output = if mode == "current" {
                Some(
                    OriginalCompilerInputs::issue_segment_native_availability(
                        &mut selection,
                        request.compiler_inputs().artifacts(),
                        vec![entry.clone()],
                        &mut validation,
                    )
                    .unwrap(),
                )
            } else {
                None
            };
            let baseline = current_output
                .as_ref()
                .map_or(request.compiler_inputs().artifacts(), |output| {
                    output.issued_artifacts()
                });
            for broaden in [false, true] {
                let custody = if broaden {
                    // A separately issued complete carrier is legitimate new custody;
                    // it cannot rewrite this earlier request's availability choice.
                    baseline
                        .retain_custody(
                            &inventory
                                .admit_shared(baseline, vec![entry.clone()])
                                .unwrap(),
                        )
                        .unwrap()
                } else {
                    baseline.clone()
                };
                let private = OriginalCompilerInputs::from_selection(&selection, &custody).unwrap();
                if mode != "current" {
                    let issued = request
                        .compiler_inputs()
                        .compiler_source_support()
                        .recorded_input_decisions();
                    assert!(issued.contains_key(&entry.descriptor.owner),
                        "the actual request issuer records the domain even when it chooses no Group");
                    assert_eq!(
                        private.issued_input_decisions().unwrap().recorded_facts(),
                        issued,
                        "certified continuation retains exact input choices despite extra custody mode={mode} broaden={broaden}",
                    );
                    if mode == "empty" {
                        assert!(issued[&entry.descriptor.owner].groups.is_empty());
                    }
                }
                let public = Arc::new(
                    crate::declaration_context::ExactDeclarationContext::from_authenticated_interfaces(
                        producer.sha256(),
                        &crate::artifact_inventory::ArtifactInventory::default().empty_view(),
                        crate::artifact_inventory::CompilerInputProjection::default(),
                    )
                        .unwrap(),
                );
                let next = ExactCompileContext::new(public)
                    .prepare_compilation_with_private_input(
                        &root.path().join(format!("next-{broaden}")),
                        producer_bytes,
                        None,
                        Some(private),
                    )
                    .unwrap();
                let actual_mode = wire_mode(&next);
                if actual_mode != expected {
                    unexpected.push(format!("mode={mode} broaden={broaden} expected={expected:?} actual={actual_mode:?}"));
                }
                eprintln!("native_availability_handoff mode={mode} broaden={broaden} actual={actual_mode:?}");
                let next_selection = CertifiedSourceSelection::from_compiler_inputs(
                    next.compiler_inputs(),
                    &validation.inventory,
                )
                .unwrap();
                assert!(
                    crate::declaration_context::OriginalCompilerInputs::from_issued_support(
                        next.compiler_inputs().compiler_source_support(),
                    )
                    .physical_cohort()
                    .is_err()
                );
                let physical = next
                    .compiler_inputs()
                    .artifacts()
                    .inventory()
                    .bind_segment(
                        next.compiler_inputs().artifacts(),
                        vec![],
                        &next_selection,
                        &mut validation,
                    )
                    .unwrap();
                if matches!(mode, "full" | "current") {
                    // Full transports body availability; the initial request
                    // deliberately chose no executable root for this owner.
                    assert!(next
                        .compiler_inputs()
                        .compiler_source_support()
                        .recorded_input_decisions()[&entry.descriptor.owner]
                        .groups
                        .is_empty());
                }
                let before_targets = physical
                    .physical_inputs()
                    .issued_artifacts()
                    .inventory()
                    .metrics()
                    .issued_scope_nodes;
                for ordinal in [7, 9001] {
                    observed += 1;
                    let accepted = source_target_observations(&[(&product, ordinal)]);
                    let target = prepared_target_fixture(&accepted);
                    let observed_target = AuthenticatedTargetImports::issue(
                        &target,
                        &accepted,
                        &validation.inventory,
                    )
                    .unwrap();
                    let outcome = next
                        .compiler_inputs()
                        .artifacts()
                        .inventory()
                        .select_native_target(
                            physical.physical_inputs().physical_cohort().unwrap(),
                            physical.source_selection(),
                            observed_target,
                            None,
                            None,
                            &[],
                            &BTreeMap::new(),
                            &mut validation,
                        )
                        .map(|selected| selected.artifacts().selected_native_groups());
                    eprintln!("native_availability_handoff_consumer mode={mode} broaden={broaden} ordinal={ordinal} outcome={outcome:?}");
                    let allowed = mode == "partial" && ordinal == 7;
                    if allowed {
                        let mut groups =
                            next.compiler_inputs().artifacts().selected_native_groups();
                        groups.insert(NativeGroupKey {
                            artifact: entry.descriptor.id,
                            original_ordinal: ordinal,
                        });
                        match outcome {
                            Ok(actual) => assert_eq!(actual, groups),
                            Err(error) => unexpected.push(format!("mode={mode} broaden={broaden} ordinal={ordinal} expected success actual={error:?}")),
                        }
                    } else if matches!(mode, "full" | "current") {
                        if !matches!(
                            &outcome,
                            Err(crate::CompileError::ArtifactInventory(error))
                                if error.failure == crate::artifact_inventory::ArtifactInventoryFailure::NativeGroupUnavailable {
                                    artifact: entry.descriptor.id, original_ordinal: ordinal,
                                } && matches!(&error.native_refusal, Some(crate::artifact_inventory::NativeAdmissionRefusal::RootChoiceExplicitEmpty {
                                    owner, original_ordinal,
                                }) if owner == &entry.descriptor.owner && *original_ordinal == ordinal)
                        ) {
                            unexpected.push(format!("mode={mode} broaden={broaden} ordinal={ordinal} expected empty initial choice actual={outcome:?}"));
                        }
                    } else if !matches!(
                        &outcome,
                        Err(crate::CompileError::ArtifactInventory(error))
                            if error.failure == crate::artifact_inventory::ArtifactInventoryFailure::NativeGroupUnavailable {
                                artifact: entry.descriptor.id, original_ordinal: ordinal,
                            } && matches!(error.native_refusal, Some(crate::artifact_inventory::NativeAdmissionRefusal::InputPermissionDenied {
                                body_present: true, ..
                            }))
                    ) {
                        unexpected.push(format!("mode={mode} broaden={broaden} ordinal={ordinal} expected typed refusal actual={outcome:?}"));
                    }
                }
                assert_eq!(
                    physical
                        .physical_inputs()
                        .issued_artifacts()
                        .inventory()
                        .metrics()
                        .issued_scope_nodes,
                    before_targets
                );
            }
        }
        assert_eq!(observed, 16);
        assert!(unexpected.is_empty(), "{}", unexpected.join("\n"));
    }

    #[test]
    fn source_support_projection_uses_only_issued_keys_and_keeps_all_interface_kinds() {
        use crate::artifact_inventory::{
            ArtifactEntry, ArtifactInventory, CompilerInputProjection, JoinedInterfaceRole,
        };
        let producer = [2; 32];
        let canonical = Arc::new(ArtifactEntry::canonical(fixture_module_interface(
            producer,
            "fixture",
            "Canonical",
            BTreeMap::new(),
        )));
        let joined = |module: &str, role| {
            let interface = fixture_module_interface(producer, "fixture", module, BTreeMap::new());
            Arc::new(ArtifactEntry::interface(
                crate::recovery_artifacts::CertifiedJoinedInterface::from_certification(
                    producer,
                    "fixture".into(),
                    module.into(),
                    interface.interface_bytes().to_vec(),
                    interface.package_imports_bytes().to_vec(),
                )
                .unwrap(),
                role,
                vec![],
            ))
        };
        let selected = vec![
            canonical,
            joined("CapturedValue", JoinedInterfaceRole::ValueInterface),
            joined("LexicalFacade", JoinedInterfaceRole::LexicalJoin),
        ];
        let projection = CompilerInputProjection::from_issued_entries(&selected).unwrap();
        let narrow_inventory = ArtifactInventory::default();
        let narrow = narrow_inventory
            .admit_shared(&narrow_inventory.empty_view(), selected.clone())
            .unwrap();
        let selection = CertifiedSourceSelection::from_compiler_projection(
            &projection,
            &narrow.metadata_snapshot(),
            &InventoryOperation::new(Default::default()),
        )
        .unwrap();
        for unrelated in [1, 32, 128] {
            let inventory = ArtifactInventory::default();
            let mut entries = selected.clone();
            entries.extend((0..unrelated).map(|index| {
                Arc::new(ArtifactEntry::canonical(fixture_module_interface(
                    producer,
                    "other",
                    &format!("Unrelated{index}"),
                    BTreeMap::new(),
                )))
            }));
            let broad = inventory
                .admit_shared(&inventory.empty_view(), entries)
                .unwrap();
            let before = inventory.metrics();
            let actual = selection.compiler_support_projection(&broad, &[]).unwrap();
            let after = inventory.metrics();
            assert_eq!(actual, projection);
            assert_eq!(after.view_queries - before.view_queries, 0);
            assert_eq!(after.graph_visits - before.graph_visits, 0);
            assert_eq!(after.entry_handle_copies - before.entry_handle_copies, 0);
            let expected = selection
                .compiler_projection_from_metadata(&broad.metadata_snapshot(), &BTreeSet::new())
                .unwrap();
            assert_eq!(actual, expected);
            eprintln!("source_support_projection unrelated={unrelated} selected_roles={} view_queries=0 graph_visits=0 metadata_handle_copies=0", actual.snapshot_roles().len());
        }
        let mut crossed = selection.clone();
        let modules = Arc::make_mut(&mut crossed.modules);
        let row = modules
            .remove(&("fixture".into(), "CapturedValue".into()))
            .unwrap();
        modules.insert(("fixture".into(), "WrongOwner".into()), row);
        assert!(matches!(
            crossed.compiler_support_projection(&narrow, &[]),
            Err(CertificationError::Mismatch(
                "issued compiler interface owner"
            ))
        ));
        assert!(matches!(
            selection.compiler_support_projection(&narrow_inventory.empty_view(), &[]),
            Err(CertificationError::Mismatch(
                "issued compiler interface artifact"
            ))
        ));
    }

    #[test]
    fn physical_native_issuance_survives_item_type_projection_without_future_demand() {
        use crate::artifact_inventory::{
            ArtifactBindingNode, ArtifactDependency, ArtifactEntry, ArtifactInventory,
            CanonicalProducerIdentity, CompilerInputProjection, JoinedInterfaceRole,
            NativeArtifactDemand, NativeGroupKey,
        };
        use crate::declaration_context::{ExactCompileContext, OriginalCompilerInputs};
        let producer_bytes = b"physical-new-product-issuance";
        let producer = CanonicalProducerIdentity::from_producer_bytes(producer_bytes);
        let future_module =
            tidepool_repr::SessionModule::val(tidepool_repr::Generation(11)).module_name();
        let future_identity = testing::identity(&future_module, "publishedB");
        let product = recovered_witness_fixtures(&[fixture_finalized_product(
            original_groups_fixture_with_interface(
                "PhysicalScaffold",
                vec![
                    (0, vec![]),
                    (
                        17,
                        vec![PendingImportOwner::Retained {
                            identity: future_identity,
                            generation: 11,
                        }],
                    ),
                ],
                81,
                &BTreeMap::new(),
                b"physical scaffold".to_vec(),
            ),
            producer.sha256(),
        )])
        .remove(0)
        .product;
        let native = Arc::new(ArtifactEntry::original(producer.sha256(), product.clone()).unwrap());
        let future_canonical = fixture_module_interface(
            producer.sha256(),
            &product.owner().unit,
            &future_module,
            BTreeMap::new(),
        );
        let future = Arc::new(ArtifactEntry::interface(
            crate::recovery_artifacts::CertifiedJoinedInterface::from_certification(
                producer.sha256(),
                product.owner().unit.clone(),
                future_module.clone(),
                future_canonical.interface_bytes().to_vec(),
                future_canonical.package_imports_bytes().to_vec(),
            )
            .unwrap(),
            JoinedInterfaceRole::ValueInterface,
            vec![],
        ));
        let entries = vec![native.clone(), future.clone()];
        let inventory = ArtifactInventory::default();
        let available = inventory
            .admit_shared_with_demand(
                &inventory.empty_view(),
                entries.clone(),
                NativeArtifactDemand::ScopeInterfaces,
            )
            .unwrap();
        let projection = CompilerInputProjection::from_issued_entries(&entries).unwrap();
        let mut physical = CertifiedSourceSelection::from_compiler_projection(
            &projection,
            &available.metadata_snapshot(),
            &PackageInterfaceValidation::default().inventory,
        )
        .unwrap();
        let future_owner = (product.owner().unit.clone(), future_module);
        let mut premature = physical.clone();
        Arc::make_mut(&mut premature.modules)
            .remove(&future_owner)
            .unwrap();
        let item_view = available.select_roots(vec![native.descriptor.id]).unwrap();
        assert!(matches!(
            OriginalCompilerInputs::issue_segment_native_availability(
                &mut premature,
                &inventory.empty_view(),
                vec![native.clone()],
                &mut PackageInterfaceValidation::default(),
            ),
            Err(crate::CompileError::ArtifactInventory(error))
                if matches!(error.failure, crate::artifact_inventory::ArtifactInventoryFailure::MissingDependency {
                    dependency: crate::artifact_inventory::ArtifactDependency::NativeBinding { dependent_ordinal: 17, generation: 11, .. }, ..
                })
        ));
        let completed = OriginalCompilerInputs::issue_segment_native_availability(
            &mut physical,
            &inventory.empty_view(),
            entries.clone(),
            &mut crate::recovery_artifacts::PackageInterfaceValidation::default(),
        )
        .unwrap();
        let physical_availability = physical.issued_native_availability().collect::<Vec<_>>();
        let [issued] = physical_availability.as_slice() else {
            panic!("one physical native product");
        };
        let issued = Arc::clone(issued);
        let issued_offer = issued
            .offers()
            .find(|offer| offer.proof().is_some())
            .unwrap()
            .clone();
        let proof_graph = issued_offer.proof().unwrap().selection.graph_selection();
        let groups = proof_graph
            .native_groups
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        assert_eq!(
            groups
                .iter()
                .map(|group| group.original_ordinal)
                .collect::<BTreeSet<_>>(),
            BTreeSet::from([0, 17]),
        );
        let issued_groups = proof_graph
            .selections
            .iter()
            .flat_map(|scope| &scope.dependencies)
            .filter_map(|(source, target, edge)| match (source, target, edge) {
                (
                    ArtifactBindingNode::Group(group),
                    ArtifactBindingNode::Artifact(carrier),
                    ArtifactDependency::Interface,
                ) if groups.contains(group) && carrier.artifact == group.binding.artifact() => {
                    Some((*group, *carrier))
                }
                _ => None,
            })
            .collect::<BTreeMap<_, _>>();
        assert_eq!(issued_groups.len(), groups.len());
        assert_eq!(issued_groups, issued_offer.issued_group_carriers().unwrap());
        let required_scopes = proof_graph
            .bindings
            .iter()
            .map(|binding| binding.selection)
            .chain(groups.iter().map(|group| group.binding.selection()))
            .collect::<BTreeSet<_>>();
        assert_eq!(issued_offer.required_scopes(), &required_scopes);
        assert!(
            issued_groups
                .iter()
                .any(|(group, carrier)| { group.binding.selection() != carrier.selection }),
            "the control must exercise independent group and carrier scopes"
        );
        let before = inventory.metrics();
        let mut item = physical.clone();
        Arc::make_mut(&mut item.modules)
            .remove(&future_owner)
            .unwrap();
        assert!(Arc::ptr_eq(
            item.issued_native_availability().next().unwrap(),
            &issued
        ));
        let current_key = crate::artifact_inventory::NativeGroupKey {
            artifact: native.descriptor.id,
            original_ordinal: *native.native_group_ordinals.first().unwrap(),
        };
        assert!(physical
            .current_product(current_key, &native)
            .unwrap()
            .is_some());
        assert!(item
            .current_product(current_key, &native)
            .unwrap()
            .is_some());
        let private = OriginalCompilerInputs::from_selection(&item, &item_view).unwrap();
        assert_eq!(
            inventory.metrics().issued_scope_nodes,
            before.issued_scope_nodes,
            "an item must carry physical issuance without issuing another graph"
        );
        let root = tempfile::tempdir().unwrap();
        let request = ExactCompileContext::new(Arc::new(
            crate::declaration_context::ExactDeclarationContext::from_authenticated_interfaces(
                producer.sha256(),
                &crate::artifact_inventory::ArtifactInventory::default().empty_view(),
                crate::artifact_inventory::CompilerInputProjection::default(),
            )
            .unwrap(),
        ))
        .prepare_compilation_with_private_input(root.path(), producer_bytes, None, Some(private))
        .unwrap();
        let inputs = request.compiler_inputs();
        let inherited = CertifiedSourceSelection::from_compiler_inputs(
            inputs,
            &PackageInterfaceValidation::default().inventory,
        )
        .unwrap();
        assert!(
            inherited
                .current_product(current_key, &native)
                .unwrap()
                .is_none(),
            "carrying actual Full availability cannot restamp physical output membership"
        );
        assert!(inputs
            .native_availability(native.descriptor.id)
            .unwrap()
            .permits(17));
        assert!(!inputs
            .artifacts()
            .contains_namespace_artifact(future.descriptor.id));
        assert!(inputs.artifacts().selected_native_groups().is_empty());
        assert!(request.groups.is_empty());
        let request_availability = inputs.native_availability(native.descriptor.id).unwrap();
        let request_offers = request_availability
            .offers()
            .filter(|offer| offer.proof().is_some())
            .collect::<Vec<_>>();
        let [request_offer] = request_offers.as_slice() else {
            panic!("one physical native offer remains in the request");
        };
        assert!(request_offer.is_full());
        assert!(request_offer.same_issuance(&issued_offer));
        assert_eq!(
            issued_groups,
            request_offer.issued_group_carriers().unwrap()
        );
        let inventory = inputs.artifacts().inventory();
        let mut target_validation = PackageInterfaceValidation::default();
        let observations = source_target_observations(&[(&product, 0)]);
        let prepared = prepared_target_fixture(&observations);
        let observed = AuthenticatedTargetImports::issue(
            &prepared,
            &observations,
            &target_validation.inventory,
        )
        .unwrap();
        let current = inventory
            .select_native_target(
                completed.physical_cohort().unwrap(),
                &item,
                observed,
                None,
                Some(&inventory.empty_view()),
                &[],
                &BTreeMap::new(),
                &mut target_validation,
            )
            .unwrap()
            .artifacts()
            .clone();
        assert_eq!(
            current.selected_native_groups(),
            BTreeSet::from([NativeGroupKey {
                artifact: native.descriptor.id,
                original_ordinal: 0,
            }])
        );
        assert!(!current.artifact_ids().contains(&future.descriptor.id));
        let observations = source_target_observations(&[(&product, 17)]);
        let prepared = prepared_target_fixture(&observations);
        let observed = AuthenticatedTargetImports::issue(
            &prepared,
            &observations,
            &target_validation.inventory,
        )
        .unwrap();
        assert!(
            inventory
                .select_native_target(
                    completed.physical_cohort().unwrap(),
                    &item,
                    observed,
                    None,
                    Some(&current),
                    &[],
                    &BTreeMap::new(),
                    &mut target_validation,
                )
                .is_err(),
            "issued availability cannot authorize future item type demand"
        );
        let observations = source_target_observations(&[(&product, 0), (&product, 17)]);
        let prepared = prepared_target_fixture(&observations);
        let observed = AuthenticatedTargetImports::issue(
            &prepared,
            &observations,
            &target_validation.inventory,
        )
        .unwrap();
        let next = inventory
            .select_native_target(
                completed.physical_cohort().unwrap(),
                &physical,
                observed,
                None,
                Some(&current),
                &[future.clone()],
                &BTreeMap::new(),
                &mut target_validation,
            )
            .unwrap()
            .artifacts()
            .clone();
        assert!(next.contains_namespace_artifact(future.descriptor.id));
        assert_eq!(next.selected_native_groups().len(), 2);
    }

    pub(crate) fn assert_request_private_product_uses_carried_dependency(
        source: &crate::declaration_context::RequestCompilerInputs,
        consumer: &crate::recovery_artifacts::CertifiedRecoveryProduct,
        expected_dependency: crate::artifact_inventory::NativeGroupBinding,
        producer_bytes: &[u8],
        root: &Path,
    ) {
        use crate::artifact_inventory::{
            ArtifactBindingNode, ArtifactDependency, ArtifactEntry, ArtifactPayload,
            CanonicalProducerIdentity, CompilerInputRole, NativeArtifactDemand,
        };
        use crate::declaration_context::{
            ExactCompileContext, ExactDeclarationContext, NativeTransportMode,
            OriginalCompilerInputs,
        };
        let context = Arc::new(
            ExactDeclarationContext::new(&[], &[], vec![])
                .unwrap()
                .extend_issued_compiler_support(source.compiler_source_support())
                .unwrap(),
        );
        let request = ExactCompileContext::new(context.clone())
            .prepare_compilation(&root.join("input"), producer_bytes)
            .unwrap();
        let input = request.compiler_inputs();
        assert_eq!(input.projection(), source.projection());
        let selected = source.artifacts().selected_native_groups();
        assert_eq!(input.artifacts().selected_native_groups(), selected);
        let dependency_id = expected_dependency.binding.artifact();
        let dependency = input
            .artifacts()
            .entries_for_artifacts(&BTreeSet::from([dependency_id]))
            .unwrap();
        let [dependency] = dependency.as_slice() else {
            panic!("one exact input dependency")
        };
        let input_row = input.native_availability(dependency_id).unwrap();
        assert!(input_row.permits(7) && input_row.permits(9001));
        assert_eq!(
            input
                .private_native_availability()
                .snapshot_facts()
                .unwrap()[&dependency_id]
                .mode,
            NativeTransportMode::Full
        );
        let entry = Arc::new(
            ArtifactEntry::original(
                CanonicalProducerIdentity::from_producer_bytes(producer_bytes).sha256(),
                consumer.clone(),
            )
            .unwrap(),
        );
        assert!(!input
            .artifacts()
            .artifact_ids()
            .contains(&entry.descriptor.id));
        let operation = InventoryOperation::new(Default::default());
        let mut selection =
            CertifiedSourceSelection::from_compiler_inputs(input, &operation).unwrap();
        selection
            .admit_current(
                consumer.owner(),
                ProductOrigin::RetainedCore,
                consumer.module_interface().unwrap(),
                &operation,
            )
            .unwrap();
        selection
            .bind_produced_originals(
                &IssuedGroupCandidates::bind(Arc::from([]), &[consumer.clone()]).unwrap(),
            )
            .unwrap();
        let physical = input
            .artifacts()
            .inventory()
            .admit_shared_with_demand(
                input.artifacts(),
                vec![entry.clone()],
                NativeArtifactDemand::ScopeInterfaces,
            )
            .unwrap();
        let completed = OriginalCompilerInputs::from_selection(&selection, &physical).unwrap();
        let canonical = ArtifactEntry::canonical(consumer.module_interface().unwrap().clone());
        assert_eq!(
            completed.role_projection().snapshot_roles()[&entry.descriptor.owner],
            CompilerInputRole::InterfaceOnly {
                interface: canonical.descriptor.id
            }
        );
        assert_eq!(
            completed.issued_artifacts().selected_native_groups(),
            selected
        );
        assert!(selected
            .iter()
            .all(|key| key.artifact != entry.descriptor.id));
        let offer = completed
            .native_offers()
            .iter()
            .find(|offer| offer.original() == entry.descriptor.id)
            .unwrap()
            .clone();
        assert!(offer.is_full());
        let proof = offer.proof().unwrap();
        assert!(
            proof.issued_groups(completed.issued_artifacts()).is_err(),
            "carrier-only output does not own the consumer's opaque group proof"
        );
        let groups = offer.issued_group_carriers().unwrap();
        assert!(groups.contains_key(&expected_dependency));
        assert!(groups
            .keys()
            .filter(|group| group.binding.artifact() == dependency_id)
            .all(|group| group.original_ordinal == 7));
        let consumer_group = *groups
            .keys()
            .find(|group| {
                group.binding.artifact() == entry.descriptor.id && group.original_ordinal == 7
            })
            .unwrap();
        let edges = offer.custody_snapshot().binding_dependencies().unwrap();
        assert!(edges.contains(&(
            ArtifactBindingNode::Group(consumer_group),
            ArtifactBindingNode::Group(expected_dependency),
            ArtifactDependency::NativeGroup {
                dependent_ordinal: 7,
                required_ordinal: 7,
            }
        )));
        assert!(edges.contains(&(
            ArtifactBindingNode::Group(consumer_group),
            ArtifactBindingNode::Artifact(groups[&consumer_group]),
            ArtifactDependency::Interface
        )));
        let next = ExactCompileContext::new(context)
            .prepare_compilation_with_private_input(
                &root.join("completed"),
                producer_bytes,
                None,
                Some(completed),
            )
            .unwrap();
        assert_eq!(
            next.compiler_inputs().artifacts().selected_native_groups(),
            selected
        );
        let retained = next
            .compiler_inputs()
            .compiler_source_support()
            .native_offers()
            .iter()
            .find(|retained| retained.same_issuance(&offer))
            .unwrap();
        assert_eq!(retained.issued_group_carriers().unwrap(), groups);
        assert_eq!(
            next.compiler_inputs()
                .private_native_availability()
                .snapshot_facts()
                .unwrap()[&entry.descriptor.id]
                .mode,
            NativeTransportMode::Full
        );
        let retained_input = next
            .compiler_inputs()
            .native_availability(dependency_id)
            .unwrap();
        assert!(
            retained_input.permits(7) && retained_input.permits(9001),
            "a new output does not narrow an existing Input Full permission"
        );
        assert!(next.context().lexical_graph().is_empty());
        assert_eq!(
            next.context().original_instance_environment(),
            &crate::declaration_context::OriginalInstanceEnvironment::Unknown
        );
        // Observe physical row modes with literal writer positions; the opaque
        // C closure above remains restricted to A7 independently of Input Full.
        let bytes = std::fs::read(&next.manifest).unwrap();
        let wire: Value = ciborium::de::from_reader(bytes.as_slice()).unwrap();
        let fields = wire.as_array().unwrap();
        assert_eq!(fields.len(), 11);
        assert_eq!(fields[0], Value::Text("TPEXACTSCOPE".into()));
        assert_eq!(fields[1], Value::Text("16".into()));
        let rows = fields[6]
            .as_array()
            .unwrap()
            .iter()
            .map(|row| {
                let [unit, module, _, _, _, _, ordinals, _, mode, _] =
                    row.as_array().unwrap().as_slice()
                else {
                    panic!("native physical row has ten fields")
                };
                (
                    (
                        unit.as_text().unwrap().to_owned(),
                        module.as_text().unwrap().to_owned(),
                    ),
                    (
                        ordinals
                            .as_array()
                            .unwrap()
                            .iter()
                            .map(|value| u32::try_from(value.as_integer().unwrap()).unwrap())
                            .collect::<Vec<_>>(),
                        mode.clone(),
                    ),
                )
            })
            .collect::<BTreeMap<_, _>>();
        let full = Value::Array(vec![Value::Text("full-carrier".into())]);
        assert_eq!(
            rows[&(
                consumer.owner().unit.clone(),
                consumer.owner().module.clone()
            )],
            (Vec::new(), full.clone())
        );
        let ArtifactPayload::Original(dependency_product) = &dependency.payload else {
            unreachable!()
        };
        assert_eq!(
            rows[&(
                dependency_product.owner().unit.clone(),
                dependency_product.owner().module.clone()
            )],
            (vec![7, 9001], full)
        );
        assert_eq!(rows.len(), 2);
    }

    #[test]
    fn current_dependency_without_root_choice_refuses_two_issued_scopes() {
        use crate::artifact_inventory::{
            ArtifactBindingNode as InventoryNodeKey, ArtifactEntry, ArtifactInventory,
            ArtifactInventoryFailure, ArtifactPayload, CanonicalProducerIdentity,
            CompilerInputProjection, NativeArtifactDemand, NativeOriginalRequirement,
        };
        use crate::declaration_context::{ExactCompileContext, ExactDeclarationContext};
        let bytes = b"ambiguous-current-dependency";
        let producer = CanonicalProducerIdentity::from_producer_bytes(bytes);
        let helper_raw = fixture_finalized_product(
            original_groups_fixture_with_interface(
                "AmbiguousDependency",
                vec![(7, vec![])],
                81,
                &BTreeMap::new(),
                b"helper".to_vec(),
            ),
            producer.sha256(),
        );
        let helper_entry = ArtifactEntry::original(producer.sha256(), helper_raw.clone()).unwrap();
        let requirements = BTreeMap::from([(
            (
                helper_raw.owner().unit.clone(),
                helper_raw.owner().module.clone(),
            ),
            helper_entry.descriptor.interface_sha256,
        )]);
        let root_raw = ["AmbiguousLeft", "AmbiguousRight"].map(|module| {
            fixture_finalized_product_with_requirements(
                original_groups_fixture_with_interface(
                    module,
                    vec![(
                        3,
                        vec![PendingImportOwner::Source {
                            owner: helper_raw.owner().clone(),
                            original_ordinal: 7,
                            binder: testing::identity("AmbiguousDependency", "entry"),
                        }],
                    )],
                    82,
                    &BTreeMap::new(),
                    module.as_bytes().to_vec(),
                ),
                producer.sha256(),
                Some(requirements.clone()),
            )
        });
        let products =
            recovered_witness_fixtures(&[helper_raw, root_raw[0].clone(), root_raw[1].clone()]);
        let helper = Arc::new(
            ArtifactEntry::original(producer.sha256(), products[0].product.clone()).unwrap(),
        );
        let originals = [1, 2].map(|index| {
            Arc::new(
                ArtifactEntry::original(producer.sha256(), products[index].product.clone())
                    .unwrap(),
            )
        });
        let sources = originals.each_ref().map(|original| {
            let inventory = ArtifactInventory::default();
            inventory
                .admit_shared(
                    &inventory.empty_view(),
                    vec![helper.clone(), original.clone()],
                )
                .unwrap()
        });
        let interfaces = CompilerInputProjection::from_issued_entries(&[
            helper.clone(),
            originals[0].clone(),
            originals[1].clone(),
        ])
        .unwrap()
        .interface_only();
        let projection = interfaces
            .merge(&CompilerInputProjection::from_issued_entries(&originals).unwrap())
            .unwrap();
        let proofs =
            std::array::from_fn::<_, 2, _>(|index| (originals[index].as_ref(), &sources[index]))
                .map(|(original, source)| {
                    NativeOriginalRequirement::from_selected_view(original.descriptor.id, source)
                        .unwrap()
                        .unwrap()
                });
        let joined = sources[0]
            .merge_fixture_selected(&sources[1], &interfaces)
            .unwrap();
        let mut issued_selection = CertifiedSourceSelection::from_compiler_projection(
            &projection,
            &joined.metadata_snapshot(),
            &crate::recovery_artifacts::PackageInterfaceValidation::default().inventory,
        )
        .unwrap();
        issued_selection
            .with_new_product_dependencies(&joined.metadata_snapshot(), &proofs)
            .unwrap();
        let selected = joined
            .inventory()
            .admit_certified_with_demand(
                &joined,
                originals.to_vec(),
                NativeArtifactDemand::ScopeInterfaces,
                &issued_selection,
            )
            .unwrap();
        let support =
            crate::declaration_context::issue_fixture_compiler_support(projection, selected)
                .unwrap();
        let context = Arc::new(
            ExactDeclarationContext::new(&[], &[], vec![])
                .unwrap()
                .admit_producer(producer.sha256())
                .unwrap()
                .extend_issued_compiler_support(&support)
                .unwrap(),
        );
        let scratch = tempfile::tempdir().unwrap();
        let request = ExactCompileContext::new(context)
            .prepare_compilation(scratch.path(), bytes)
            .unwrap();
        // The real request carries two distinct, permitted exact issuances of
        // the same payload/ordinal, and no selected execution root for either.
        let availability = request
            .compiler_inputs()
            .native_availability(helper.descriptor.id)
            .unwrap();
        assert!(availability.permits(7));
        let expected = availability
            .offers()
            .filter_map(|offer| offer.proof())
            .flat_map(|proof| proof.selection.graph_selection().native_groups.iter())
            .filter(|group| {
                group.binding.artifact() == helper.descriptor.id && group.original_ordinal == 7
            })
            .copied()
            .collect::<BTreeSet<_>>();
        assert_eq!(expected.len(), 2);
        assert!(!request.compiler_inputs().artifacts().capture_graph_selection().roots.iter().any(|node| matches!(node, InventoryNodeKey::Group(group) if group.binding.artifact() == helper.descriptor.id)));
        let product = fixture_finalized_product_with_requirements(
            original_groups_fixture_with_interface(
                "NeedsAmbiguousDependency",
                vec![(
                    5,
                    vec![PendingImportOwner::Source {
                        owner: products[0].product.owner().clone(),
                        original_ordinal: 7,
                        binder: testing::identity("AmbiguousDependency", "entry"),
                    }],
                )],
                83,
                &BTreeMap::new(),
                b"new parent".to_vec(),
            ),
            producer.sha256(),
            Some(requirements),
        );
        let product = recovered_witness_fixtures(&[product]).remove(0).product;
        let entry = Arc::new(ArtifactEntry::original(producer.sha256(), product).unwrap());
        let ArtifactPayload::Original(product) = &entry.payload else {
            unreachable!()
        };
        let mut validation = crate::recovery_artifacts::PackageInterfaceValidation::default();
        let mut selection = CertifiedSourceSelection::from_compiler_inputs(
            request.compiler_inputs(),
            &validation.inventory,
        )
        .unwrap();
        selection
            .admit_current(
                product.owner(),
                ProductOrigin::Cached,
                product.module_interface().unwrap(),
                &validation.inventory,
            )
            .unwrap();
        selection
            .bind_produced_originals(
                &IssuedGroupCandidates::bind(Arc::from([]), &[product.clone()]).unwrap(),
            )
            .unwrap();
        let output = crate::declaration_context::certified_product_artifact_view_with_validation(
            producer.sha256(),
            &[product.clone()],
            &[],
            &[],
            Some(request.compiler_inputs().artifacts()),
            NativeArtifactDemand::ScopeInterfaces,
            &mut validation,
        )
        .unwrap();
        let inventory = output.inventory();
        let before = output.capture_graph_selection();
        let bound_error = inventory
            .bind_segment(
                &output,
                vec![],
                &selection,
                &mut crate::recovery_artifacts::PackageInterfaceValidation::default(),
            )
            .err()
            .expect("product completion must consume the same unresolved input choice");
        assert!(
            matches!(bound_error, crate::CompileError::ArtifactInventory(error) if error.failure == ArtifactInventoryFailure::BindingAmbiguity { artifact: helper.descriptor.id })
        );
        assert_eq!(output.capture_graph_selection(), before);
    }

    #[test]
    fn fresh_same_key_group_keeps_selected_historical_descendant() {
        use crate::artifact_inventory::{
            ArtifactBindingNode, ArtifactDependency, ArtifactEntry, ArtifactInventory,
            CanonicalProducerIdentity, CompilerInputProjection, CompilerSourceSupport,
            NativeArtifactDemand, NativeGroupKey, NativeOriginalRequirement,
        };
        use crate::declaration_context::{ExactDeclarationContext, OriginalCompilerInputs};
        let producer = CanonicalProducerIdentity::from_producer_bytes(b"mixed-current-historical-key");
        let values_old =
            fixture_module_interface(producer.sha256(), "fixture", "Values", BTreeMap::new());
        let values_new = fixture_module_core(&values_old, b"new captured Values Core".to_vec());
        let values_old = Arc::new(ArtifactEntry::canonical(values_old));
        let values_new = Arc::new(ArtifactEntry::canonical(values_new));
        assert_eq!(values_old.descriptor.owner, values_new.descriptor.owner);
        assert_ne!(values_old.descriptor.id, values_new.descriptor.id);
        let source = |product: &crate::recovery_artifacts::CertifiedRecoveryProduct, ordinal| {
            let definitions = original_native_group_definitions(product, ordinal).unwrap();
            let binding = match &definitions.bindings()[0] {
                tidepool_repr::execution_schema::Group::NonRecursive(binding) => binding,
                tidepool_repr::execution_schema::Group::Recursive(bindings) => &bindings[0],
            };
            PendingImportOwner::Source {
                owner: product.owner().clone(),
                original_ordinal: ordinal,
                binder: binding.identity.clone(),
            }
        };
        let g = fixture_finalized_product(
            original_groups_fixture_with_interface(
                "MixedG",
                vec![(
                    7,
                    vec![PendingImportOwner::Retained {
                        identity: testing::identity("Values", "value"),
                        generation: 4,
                    }],
                )],
                91,
                &BTreeMap::new(),
                b"G interface".to_vec(),
            ),
            producer.sha256(),
        );
        let g = recovered_witness_fixtures(&[g]).remove(0).product;
        let r = fixture_finalized_product_with_requirements(
            original_groups_fixture_with_interface(
                "MixedR",
                vec![(8, vec![source(&g, 7)])],
                92,
                &BTreeMap::new(),
                b"R interface".to_vec(),
            ),
            producer.sha256(),
            Some(BTreeMap::from([(
                (g.owner().unit.clone(), g.owner().module.clone()),
                g.module_interface().unwrap().interface_sha256(),
            )])),
        );
        let r = recovered_witness_fixtures(&[r]).remove(0).product;
        let g_entry = Arc::new(ArtifactEntry::original(producer.sha256(), g.clone()).unwrap());
        let r_entry = Arc::new(ArtifactEntry::original(producer.sha256(), r.clone()).unwrap());
        let inventory = ArtifactInventory::default();
        let physical = inventory
            .admit_shared_with_demand(
                &inventory.empty_view(),
                vec![g_entry.clone(), r_entry.clone(), values_old.clone()],
                NativeArtifactDemand::AllGroups,
            )
            .unwrap();
        let g_interface = Arc::new(ArtifactEntry::canonical(
            g.module_interface().unwrap().clone(),
        ));
        let projection =
            CompilerInputProjection::from_issued_entries(&[r_entry.clone(), g_interface]).unwrap();
        let mut validation = PackageInterfaceValidation::default();
        let requirements =
            NativeOriginalRequirement::for_projection(&projection, &physical, &[]).unwrap();
        assert_eq!(requirements.len(), 1);
        let mut original = CertifiedSourceSelection::from_compiler_projection(
            &projection,
            &physical.metadata_snapshot(),
            &validation.inventory,
        )
        .unwrap();
        original
            .with_new_product_dependencies(&physical.metadata_snapshot(), &requirements)
            .unwrap();
        let output = OriginalCompilerInputs::issue_segment_native_availability(
            &mut original,
            &physical,
            vec![r_entry.clone()],
            &mut crate::recovery_artifacts::PackageInterfaceValidation::default(),
        )
        .unwrap();
        let closure = original
            .selected_original_closure(output.issued_artifacts())
            .unwrap();
        eprintln!(
            "initial completed native rows: R={:?} G={:?}; R={} G={}",
            r_entry.descriptor.id,
            g_entry.descriptor.id,
            output
                .native_availability()
                .issued_row(r_entry.descriptor.id)
                .is_some(),
            output
                .native_availability()
                .issued_row(g_entry.descriptor.id)
                .is_some(),
        );
        let completed = CompilerSourceSupport::close_complete_output(&output).unwrap();
        let support = completed.certify_original_closure(&closure).unwrap_or_else(|error| {
            panic!(
                "initial closure transfer: {error:?}; R={:?} G={:?} Rcanonical={:?} Gcanonical={:?}; roles={:?}; receiving_groups={:?}; closure_groups={:?}",
                r_entry.descriptor.id,
                g_entry.descriptor.id,
                ArtifactEntry::canonical_artifact_id(r.module_interface().unwrap()),
                ArtifactEntry::canonical_artifact_id(g.module_interface().unwrap()),
                completed.projection().snapshot_roles(),
                completed.artifacts().capture_graph_selection().native_groups,
                closure.native_closure().capture_graph_selection().native_groups,
            )
        });
        let old_groups = support.artifacts().capture_graph_selection().native_groups;
        assert_eq!(old_groups.len(), 2);
        let old_g = *old_groups
            .iter()
            .find(|group| group.binding.artifact() == g_entry.descriptor.id)
            .unwrap();
        let old_r = *old_groups
            .iter()
            .find(|group| group.binding.artifact() == r_entry.descriptor.id)
            .unwrap();
        let old_edges = support.artifacts().binding_dependencies();
        assert!(old_edges.contains(&(
            ArtifactBindingNode::Group(old_r),
            ArtifactBindingNode::Group(old_g),
            ArtifactDependency::NativeGroup {
                dependent_ordinal: 8,
                required_ordinal: 7
            },
        )));
        let old_value = old_edges
            .iter()
            .find_map(|(from, to, edge)| {
                if *from != ArtifactBindingNode::Group(old_g)
                    || !matches!(edge, ArtifactDependency::NativeBinding { .. })
                {
                    return None;
                }
                match to {
                    ArtifactBindingNode::Artifact(binding) => Some(*binding),
                    _ => None,
                }
            })
            .unwrap();
        assert_eq!(old_value.artifact, values_old.descriptor.id);
        let context = ExactDeclarationContext::new(&[], &[], Vec::new())
            .unwrap()
            .extend_issued_compiler_support(&support)
            .unwrap();
        let request = context
            .capture_world_primary_compiler_inputs(producer.sha256())
            .unwrap();
        assert!(!request
            .projection()
            .snapshot_roles()
            .contains_key(&values_old.descriptor.owner));
        let mut current =
            CertifiedSourceSelection::from_compiler_inputs(&request, &validation.inventory).unwrap();
        assert!(current
            .current_product(
                NativeGroupKey {
                    artifact: r_entry.descriptor.id,
                    original_ordinal: 8
                },
                &r_entry
            )
            .unwrap()
            .is_none());
        assert!(current
            .interface_only_artifact(&g_entry.descriptor.owner)
            .is_some());
        let j = fixture_finalized_product_with_requirements(
            original_groups_fixture_with_interface(
                "MixedJ",
                vec![(9, vec![source(&r, 8)])],
                93,
                &BTreeMap::new(),
                b"J interface".to_vec(),
            ),
            producer.sha256(),
            Some(BTreeMap::from([(
                (r.owner().unit.clone(), r.owner().module.clone()),
                r.module_interface().unwrap().interface_sha256(),
            )])),
        );
        let j = recovered_witness_fixtures(&[j]).remove(0).product;
        let j_entry = Arc::new(ArtifactEntry::original(producer.sha256(), j.clone()).unwrap());
        for product in [&g, &j] {
            current
                .admit_current(
                    product.owner(),
                    ProductOrigin::Cached,
                    product.module_interface().unwrap(),
                    &validation.inventory,
                )
                .unwrap();
        }
        current
            .bind_produced_originals(
                &IssuedGroupCandidates::bind(Arc::from([]), &[g.clone(), j.clone()]).unwrap(),
            )
            .unwrap();
        current
            .admit_interface(&values_new, &validation.inventory)
            .unwrap();
        let g_key = NativeGroupKey {
            artifact: g_entry.descriptor.id,
            original_ordinal: 7,
        };
        let j_key = NativeGroupKey {
            artifact: j_entry.descriptor.id,
            original_ordinal: 9,
        };
        assert!(current.new_product_native_requirements().next().is_none());
        assert!(
            matches!(current.current_product(g_key, &g_entry).unwrap().unwrap()
            .own_group_candidates().unwrap(), NativeGroupCandidates::NewProduct(groups) if groups.is_empty())
        );
        let entries = vec![g_entry.clone(), j_entry.clone(), values_new.clone()];
        // Complete the general PrivateAvailability issuer before the bound
        // consumer: J's exact input closure contains the old binding of G7.
        let finished = OriginalCompilerInputs::issue_segment_native_availability(
            &mut current,
            request.artifacts(),
            entries.clone(),
            &mut crate::recovery_artifacts::PackageInterfaceValidation::default(),
        )
        .unwrap();
        let g_current = current.current_product(g_key, &g_entry).unwrap().unwrap();
        let g_candidates = g_current.own_group_candidates().unwrap();
        assert_eq!(g_candidates.bindings().len(), 1);
        let fresh_g = *g_candidates.bindings().first().unwrap();
        assert_ne!(fresh_g, old_g);
        let CertifiedNativeGroupSupport::Issued(g_offer) =
            g_current.own_group_support(fresh_g).unwrap()
        else {
            panic!("completed G owns its issued support");
        };
        let g_edges = g_offer.custody_snapshot().binding_dependencies().unwrap();
        let fresh_value = g_edges
            .iter()
            .find_map(|(from, to, edge)| {
                if *from != ArtifactBindingNode::Group(fresh_g)
                    || !matches!(edge, ArtifactDependency::NativeBinding { .. })
                {
                    return None;
                }
                match to {
                    ArtifactBindingNode::Artifact(binding) => Some(*binding),
                    _ => None,
                }
            })
            .unwrap();
        assert_eq!(fresh_value.artifact, values_new.descriptor.id);
        let j_current = current.current_product(j_key, &j_entry).unwrap().unwrap();
        let j_candidates = j_current.own_group_candidates().unwrap();
        assert_eq!(j_candidates.bindings().len(), 1);
        let fresh_j = *j_candidates.bindings().first().unwrap();
        let CertifiedNativeGroupSupport::Issued(j_offer) =
            j_current.own_group_support(fresh_j).unwrap()
        else {
            panic!("completed J owns its issued support");
        };
        let j_edges = j_offer.custody_snapshot().binding_dependencies().unwrap();
        assert!(old_edges.iter().all(|edge| j_edges.contains(edge)));
        let j_to_r = (
            ArtifactBindingNode::Group(fresh_j),
            ArtifactBindingNode::Group(old_r),
            ArtifactDependency::NativeGroup {
                dependent_ordinal: 9,
                required_ordinal: 8,
            },
        );
        assert!(j_edges.contains(&j_to_r));
        let finished_artifacts = finished.issued_artifacts();
        let physical_roots = finished_artifacts.capture_graph_selection().roots;
        assert!(!physical_roots.contains(&ArtifactBindingNode::Group(fresh_g)));
        assert!(!physical_roots.contains(&ArtifactBindingNode::Group(fresh_j)));
        let owner = finished_artifacts.inventory();
        let observations = source_target_observations(&[(&g, 7), (&j, 9)]);
        let prepared = prepared_target_fixture(&observations);
        let observed =
            AuthenticatedTargetImports::issue(&prepared, &observations, &validation.inventory)
                .unwrap();
        let admitted_target = owner
            .select_native_target(
                finished.physical_cohort().unwrap(),
                &current,
                observed,
                None,
                Some(&owner.empty_view()),
                &[],
                &BTreeMap::new(),
                &mut validation,
            )
            .unwrap();
        let target = admitted_target.artifacts().clone();
        assert_eq!(
            target
                .capture_graph_selection()
                .native_groups
                .into_iter()
                .collect::<BTreeSet<_>>(),
            BTreeSet::from([old_r, old_g, fresh_g, fresh_j])
        );
        assert_eq!(
            target.selected_native_groups(),
            BTreeSet::from([
                g_key,
                j_key,
                NativeGroupKey {
                    artifact: r_entry.descriptor.id,
                    original_ordinal: 8
                },
            ])
        );
        let edges = target.binding_dependencies();
        assert!(old_edges.iter().all(|edge| edges.contains(edge)));
        assert!(edges.contains(&j_to_r));
        assert!(g_edges.iter().all(|edge| edges.contains(edge)));
        assert!(target.artifact_ids().contains(&old_value.artifact));
        assert!(target.artifact_ids().contains(&fresh_value.artifact));

        let issued_groups = crate::declaration_context::certify_selected_artifact_view_groups_with_validation(
            &target, None, &mut validation,
        ).unwrap();
        let issued_groups = Arc::new(issued_groups);
        let capture_identity = testing::identity("Values", "value");
        let mut observations = source_target_observations(&[(&g, 7)]);
        observations.push(AcceptedGlobal {
            identity: capture_identity.clone(),
            rep: RuntimeRep::LiftedRef,
            entry_signature: None,
            required_evaluated: false,
            owner: ReceiptImportOwner::Retained {
                identity: capture_identity.clone(),
                generation: 4,
            },
        });
        let prepared = prepared_target_fixture(&observations);
        let observed =
            AuthenticatedTargetImports::issue(&prepared, &observations, &validation.inventory)
                .unwrap();
        let mixed_target = owner
            .select_native_target(
                finished.physical_cohort().unwrap(),
                &current,
                observed,
                None,
                Some(&owner.empty_view()),
                &[],
                &BTreeMap::new(),
                &mut validation,
            )
            .unwrap();
        let mixed_groups =
            crate::declaration_context::certify_selected_artifact_view_groups_with_validation(
                mixed_target.artifacts(),
                None,
                &mut validation,
            )
            .unwrap();
        let mixed_target = mixed_target
            .with_certified_groups(Arc::new(mixed_groups))
            .unwrap();
        let mixed = mixed_target.resolve_sources().unwrap();
        assert!(matches!(mixed.target_requirements(), [
            SelectedNativeTargetImport::Source { binding, .. },
            SelectedNativeTargetImport::RetainedCapture { identity, generation: 4 },
        ] if *binding == fresh_g && identity == &capture_identity));
        let certified_target = admitted_target
            .with_certified_groups(issued_groups)
            .unwrap();
        let linked_target = certified_target.resolve_sources().unwrap();
        assert!(matches!(linked_target.target_requirements(), [
            SelectedNativeTargetImport::Source { binding: first, .. },
            SelectedNativeTargetImport::Source { binding: second, .. },
        ] if *first == fresh_g && *second == fresh_j));
        assert!(matches!(linked_target.group_imports(fresh_j).unwrap(),
            [SelectedNativeImport::Source { binding, .. }] if *binding == old_r));

        // The World demand owner must retain both exact G occurrences too;
        // their equal logical key cannot erase either dependency history.
        let complete = CompilerSourceSupport::close_complete_output(&finished).unwrap();
        let closure = current.selected_original_closure(&target).unwrap();
        let selected = complete.certify_original_closure(&closure).unwrap();
        let context = ExactDeclarationContext::new(&[], &[], vec![]).unwrap()
            .extend_issued_compiler_support(&selected).unwrap();
        let inputs = context
            .capture_world_primary_compiler_inputs(producer.sha256())
            .unwrap();
        let mut uses = Vec::new();
        for (entry, product, ordinal) in [(&g_entry, &g, 7), (&j_entry, &j, 9)] {
            let primary = inputs
                .compiler_source_support()
                .compiler_primary_input(&entry.descriptor.owner)
                .unwrap()
                .unwrap();
            let pair = |binding: crate::artifact_inventory::ArtifactBinding| {
                value_array([
                    Value::Bytes(binding.artifact.0.to_vec()),
                    Value::Bytes(binding.selection.0.to_vec()),
                ])
            };
            let PendingImportOwner::Source { binder, .. } = source(product, ordinal) else {
                unreachable!()
            };
            uses.push(value_array([
                value_text(&entry.descriptor.owner.unit),
                value_text(&entry.descriptor.owner.module),
                pair(primary.interface()),
                pair(primary.original().unwrap()),
                value_identity(&binder),
            ]));
        }
        let batch_uses = uses.clone();
        let mut bytes = Vec::new();
        ciborium::ser::into_writer(
            &value_array([value_text("TPNATIVEDEMAND1"), value_array(uses)]),
            &mut bytes,
        )
        .unwrap();
        let packet = NativeDemandPacket::decode(&bytes, &validation.inventory).unwrap();
        let resolved = inputs
            .resolve_native_demand(&packet, &mut validation)
            .unwrap();
        let packet = |uses: Vec<Value>, operation: &InventoryOperation| {
            let bytes = encode_value_with_operation(
                &value_array([value_text("TPNATIVEDEMAND1"), value_array(uses)]),
                CertificationFormat::ProductReceipt, COMPILER_RECEIPT_BYTES_LIMIT, operation,
            ).unwrap();
            NativeDemandPacket::decode(&bytes, operation).unwrap()
        };
        let first = inputs.resolve_native_demand(
            &packet(vec![batch_uses[0].clone()], &validation.inventory), &mut validation,
        ).unwrap();
        let second = inputs.resolve_native_demand(
            &packet(vec![batch_uses[1].clone()], &validation.inventory), &mut validation,
        ).unwrap();
        let merged = first.groups().merge(second.groups()).unwrap();
        assert_eq!(merged.selected_rows().keys().copied().collect::<BTreeSet<_>>(), BTreeSet::from([old_r, old_g, fresh_g, fresh_j]));
        assert_eq!(merged.retained_bindings(), resolved.groups().retained_bindings());
        let mut foreign_validation = PackageInterfaceValidation::default();
        let foreign = inputs.resolve_native_demand(
            &packet(vec![batch_uses[0].clone()], &foreign_validation.inventory), &mut foreign_validation,
        ).unwrap();
        assert!(merged.merge(foreign.groups()).is_err());
        let rows = resolved.groups().selected_rows();
        assert_eq!(
            rows.keys().copied().collect::<BTreeSet<_>>(),
            BTreeSet::from([old_r, old_g, fresh_g, fresh_j])
        );
        assert_eq!(rows[&fresh_j].dependencies(), &[old_r]);
        assert_eq!(rows[&old_r].dependencies(), &[old_g]);
        assert!(rows[&fresh_g].dependencies().is_empty());
        assert!(
            matches!(rows[&fresh_j].imports(), [SelectedNativeImport::Source { binding, .. }] if *binding == old_r)
        );
        assert!(
            matches!(rows[&old_r].imports(), [SelectedNativeImport::Source { binding, .. }] if *binding == old_g)
        );
        assert!(
            matches!(rows[&old_g].imports(), [SelectedNativeImport::Retained { binding, .. }] if *binding == old_value)
        );
        assert!(
            matches!(rows[&fresh_g].imports(), [SelectedNativeImport::Retained { binding, .. }] if *binding == fresh_value)
        );
        assert_eq!(
            rows[&old_g].product().owner(),
            rows[&fresh_g].product().owner()
        );
        assert_eq!(
            resolved
                .groups()
                .retained_bindings()
                .iter()
                .map(|binding| binding.artifact_id)
                .collect::<BTreeSet<_>>(),
            BTreeSet::from([old_value.artifact, fresh_value.artifact])
        );
    }

    #[test]
    fn current_cohort_dependencies_keep_required_owners_in_completed_target() {
        use crate::artifact_inventory::{
            ArtifactBindingNode, ArtifactDependency, ArtifactEntry, CanonicalProducerIdentity,
            NativeArtifactDemand,
        };
        use crate::declaration_context::{ExactCompileContext, ExactDeclarationContext};
        let bytes = b"current-cohort-owner-obligations";
        let producer = CanonicalProducerIdentity::from_producer_bytes(bytes);
        let children = ["CohortLeft", "CohortRight"].map(|module| {
            fixture_finalized_product(
                original_groups_fixture_with_interface(
                    module,
                    vec![(7, vec![])],
                    76,
                    &BTreeMap::new(),
                    module.as_bytes().to_vec(),
                ),
                producer.sha256(),
            )
        });
        let imports = children.each_ref().map(|child| PendingImportOwner::Source {
            owner: child.owner().clone(),
            original_ordinal: 7,
            binder: testing::identity(&child.owner().module, "entry"),
        });
        let parent = fixture_finalized_product(
            original_groups_fixture_with_interface(
                "CohortParent",
                vec![(5, imports.to_vec())],
                77,
                &BTreeMap::new(),
                b"cohort parent".to_vec(),
            ),
            producer.sha256(),
        );
        let products =
            recovered_witness_fixtures(&[children[0].clone(), children[1].clone(), parent]);
        for reverse in [false, true] {
            let root = tempfile::tempdir().unwrap();
            let context = Arc::new(
                ExactDeclarationContext::new(&[], &[], vec![])
                    .unwrap()
                    .admit_producer(producer.sha256())
                    .unwrap(),
            );
            let request = ExactCompileContext::new(context)
                .prepare_compilation(root.path(), bytes)
                .unwrap();
            let mut validation = PackageInterfaceValidation::default();
            let mut selection = CertifiedSourceSelection::from_compiler_inputs(
                request.compiler_inputs(),
                &validation.inventory,
            )
            .unwrap();
            let mut current = products
                .iter()
                .map(|product| product.product.clone())
                .collect::<Vec<_>>();
            if reverse {
                current.reverse();
            }
            for product in &current {
                selection
                    .admit_current(
                        product.owner(),
                        ProductOrigin::Cached,
                        product.module_interface().unwrap(),
                        &validation.inventory,
                    )
                    .unwrap();
            }
            selection
                .bind_produced_originals(
                    &IssuedGroupCandidates::bind(Arc::from([]), &current).unwrap(),
                )
                .unwrap();
            let output =
                crate::declaration_context::certified_product_artifact_view_with_validation(
                    producer.sha256(),
                    &current,
                    &[],
                    &[],
                    Some(request.compiler_inputs().artifacts()),
                    NativeArtifactDemand::ScopeInterfaces,
                    &mut validation,
                )
                .unwrap();
            assert!(output.selected_native_groups().is_empty());
            assert!(selection.new_product_native_requirements().next().is_none());
            let entries = current
                .iter()
                .map(|product| {
                    Arc::new(ArtifactEntry::original(producer.sha256(), product.clone()).unwrap())
                })
                .collect::<Vec<_>>();
            let parent = &products[2].product;
            let parent_entry = entries
                .iter()
                .find(|entry| entry.descriptor.owner.module == "CohortParent")
                .unwrap();
            let inventory = output.inventory();
            let bound = inventory
                .bind_segment(
                    &output,
                    vec![],
                    &selection,
                    &mut crate::recovery_artifacts::PackageInterfaceValidation::default(),
                )
                .unwrap();
            let observations = source_target_observations(&[(parent, 5)]);
            let prepared = prepared_target_fixture(&observations);
            let observed =
                AuthenticatedTargetImports::issue(&prepared, &observations, &validation.inventory)
                    .unwrap();
            let bound = inventory
                .select_native_target(
                    bound.physical_inputs().physical_cohort().unwrap(),
                    bound.source_selection(),
                    observed,
                    None,
                    Some(&output),
                    &[],
                    &BTreeMap::new(),
                    &mut validation,
                )
                .unwrap()
                .artifacts()
                .clone();
            {
                let view = bound;
                let graph = view.capture_graph_selection();
                assert_eq!(
                    graph.native_groups.len(),
                    3,
                    "one parent and two distinct required owners; reverse={reverse}"
                );
                let parent_group = *graph
                    .native_groups
                    .iter()
                    .find(|group| {
                        group.binding.artifact() == parent_entry.descriptor.id
                            && group.original_ordinal == 5
                    })
                    .unwrap();
                let edges = graph
                    .selections
                    .iter()
                    .flat_map(|scope| scope.dependencies.iter())
                    .collect::<BTreeSet<_>>();
                for child in &products[..2] {
                    let id = ArtifactEntry::original(producer.sha256(), child.product.clone())
                        .unwrap()
                        .descriptor
                        .id;
                    let child_group = *graph
                        .native_groups
                        .iter()
                        .find(|group| group.binding.artifact() == id && group.original_ordinal == 7)
                        .unwrap();
                    assert_eq!(
                        child_group.binding.selection(),
                        parent_group.binding.selection(),
                        "same cohort needs no earlier child issuance"
                    );
                    assert!(edges.contains(&&(
                        ArtifactBindingNode::Group(parent_group),
                        ArtifactBindingNode::Group(child_group),
                        ArtifactDependency::NativeGroup {
                            dependent_ordinal: 5,
                            required_ordinal: 7
                        }
                    )));
                    assert!(
                        !graph
                            .roots
                            .contains(&ArtifactBindingNode::Group(child_group)),
                        "native dependency is not an execution root"
                    );
                }
            }
        }
    }

    #[test]
    fn current_complete_product_borrows_issued_full_dependency_without_execution_demand() {
        use crate::artifact_inventory::{
            ArtifactEntry, ArtifactInventory, CanonicalProducerIdentity, CompilerInputProjection,
            NativeArtifactDemand,
        };
        use crate::declaration_context::{
            ExactCompileContext, ExactDeclarationContext, OriginalCompilerInputs,
        };
        let producer_bytes = b"current-product-full-dependency";
        let producer = CanonicalProducerIdentity::from_producer_bytes(producer_bytes);
        let dependency = fixture_finalized_product(
            original_groups_fixture_with_interface(
                "AvailableDependency",
                vec![(7, vec![]), (9001, vec![])],
                74,
                &BTreeMap::new(),
                b"available dependency".to_vec(),
            ),
            producer.sha256(),
        );
        let mut binder = testing::identity("AvailableDependency", "entry_9001");
        binder.unit = dependency.owner().unit.clone();
        let current = fixture_finalized_product(
            original_groups_fixture_with_interface(
                "CurrentDependent",
                vec![(
                    5,
                    vec![PendingImportOwner::Source {
                        owner: dependency.owner().clone(),
                        original_ordinal: 9001,
                        binder,
                    }],
                )],
                75,
                &BTreeMap::new(),
                b"current dependent".to_vec(),
            ),
            producer.sha256(),
        );
        let recovered = recovered_witness_fixtures(&[dependency, current]);
        let dependency = &recovered[0].product;
        let current = &recovered[1].product;
        let root = tempfile::tempdir().unwrap();
        for (full, interface_only) in [(false, false), (true, false), (false, true), (true, true)] {
            let inventory = ArtifactInventory::default();
            let entry =
                Arc::new(ArtifactEntry::original(producer.sha256(), dependency.clone()).unwrap());
            let projection =
                CompilerInputProjection::from_issued_entries(&[entry.clone()]).unwrap();
            let view = inventory
                .admit_recovery_selection(
                    &inventory.empty_view(),
                    vec![entry.clone()],
                    &BTreeSet::new(),
                )
                .unwrap();
            let context = Arc::new(
                ExactDeclarationContext::from_authenticated_execution(
                    producer.sha256(),
                    &view,
                    projection,
                    vec![crate::declaration_join::ExactLexicalNode {
                        owner: entry.descriptor.owner.clone(),
                        imports: vec![],
                    }],
                    entry.descriptor.owner.clone(),
                    &[],
                )
                .unwrap(),
            );
            // A separately certified selected output supplies full dependency
            // availability before the dependent output is admitted.
            let private = full.then(|| {
                let output_inventory = ArtifactInventory::default();
                let output_artifacts = output_inventory
                    .admit_shared_with_demand(
                        &output_inventory.empty_view(),
                        vec![entry.clone()],
                        NativeArtifactDemand::ScopeInterfaces,
                    )
                    .unwrap();
                let output_projection =
                    CompilerInputProjection::from_issued_entries(&[entry.clone()]).unwrap();
                let output_selection = CertifiedSourceSelection::from_compiler_projection(
                    &output_projection,
                    &output_artifacts.metadata_snapshot(),
                    &InventoryOperation::new(Default::default()),
                )
                .unwrap();
                OriginalCompilerInputs::from_selection(&output_selection, &output_artifacts)
                    .unwrap()
            });
            let (context, private) = if interface_only {
                let support = match &private {
                    Some(private) => {
                        crate::artifact_inventory::CompilerSourceSupport::close_complete_output(
                            private,
                        )
                        .unwrap()
                    }
                    None => context.compiler_source_support().clone(),
                }
                .for_source_owners(&BTreeSet::new())
                .unwrap();
                assert!(support
                    .projection()
                    .roles()
                    .iter()
                    .all(|role| role.original().is_none()));
                assert_eq!(
                    support.native_offers().iter().any(|offer| offer.is_full()),
                    full
                );
                let context = ExactDeclarationContext::new(&[], &[], vec![])
                    .unwrap()
                    .extend_issued_compiler_support(&support)
                    .unwrap();
                (Arc::new(context), None)
            } else {
                (context, private)
            };
            let request = ExactCompileContext::new(context)
                .prepare_compilation_with_private_input(
                    &root.path().join(format!("request-{full}-{interface_only}")),
                    producer_bytes,
                    None,
                    private,
                )
                .unwrap();
            let wire: Value =
                ciborium::de::from_reader(std::fs::read(&request.manifest).unwrap().as_slice())
                    .unwrap();
            let native_rows = wire.as_array().unwrap()[6].as_array().unwrap();
            if interface_only && !full {
                // Recovery may retain a bounded-empty authenticated row after
                // demoting the compiler role. It grants no executable ordinal.
                assert!(native_rows.len() <= 1);
                for row in native_rows {
                    let row = row.as_array().unwrap();
                    assert_eq!(row[6], value_array([]));
                    assert_eq!(
                        row[8],
                        value_array([value_text("issued-groups"), value_array([])])
                    );
                    assert_eq!(row[9], value_text("private-native"));
                }
            } else {
                assert_eq!(native_rows.len(), 1);
                let row = native_rows[0].as_array().unwrap();
                assert_eq!(row[6], value_array([]));
                assert_eq!(
                    row[8],
                    if full {
                        value_array([value_text("full-carrier")])
                    } else {
                        value_array([value_text("issued-groups"), value_array([])])
                    }
                );
                assert_eq!(
                    row[9],
                    value_text(if interface_only {
                        "private-native"
                    } else {
                        "compiler-original"
                    })
                );
            }
            let mut validation = PackageInterfaceValidation::default();
            let mut selection = CertifiedSourceSelection::from_compiler_inputs(
                request.compiler_inputs(),
                &validation.inventory,
            )
            .unwrap();
            assert_eq!(
                selection.permits_native_group(entry.descriptor.id, dependency.owner(), 9001),
                full,
                "custody and canonical visibility do not replace the carried body permission"
            );
            if interface_only {
                assert!(selection
                    .receipt_native_body_owners()
                    .all(|owner| owner != dependency.owner()));
                assert!(request
                    .compiler_inputs()
                    .projection()
                    .roles()
                    .iter()
                    .all(|role| role.original().is_none()));
            }
            // Model the production cached-product admission, as in View.Wire.
            // This is an issuer component test, not a GHC compilation history.
            selection
                .admit_current(
                    current.owner(),
                    ProductOrigin::Cached,
                    current.module_interface().unwrap(),
                    &validation.inventory,
                )
                .unwrap();
            selection
                .bind_produced_originals(
                    &IssuedGroupCandidates::bind(Arc::from([]), &[current.clone()]).unwrap(),
                )
                .unwrap();
            let output =
                crate::declaration_context::certified_product_artifact_view_with_validation(
                    producer.sha256(),
                    &[dependency.clone(), current.clone()],
                    &[],
                    &[],
                    Some(request.compiler_inputs().artifacts()),
                    NativeArtifactDemand::ScopeInterfaces,
                    &mut validation,
                )
                .unwrap();
            assert!(output.selected_native_groups().is_empty());
            assert!(selection.new_product_native_requirements().next().is_none());
            let current_entry = output.entries().into_iter().find(|entry| {
                matches!(&entry.payload, crate::artifact_inventory::ArtifactPayload::Original(product)
                    if product.owner() == current.owner())
            }).expect("actual output retains the current product");
            let current_ref = selection
                .current_product(
                    crate::artifact_inventory::NativeGroupKey {
                        artifact: current_entry.descriptor.id,
                        original_ordinal: 5,
                    },
                    &current_entry,
                )
                .unwrap()
                .expect("bound physical output needs no self dependency proof");
            assert!(
                matches!(current_ref.own_group_candidates().unwrap(), NativeGroupCandidates::NewProduct(groups) if groups.is_empty())
            );
            if full {
                use crate::artifact_inventory::{ArtifactBindingNode, ArtifactDependency};
                // Read the expected dependency directly from the original
                // issuer's recorded rows, before either receiving planner runs.
                let expected = request
                    .compiler_inputs()
                    .native_availability(entry.descriptor.id)
                    .unwrap()
                    .offers()
                    .filter_map(|offer| offer.proof())
                    .flat_map(|proof| proof.selection.graph_selection().native_groups.iter())
                    .filter(|group| {
                        group.binding.artifact() == entry.descriptor.id
                            && group.original_ordinal == 9001
                    })
                    .copied()
                    .collect::<BTreeSet<_>>();
                assert_eq!(expected.len(), 1);
                let expected = *expected.first().unwrap();
                let inventory = output.inventory();
                let bound = inventory
                    .bind_segment(
                        &output,
                        vec![],
                        &selection,
                        &mut crate::recovery_artifacts::PackageInterfaceValidation::default(),
                    )
                    .unwrap();
                let observations = source_target_observations(&[(current, 5)]);
                let prepared = prepared_target_fixture(&observations);
                let observed = AuthenticatedTargetImports::issue(
                    &prepared,
                    &observations,
                    &validation.inventory,
                )
                .unwrap();
                let bound = inventory
                    .select_native_target(
                        bound.physical_inputs().physical_cohort().unwrap(),
                        bound.source_selection(),
                        observed,
                        None,
                        Some(&output),
                        &[],
                        &BTreeMap::new(),
                        &mut validation,
                    )
                    .unwrap()
                    .artifacts()
                    .clone();
                {
                    let view = bound;
                    let graph = view.capture_graph_selection();
                    let parents = graph
                        .native_groups
                        .iter()
                        .filter(|group| {
                            group.binding.artifact() == current_entry.descriptor.id
                                && group.original_ordinal == 5
                        })
                        .copied()
                        .collect::<Vec<_>>();
                    assert_eq!(parents.len(), 1);
                    let parent = parents[0];
                    assert!(graph
                        .selections
                        .iter()
                        .flat_map(|scope| scope.dependencies.iter())
                        .any(|edge| *edge
                            == (
                                ArtifactBindingNode::Group(parent),
                                ArtifactBindingNode::Group(expected),
                                ArtifactDependency::NativeGroup {
                                    dependent_ordinal: 5,
                                    required_ordinal: 9001
                                },
                            )));
                    assert_eq!(
                        graph
                            .native_groups
                            .iter()
                            .filter(|group| group.binding.artifact() == entry.descriptor.id)
                            .copied()
                            .collect::<Vec<_>>(),
                        vec![expected]
                    );
                    assert!(
                        !graph.roots.contains(&ArtifactBindingNode::Group(expected)),
                        "dependency support adds no execution root"
                    );
                }
            }
            let result = OriginalCompilerInputs::from_selection(&selection, &output);
            if !full {
                let observed = format!("{result:?}");
                assert!(
                    matches!(result, Err(crate::CompileError::ArtifactInventory(error))
                    if error.failure == crate::artifact_inventory::ArtifactInventoryFailure::NativeGroupUnavailable {
                        artifact: entry.descriptor.id,
                        original_ordinal: 9001,
                    }),
                    "missing or bounded-empty availability must refuse the actual dependency: {observed}"
                );
                continue;
            }
            let private = result.expect("current product must borrow its issued full dependency");
            // Program support predates the new private proof issuance. Continue
            // through that actual handoff rather than preparing from private directly.
            let (admission, source) =
                crate::declaration_context::generated_source_admission_fixture(
                    &root
                        .path()
                        .join(format!("continuation-admission-{interface_only}")),
                    &request,
                );
            let private = private
                .for_program_continuation(&output, &[admission], &source)
                .unwrap();
            let public = Arc::new(
                ExactDeclarationContext::new(&[], &[], vec![])
                    .unwrap()
                    .admit_producer(producer.sha256())
                    .unwrap(),
            );
            assert_eq!(public.toolchain_identity_sha256(), producer.sha256());
            assert!(public.compiler_input_roles().is_empty());
            let next = ExactCompileContext::new(public)
                .prepare_compilation_with_private_input(
                    &root.path().join(format!("next-{interface_only}")),
                    producer_bytes,
                    None,
                    Some(private),
                )
                .unwrap();
            assert!(next
                .compiler_inputs()
                .metadata()
                .retained
                .selected_native_groups
                .is_empty());
            let wire: Value =
                ciborium::de::from_reader(std::fs::read(&next.manifest).unwrap().as_slice())
                    .unwrap();
            let rows = wire.as_array().unwrap()[6].as_array().unwrap();
            assert_eq!(rows.len(), 2);
            for row in rows {
                let row = row.as_array().unwrap();
                assert_eq!(row[6], value_array([]));
                assert_eq!(row[8], value_array([value_text("full-carrier")]));
                if row[1] == value_text(&dependency.owner().module) && interface_only {
                    assert_eq!(row[9], value_text("private-native"));
                }
            }
            if interface_only {
                use crate::artifact_inventory::{
                    ArtifactInventoryFailure, NativeAdmissionRefusal, NativeGroupKey,
                };
                let input_view = next.compiler_inputs().artifacts();
                let inventory = input_view.inventory();
                let operation = InventoryOperation::new(Default::default());
                let input_selection = CertifiedSourceSelection::from_compiler_inputs(
                    next.compiler_inputs(),
                    &operation,
                )
                .unwrap();
                let original = input_selection
                    .target_original(dependency.owner())
                    .unwrap()
                    .expect("real request retains private Full native output");
                let key = NativeGroupKey {
                    artifact: original.descriptor.id,
                    original_ordinal: 9001,
                };
                assert!(input_selection.permits_native_group(
                    key.artifact,
                    dependency.owner(),
                    key.original_ordinal
                ));
                assert!(
                    input_selection
                        .current_product(key, &original)
                        .unwrap()
                        .is_none(),
                    "private Input availability is not current physical production"
                );
                let bound = inventory
                    .bind_segment(
                        input_view,
                        vec![],
                        &input_selection,
                        &mut crate::recovery_artifacts::PackageInterfaceValidation::default(),
                    )
                    .unwrap();
                let physical = bound.physical_inputs().issued_artifacts();
                let before_physical = physical.capture_graph_selection();
                let before_view = input_view.capture_graph_selection();
                let before = inventory.metrics();
                let observations =
                    source_target_observations(&[(dependency, key.original_ordinal)]);
                let prepared = prepared_target_fixture(&observations);
                let observed = AuthenticatedTargetImports::issue(
                    &prepared,
                    &observations,
                    &validation.inventory,
                )
                .unwrap();
                let error = inventory
                    .select_native_target(
                        bound.physical_inputs().physical_cohort().unwrap(),
                        &input_selection,
                        observed,
                        None,
                        Some(input_view),
                        &[],
                        &BTreeMap::new(),
                        &mut validation,
                    )
                    .err()
                    .expect("private Full without a root choice cannot become a current root");
                assert!(
                    matches!(error, crate::CompileError::ArtifactInventory(ref error)
                    if error.failure == ArtifactInventoryFailure::NativeGroupUnavailable {
                        artifact: key.artifact, original_ordinal: key.original_ordinal,
                    } && error.native_refusal == Some(NativeAdmissionRefusal::CurrentProductNotCompleted {
                        original: key.artifact, original_ordinal: key.original_ordinal,
                    })),
                    "actual Input refusal must preserve its native admission cause: {error:?}"
                );
                assert_eq!(physical.capture_graph_selection(), before_physical);
                assert_eq!(input_view.capture_graph_selection(), before_view);
                let after = inventory.metrics();
                assert_eq!(
                    (after.nodes, after.issued_scope_nodes),
                    (before.nodes, before.issued_scope_nodes)
                );
            }
        }
    }

    #[test]
    fn ordinary_target_selects_old_full_carrier_transitively_without_new_native() {
        use crate::artifact_inventory::{ArtifactEntry, ArtifactInventory, NativeGroupKey};
        let dependency = full_native_fixture("Dependency", vec![(9, vec![]), (12, vec![])], 7);
        let dependency_import = PendingImportOwner::Source {
            owner: dependency.owner().clone(),
            original_ordinal: 9,
            binder: testing::identity("Dependency", "entry_9"),
        };
        for unrelated in [0, 1, 7, 17] {
            let mut outlines = vec![(8, vec![dependency_import.clone()])];
            outlines.extend((0..unrelated).map(|index| (20 + index, vec![])));
            let original = full_native_fixture("Original", outlines, 7);
            let products = vec![original.clone(), dependency.clone()];
            let mut validation = PackageInterfaceValidation::default();
            let entries = products
                .iter()
                .cloned()
                .map(|product| {
                    Arc::new(
                        ArtifactEntry::original_with_validation([1; 32], product, &mut validation)
                            .unwrap(),
                    )
                })
                .collect::<Vec<_>>();
            let inventory = ArtifactInventory::default();
            let baseline = inventory
                .admit_recovery_selection(
                    &inventory.empty_view(),
                    entries.clone(),
                    &BTreeSet::new(),
                )
                .unwrap();
            assert!(baseline.selected_native_groups().is_empty());
            let accepted = source_target_observations(&[(&original, 8)]);
            let target = prepared_target_fixture(&accepted);
            let selection = CertifiedSourceSelection::from_projected_originals(
                &products,
                &validation.inventory,
            )
            .unwrap();
            let completed = inventory
                .bind_segment(&baseline, entries.clone(), &selection, &mut validation)
                .unwrap();
            let before = inventory.metrics().issued_scope_nodes;
            let observed =
                AuthenticatedTargetImports::issue(&target, &accepted, &validation.inventory)
                    .unwrap();
            let selected = inventory
                .select_native_target(
                    completed.physical_inputs().physical_cohort().unwrap(),
                    completed.source_selection(),
                    observed,
                    None,
                    None,
                    &[],
                    &BTreeMap::new(),
                    &mut validation,
                )
                .unwrap()
                .artifacts()
                .clone();
            let selected_keys = BTreeSet::from([
                NativeGroupKey {
                    artifact: entries[0].descriptor.id,
                    original_ordinal: 8,
                },
                NativeGroupKey {
                    artifact: entries[1].descriptor.id,
                    original_ordinal: 9,
                },
            ]);
            assert_eq!(selected.selected_native_groups(), selected_keys);
            assert_eq!(selected.artifact_ids(), baseline.artifact_ids());
            let groups =
                crate::declaration_context::certify_selected_artifact_view_groups_with_validation(
                    &selected,
                    None,
                    &mut validation,
                )
                .unwrap();
            assert_eq!(groups.len(), 2);
            let observed =
                AuthenticatedTargetImports::issue(&target, &accepted, &validation.inventory)
                    .unwrap();
            let repeated = inventory
                .select_native_target(
                    completed.physical_inputs().physical_cohort().unwrap(),
                    completed.source_selection(),
                    observed,
                    None,
                    None,
                    &[],
                    &BTreeMap::new(),
                    &mut validation,
                )
                .unwrap()
                .artifacts()
                .clone();
            assert_eq!(inventory.metrics().issued_scope_nodes, before);
            assert_eq!(repeated.selected_native_groups(), selected_keys);
            crate::declaration_context::certify_selected_artifact_view_groups_with_validation(
                &repeated,
                Some(&groups),
                &mut validation,
            )
            .unwrap();
            assert!(
                crate::declaration_context::certify_selected_artifact_view_groups_with_validation(
                    &baseline,
                    Some(&groups),
                    &mut validation
                )
                .is_err()
            );
            let mut stale = accepted.clone();
            let ReceiptImportOwner::Source {
                original_ordinal, ..
            } = &mut stale[0].owner
            else {
                unreachable!()
            };
            *original_ordinal = 100;
            let observed =
                AuthenticatedTargetImports::issue(&target, &stale, &validation.inventory).unwrap();
            assert!(matches!(
                inventory.select_native_target(
                    completed.physical_inputs().physical_cohort().unwrap(),
                    completed.source_selection(),
                    observed,
                    None,
                    None,
                    &[],
                    &BTreeMap::new(),
                    &mut validation,
                ),
                Err(crate::CompileError::CompilerEvidence(error))
                    if matches!(error.as_ref(), CertificationError::Mismatch(
                        "target Source exact native membership"
                    ))
            ));
            let missing = vec![entries[0].clone()];
            let partial_inventory = ArtifactInventory::default();
            let partial = partial_inventory
                .admit_recovery_selection(
                    &partial_inventory.empty_view(),
                    missing.clone(),
                    &BTreeSet::new(),
                )
                .unwrap();
            let missing_selection = CertifiedSourceSelection::from_projected_originals(
                std::slice::from_ref(&original),
                &validation.inventory,
            )
            .unwrap();
            let missing_error = partial_inventory
                .bind_segment(&partial, missing, &missing_selection, &mut validation)
                .err()
                .expect("the omitted dependency has no selected Source owner");
            assert!(matches!(
                &missing_error,
                crate::CompileError::CompilerEvidence(error)
                    if matches!(error.as_ref(), CertificationError::SourceOutsideCompilerSelection {
                        owner, requested_version, original_ordinal: None,
                    } if owner.unit == dependency.owner().unit
                        && owner.module == dependency.owner().module
                        && requested_version == &dependency.owner().module_version)
            ), "the absent dependency must refuse before physical group completion: {missing_error:?}");
        }
    }

    #[test]
    fn authored_original_closure_preserves_inherited_demand_and_fresh_dependencies() {
        use crate::artifact_inventory::{ArtifactEntry, ArtifactInventory, NativeArtifactDemand};

        let scientific = full_native_fixture("Scientific", vec![(26, vec![])], 7);
        let schema = full_native_fixture(
            "Schema",
            vec![
                (195, vec![]),
                (197, vec![]),
                (
                    202,
                    vec![PendingImportOwner::Source {
                        owner: scientific.owner().clone(),
                        original_ordinal: 26,
                        binder: testing::identity("Scientific", "entry_26"),
                    }],
                ),
            ],
            7,
        );
        let fresh = full_native_fixture("FreshDependency", vec![(5, vec![])], 7);
        for later_group in [197, 202] {
            let source = |ordinal| PendingImportOwner::Source {
                owner: schema.owner().clone(),
                original_ordinal: ordinal,
                binder: testing::identity("Schema", &format!("entry_{ordinal}")),
            };
            let authored =
                recovered_witness_fixtures(&[fixture_finalized_product_with_requirements(
                    original_groups_fixture(
                        "Authored",
                        vec![
                            (
                                7,
                                vec![
                                    source(195),
                                    PendingImportOwner::Source {
                                        owner: fresh.owner().clone(),
                                        original_ordinal: 5,
                                        binder: testing::identity("FreshDependency", "entry_5"),
                                    },
                                ],
                            ),
                            (11, vec![source(later_group)]),
                        ],
                        7,
                        &BTreeMap::new(),
                    ),
                    [1; 32],
                    Some(
                        [&schema, &fresh]
                            .into_iter()
                            .map(|product| {
                                (
                                    (product.owner().unit.clone(), product.owner().module.clone()),
                                    product.module_interface().unwrap().interface_sha256(),
                                )
                            })
                            .collect(),
                    ),
                )])
                .remove(0)
                .product;
            assert_eq!(authored.module_interface().unwrap().requirements().len(), 2);
            let mut products = vec![authored.clone(), schema.clone(), fresh.clone()];
            if later_group == 197 {
                products.push(scientific.clone());
            }
            let mut entries = products
                .iter()
                .map(|product| Arc::new(ArtifactEntry::original([1; 32], product.clone()).unwrap()))
                .collect::<Vec<_>>();
            entries.push(Arc::new(ArtifactEntry::canonical(
                scientific.module_interface().unwrap().clone(),
            )));
            let inventory = ArtifactInventory::default();
            let available = inventory
                .admit_shared_with_demand(
                    &inventory.empty_view(),
                    entries.clone(),
                    NativeArtifactDemand::ScopeInterfaces,
                )
                .unwrap();
            let selection = CertifiedSourceSelection::from_projected_originals(
                &products,
                &InventoryOperation::new(Default::default()),
            )
            .unwrap();
            let mut validation = PackageInterfaceValidation::default();
            let completed =
                inventory.bind_segment(&available, entries, &selection, &mut validation);
            if later_group == 202 {
                assert!(
                    matches!(
                        completed,
                        Err(crate::CompileError::ArtifactInventory(error))
                            if matches!(error.failure,
                                crate::artifact_inventory::ArtifactInventoryFailure::MissingDependency {
                                    dependency: crate::artifact_inventory::ArtifactDependency::NativeGroup { dependent_ordinal: 202, required_ordinal: 26 }, ..
                                })
                    ),
                    "whole physical completion requires the later Scientific body"
                );
                assert!(available.selected_native_groups().is_empty());
                continue;
            }
            let completed = completed.unwrap();
            let before_issuance = inventory.metrics().issued_scope_nodes;
            let observations = source_target_observations(&[(&authored, 7)]);
            let prepared = prepared_target_fixture(&observations);
            let observed =
                AuthenticatedTargetImports::issue(&prepared, &observations, &validation.inventory)
                    .unwrap();
            let early = inventory
                .select_native_target(
                    completed.physical_inputs().physical_cohort().unwrap(),
                    completed.source_selection(),
                    observed,
                    None,
                    None,
                    &[],
                    &BTreeMap::new(),
                    &mut validation,
                )
                .unwrap();
            let early = early.artifacts();
            assert_eq!(inventory.metrics().issued_scope_nodes, before_issuance);
            let before = early.selected_native_groups();
            assert_eq!(
                before,
                BTreeSet::from([
                    crate::artifact_inventory::NativeGroupKey {
                        artifact: crate::artifact_inventory::ArtifactEntry::original_artifact_id(
                            [1; 32], &authored
                        ),
                        original_ordinal: 7,
                    },
                    crate::artifact_inventory::NativeGroupKey {
                        artifact: crate::artifact_inventory::ArtifactEntry::original_artifact_id(
                            [1; 32], &schema
                        ),
                        original_ordinal: 195,
                    },
                    crate::artifact_inventory::NativeGroupKey {
                        artifact: crate::artifact_inventory::ArtifactEntry::original_artifact_id(
                            [1; 32], &fresh
                        ),
                        original_ordinal: 5,
                    },
                ]),
            );
            let selection = completed.source_selection();
            selection.selected_original_closure(early).unwrap();
            assert!(selection
                .selected_authored_original_closure(early, "fixture", "Absent")
                .is_err());
            let result = selection.selected_authored_original_closure(early, "fixture", "Authored");
            assert_eq!(early.selected_native_groups(), before);
            let closure = result.unwrap();
            assert_eq!(closure.products(), &[authored.clone()]);
            let selected = closure.native_closure.selected_native_groups();
            let ordinals = |module: &str| {
                selected
                    .iter()
                    .filter_map(|key| {
                        closure
                            .native_closure
                            .entries()
                            .iter()
                            .find(|entry| entry.descriptor.id == key.artifact)
                            .filter(|entry| entry.descriptor.owner.module == module)
                            .map(|_| key.original_ordinal)
                    })
                    .collect::<BTreeSet<_>>()
            };
            assert_eq!(ordinals("Authored"), BTreeSet::from([7, 11]));
            assert_eq!(ordinals("Schema"), BTreeSet::from([195, 197]));
            assert_eq!(ordinals("FreshDependency"), BTreeSet::from([5]));
            assert!(ordinals("Scientific").is_empty());
            assert!(closure
                .native_closure
                .entries()
                .iter()
                .any(|entry| matches!(
                    &entry.payload, crate::artifact_inventory::ArtifactPayload::Original(product)
                    if product.same_durable_artifact(&fresh)
                )));
        }
    }

    #[test]
    fn authored_root_preserves_complete_interface_namespace_through_offer_retirement() {
        use crate::artifact_inventory::{ArtifactEntry, ArtifactInventory, NativeArtifactDemand};
        let dependencies = [
            full_native_fixture("TypeLeft", vec![(7, vec![])], 7),
            full_native_fixture("TypeRight", vec![(7, vec![])], 7),
        ];
        let mut histories = 0;
        for required_mask in 1u8..4 {
            let requirements = dependencies
                .iter()
                .enumerate()
                .filter(|(index, _)| required_mask & (1 << index) != 0)
                .map(|(_, product)| {
                    (
                        (product.owner().unit.clone(), product.owner().module.clone()),
                        product.module_interface().unwrap().interface_sha256(),
                    )
                })
                .collect();
            let authored =
                recovered_witness_fixtures(&[fixture_finalized_product_with_requirements(
                    original_groups_fixture(
                        "AuthoredTypes",
                        vec![(7, vec![])],
                        7,
                        &BTreeMap::new(),
                    ),
                    [1; 32],
                    Some(requirements),
                )])
                .remove(0)
                .product;
            let entries = std::iter::once(&authored)
                .chain(dependencies.iter())
                .map(|product| Arc::new(ArtifactEntry::original([1; 32], product.clone()).unwrap()))
                .collect();
            let inventory = ArtifactInventory::default();
            let available = inventory
                .admit_shared_with_demand(
                    &inventory.empty_view(),
                    entries,
                    NativeArtifactDemand::ScopeInterfaces,
                )
                .unwrap();
            let issue = |mask, reverse| {
                let mut products = vec![authored.clone()];
                products.extend(
                    dependencies
                        .iter()
                        .enumerate()
                        .filter(|(index, _)| mask & (1u8 << index) != 0)
                        .map(|(_, product)| product.clone()),
                );
                if reverse {
                    products.reverse();
                }
                let selection = CertifiedSourceSelection::from_projected_originals(
                    &products,
                    &InventoryOperation::new(Default::default()),
                )
                .unwrap();
                let entries = products
                    .into_iter()
                    .map(|product| Arc::new(ArtifactEntry::original([1; 32], product).unwrap()))
                    .collect();
                inventory.bind_segment(
                    &inventory.empty_view(),
                    entries,
                    &selection,
                    &mut PackageInterfaceValidation::default(),
                )
            };

            // The finite domain is small enough to cover every history. Share
            // only immutable fixture artifacts; each selection remains fresh.
            for offered_mask in 0u8..4 {
                for retired_mask in 0u8..4 {
                    for reverse in [false, true] {
                        histories += 1;
                        let initial = issue(offered_mask, reverse);
                        for mask in [offered_mask, offered_mask & !retired_mask, 3] {
                            let completed = issue(mask, reverse);
                            let expected = required_mask & !mask == 0;
                            assert_eq!(completed.is_ok(), expected);
                            if let Ok(completed) = completed {
                                let closure = completed
                                    .source_selection()
                                    .selected_authored_original_closure(
                                        completed.physical_inputs().issued_artifacts(),
                                        "fixture",
                                        "AuthoredTypes",
                                    )
                                    .unwrap();
                                assert_eq!(closure.products(), &[authored.clone()]);
                                let groups = closure.native_closure.selected_native_groups();
                                assert_eq!(groups.len(), 1);
                                assert_eq!(groups.iter().next().unwrap().original_ordinal, 7);
                            }
                            assert!(available.selected_native_groups().is_empty());
                            assert_eq!(
                                initial.as_ref().is_ok_and(|completed| {
                                    completed
                                        .source_selection()
                                        .selected_authored_original_closure(
                                            completed.physical_inputs().issued_artifacts(),
                                            "fixture",
                                            "AuthoredTypes",
                                        )
                                        .is_ok()
                                }),
                                required_mask & !offered_mask == 0,
                            );
                        }
                    }
                }
            }
        }
        assert_eq!(histories, 3 * 4 * 4 * 2);
    }

    #[test]
    fn original_consumers_preserve_whole_demand_and_exclude_only_the_probe() {
        use crate::artifact_inventory::{ArtifactEntry, ArtifactInventory, NativeArtifactDemand};
        let captured = PendingImportOwner::Retained {
            identity: testing::identity("Tidepool.Session.Val.G4", "delayed"),
            generation: 4,
        };
        let scaffold = full_native_fixture("Scaffold", vec![(3, vec![]), (11, vec![captured])], 7);
        let inventory = ArtifactInventory::default();
        let native = Arc::new(ArtifactEntry::original([1; 32], scaffold.clone()).unwrap());
        let canonical = Arc::new(ArtifactEntry::canonical(
            scaffold.module_interface().unwrap().clone(),
        ));
        let entries = vec![native.clone(), canonical];
        let available = inventory
            .admit_shared_with_demand(
                &inventory.empty_view(),
                entries.clone(),
                NativeArtifactDemand::ScopeInterfaces,
            )
            .unwrap();
        let early = inventory
            .admit_recovery_selection(
                &available,
                entries.clone(),
                &BTreeSet::from([crate::artifact_inventory::NativeGroupKey {
                    artifact: native.descriptor.id,
                    original_ordinal: 3,
                }]),
            )
            .unwrap();
        let selection = CertifiedSourceSelection::from_projected_originals(
            std::slice::from_ref(&scaffold),
            &InventoryOperation::new(Default::default()),
        )
        .unwrap();
        assert!(
            selection.selected_original_closure(&early).is_err(),
            "partial recovered graph custody cannot authorize an unavailable whole original"
        );
        assert!(
            matches!(
                inventory.bind_segment(
                    &available,
                    entries,
                    &selection,
                    &mut PackageInterfaceValidation::default(),
                ),
                Err(crate::CompileError::ArtifactInventory(error))
                    if matches!(error.failure,
                        crate::artifact_inventory::ArtifactInventoryFailure::MissingDependency {
                            dependency: crate::artifact_inventory::ArtifactDependency::NativeBinding {
                                dependent_ordinal: 11, generation: 4, ..
                            }, ..
                        })
            ),
            "whole physical completion still requires the delayed value carrier"
        );

        let probe_name = crate::artifacts::AUTHORED_PRODUCT_PROBE_MODULE;
        let probe = recovered_witness_fixtures(&[fixture_finalized_product(
            original_groups_fixture_with_interface(
                probe_name,
                vec![(3, vec![])],
                7,
                &BTreeMap::new(),
                b"Authored probe interface".to_vec(),
            ),
            [1; 32],
        )])
        .remove(0)
        .product;
        let authored = full_native_fixture("Authored", vec![(3, vec![])], 7);
        let backedge = PendingImportOwner::Source {
            owner: probe.owner().clone(),
            original_ordinal: 3,
            binder: testing::identity(probe_name, "entry_3"),
        };
        let invalid = full_native_fixture("Authored", vec![(3, vec![backedge])], 9);
        for (product, allowed) in [(authored, true), (invalid, false)] {
            assert_ne!(
                product.owner().skinny_iface_sha256,
                probe.owner().skinny_iface_sha256,
            );
            let products = recovered_witness_fixtures(&[product.clone(), probe.clone()])
                .into_iter()
                .map(|row| row.product)
                .collect::<Vec<_>>();
            let mut validation = PackageInterfaceValidation::default();
            let inventory = ArtifactInventory::default();
            let mut entries = Vec::new();
            for product in &products {
                entries.push(Arc::new(
                    ArtifactEntry::original_with_validation(
                        [1; 32],
                        product.clone(),
                        &mut validation,
                    )
                    .unwrap(),
                ));
                entries.push(Arc::new(ArtifactEntry::canonical(
                    product.module_interface().unwrap().clone(),
                )));
            }
            let available = inventory
                .admit_shared_with_demand(
                    &inventory.empty_view(),
                    entries.clone(),
                    NativeArtifactDemand::ScopeInterfaces,
                )
                .unwrap();
            let selection = CertifiedSourceSelection::from_projected_originals(
                &products,
                &validation.inventory,
            )
            .unwrap();
            let completed = inventory
                .bind_segment(&available, entries, &selection, &mut validation)
                .unwrap();
            let result = completed
                .source_selection()
                .selected_original_closure_excluding_module(
                    completed.physical_inputs().issued_artifacts(),
                    "fixture",
                    probe_name,
                );
            if allowed {
                let selected = result.unwrap();
                assert_eq!(selected.products(), &[product]);
                assert!(!selected.native_closure.entries().iter().any(|entry| entry
                    .descriptor
                    .owner
                    .module
                    == probe_name));
            } else {
                assert!(
                    result.is_err(),
                    "an authored backedge cannot re-admit its excluded transient probe"
                );
            }
        }
    }

    #[test]
    fn certified_group_bindings_preserve_exact_scopes_and_target_owner() {
        use crate::artifact_inventory::{ArtifactEntry, ArtifactInventory, NativeArtifactDemand};

        let original = full_native_fixture("BoundGroup", vec![(8, vec![]), (11, vec![])], 7);
        let other = full_native_fixture("OtherBoundGroup", vec![(12, vec![])], 7);
        let mut candidates = original
            .original_native()
            .unwrap()
            .groups
            .iter()
            .map(|group| group.admitted(original.original_native().unwrap()).unwrap())
            .chain(
                other
                    .original_native()
                    .unwrap()
                    .groups
                    .iter()
                    .map(|group| group.admitted(other.original_native().unwrap()).unwrap()),
            )
            .collect::<Vec<_>>();
        // An available but undemanded duplicate cannot compete with a solved row.
        candidates.push(candidates[1].clone());
        let issued = IssuedGroupCandidates::bind(
            nominal_pending_groups(&candidates).0.into(),
            &[original.clone(), other.clone()],
        )
        .unwrap();
        let own_observations = source_target_observations(&[(&original, 8)]);
        let both_observations = source_target_observations(&[(&original, 8), (&other, 12)]);
        let own_prepared = prepared_target_fixture(&own_observations);
        let both_prepared = prepared_target_fixture(&both_observations);
        let inventory = ArtifactInventory::default();
        let mut validation = PackageInterfaceValidation::default();
        let entries = [&original, &other]
            .into_iter()
            .map(|product| {
                Arc::new(
                    ArtifactEntry::original_with_validation(
                        [1; 32],
                        product.clone(),
                        &mut validation,
                    )
                    .unwrap(),
                )
            })
            .collect::<Vec<_>>();
        let available = inventory
            .admit_shared_with_demand(
                &inventory.empty_view(),
                entries.clone(),
                NativeArtifactDemand::ScopeInterfaces,
            )
            .unwrap();
        let selection = CertifiedSourceSelection::from_projected_originals(
            &[original.clone(), other.clone()],
            &validation.inventory,
        )
        .unwrap();
        let physical = inventory
            .bind_segment(&available, entries, &selection, &mut validation)
            .unwrap();
        let before = inventory.metrics().issued_scope_nodes;
        let observed = AuthenticatedTargetImports::issue(
            &own_prepared,
            &own_observations,
            &validation.inventory,
        )
        .unwrap();
        let admitted = inventory
            .select_native_target(
                physical.physical_inputs().physical_cohort().unwrap(),
                physical.source_selection(),
                observed,
                None,
                None,
                &[],
                &BTreeMap::new(),
                &mut validation,
            )
            .unwrap();
        let admitted_view = admitted.artifacts().clone();
        let owner = Arc::new(
            crate::declaration_context::certify_issued_artifact_view_groups_with_validation(
                admitted.artifacts(),
                &issued,
                None,
                &mut validation,
            )
            .unwrap(),
        );
        assert_eq!(owner.groups().len(), 1);
        assert_eq!(owner.groups()[0].origin(), ProductOrigin::Fresh);
        let (_, selected) = admitted.artifacts().selected_native_binding_rows();
        let binding = *selected.first().unwrap();
        assert_eq!(selected.len(), 1);
        assert!(std::ptr::eq(
            owner.get(binding).unwrap(),
            &owner.groups()[0]
        ));
        assert!(owner.matches_view(&admitted_view));
        let target = admitted.with_certified_groups(Arc::clone(&owner)).unwrap();
        let first_rows = target.resolve_sources().unwrap();
        let second_rows = target.resolve_sources().unwrap();
        assert!(std::ptr::eq(
            first_rows.group(binding).unwrap(),
            second_rows.group(binding).unwrap(),
        ));

        // Equal selected bindings do not establish the same acquisition owner.
        let observed = AuthenticatedTargetImports::issue(
            &own_prepared,
            &own_observations,
            &validation.inventory,
        )
        .unwrap();
        let foreign = inventory
            .select_native_target(
                physical.physical_inputs().physical_cohort().unwrap(),
                physical.source_selection(),
                observed,
                None,
                None,
                &[],
                &BTreeMap::new(),
                &mut validation,
            )
            .unwrap();
        let foreign_owner = Arc::new(
            crate::declaration_context::certify_issued_artifact_view_groups_with_validation(
                foreign.artifacts(),
                &issued,
                None,
                &mut validation,
            )
            .unwrap(),
        );
        assert_eq!(
            foreign.artifacts().selected_native_binding_rows().1,
            selected
        );
        assert!(!foreign_owner.matches_view(&admitted_view));
        assert!(foreign.with_certified_groups(Arc::clone(&owner)).is_err());

        // A different target selects existing occurrences without issuing scopes.
        let observed = AuthenticatedTargetImports::issue(
            &both_prepared,
            &both_observations,
            &validation.inventory,
        )
        .unwrap();
        let independent = inventory
            .select_native_target(
                physical.physical_inputs().physical_cohort().unwrap(),
                physical.source_selection(),
                observed,
                None,
                None,
                &[],
                &BTreeMap::new(),
                &mut validation,
            )
            .unwrap();
        let (_, independent_bindings) = independent.artifacts().selected_native_binding_rows();
        let independent_binding = *independent_bindings
            .iter()
            .find(|group| {
                group.binding.artifact() == binding.binding.artifact()
                    && group.original_ordinal == binding.original_ordinal
            })
            .unwrap();
        assert_eq!(independent_binding, binding);
        let independent_owner = Arc::new(
            crate::declaration_context::certify_issued_artifact_view_groups_with_validation(
                independent.artifacts(),
                &issued,
                None,
                &mut validation,
            )
            .unwrap(),
        );
        assert!(std::ptr::eq(
            owner.get(binding).unwrap().group(),
            independent_owner.get(binding).unwrap().group(),
        ));
        let other_binding = *independent_bindings
            .iter()
            .find(|group| group.binding.artifact() != binding.binding.artifact())
            .unwrap();
        assert!(independent_owner.get(other_binding).is_some());
        let observed = AuthenticatedTargetImports::issue(
            &own_prepared,
            &own_observations,
            &validation.inventory,
        )
        .unwrap();
        let narrowed = inventory
            .select_native_target(
                physical.physical_inputs().physical_cohort().unwrap(),
                physical.source_selection(),
                observed,
                None,
                None,
                &[],
                &BTreeMap::new(),
                &mut validation,
            )
            .unwrap();
        let narrowed_owner =
            crate::declaration_context::certify_issued_artifact_view_groups_with_validation(
                narrowed.artifacts(),
                &issued,
                None,
                &mut validation,
            )
            .unwrap();
        let narrowed = narrowed
            .with_certified_groups(Arc::new(narrowed_owner))
            .unwrap();
        let narrowed_rows = narrowed.resolve_sources().unwrap();
        assert!(narrowed_rows.group(independent_binding).is_ok());
        assert!(narrowed_rows.group(other_binding).is_err());

        assert_eq!(inventory.metrics().issued_scope_nodes, before);
        let joined = admitted_view
            .merge_fixture_selections(independent.artifacts())
            .unwrap();
        let joined_owner =
            crate::declaration_context::certify_issued_artifact_view_groups_with_validation(
                &joined,
                &issued,
                None,
                &mut validation,
            )
            .unwrap();
        assert_eq!(joined_owner.groups().len(), 2);
    }

    #[test]
    fn target_order_preserves_distinct_symbols_from_one_actual_group() {
        use crate::artifact_inventory::{ArtifactEntry, ArtifactInventory, NativeArtifactDemand};
        use tidepool_repr::execution_schema::{
            Group, HeapRhs, ModuleVersion, RawModuleProduct, ValueId,
        };

        let mut wire = testing::wire_program();
        let Group::NonRecursive(mut first) = wire.bindings.remove(0) else {
            unreachable!()
        };
        first.identity = testing::identity("OrderedExports", "first");
        first.binding.rhs = HeapRhs::Bytes(vec![1]);
        let mut second = first.clone();
        second.identity.occurrence = "second".into();
        second.binding.id = ValueId(1);
        second.binding.rhs = HeapRhs::Bytes(vec![2]);
        wire.bindings = vec![Group::Recursive(vec![first, second])];
        wire.expressions.nodes.clear();
        let group = testing::projected_group(wire, 7).unwrap();
        let symbols = group.binders().to_vec();
        let interface = vec![0x42];
        let bytes =
            tidepool_test_data::prepared_encode::encode_module_products(&[RawModuleProduct {
                unit: "fixture".into(),
                module: "OrderedExports".into(),
                interface: interface.clone(),
                groups: vec![group.clone()],
            }]);
        let owner = CachedHomeOwner {
            unit: "fixture".into(),
            module: "OrderedExports".into(),
            module_version: ModuleVersion([1; 32]),
            skinny_iface_sha256: sha(&interface),
            product_sha256: sha(&bytes),
        };
        let pending = PendingCertifiedGroup {
            owner: owner.clone(),
            origin: ProductOrigin::Fresh,
            group: Arc::new(group),
            imports: Arc::from([]),
        };
        let seal = encode_home_certification(&owner, &[pending], &BTreeMap::new()).unwrap();
        let package_bytes = crate::module_candidates::tests::package_imports_with_roots(
            "fixture",
            "OrderedExports",
            &interface,
            vec![],
        );
        let product = crate::recovery_artifacts::CertifiedRecoveryProduct::from_certification(
            owner,
            interface,
            bytes,
            package_bytes,
            seal,
        );
        let product = fixture_finalized_product(product, [2; 32]);
        let native = Arc::new(ArtifactEntry::original([2; 32], product).unwrap());
        let crate::artifact_inventory::ArtifactPayload::Original(product) = &native.payload else {
            unreachable!()
        };
        let inventory = ArtifactInventory::default();
        let physical = inventory
            .admit_shared_with_demand(
                &inventory.empty_view(),
                vec![native.clone()],
                NativeArtifactDemand::ScopeInterfaces,
            )
            .unwrap();
        let mut validation = PackageInterfaceValidation::default();
        let selection = CertifiedSourceSelection::from_projected_originals(
            std::slice::from_ref(product),
            &validation.inventory,
        )
        .unwrap();
        let fixed = inventory
            .bind_segment(&physical, vec![native.clone()], &selection, &mut validation)
            .unwrap();
        let selection = fixed.source_selection();
        let definitions = original_native_group_definitions(product, 7).unwrap();
        let contracts = definitions
            .export_contracts()
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
        assert_eq!(contracts.len(), 2);
        let before = inventory.metrics().issued_scope_nodes;
        let mut selected_values = Vec::new();
        for order in [[0usize, 1], [1, 0]] {
            let accepted = order
                .iter()
                .map(|index| {
                    let symbol = &symbols[*index];
                    let contract = contracts
                        .iter()
                        .find(|contract| contract.identity == symbol)
                        .unwrap();
                    AcceptedGlobal {
                        identity: symbol.clone(),
                        rep: contract.rep,
                        entry_signature: contract.entry_signature.cloned(),
                        required_evaluated: contract.evaluated,
                        owner: ReceiptImportOwner::Source {
                            unit: product.owner().unit.clone(),
                            module: product.owner().module.clone(),
                            module_version: Some(product.owner().module_version.clone()),
                            original_ordinal: 7,
                            binder: symbol.clone(),
                        },
                    }
                })
                .collect::<Vec<_>>();
            let prepared = prepared_target_fixture(&accepted);
            let observed =
                AuthenticatedTargetImports::issue(&prepared, &accepted, &validation.inventory)
                    .unwrap();
            let target = inventory
                .select_native_target(
                    fixed.physical_inputs().physical_cohort().unwrap(),
                    selection,
                    observed,
                    None,
                    None,
                    &[],
                    &BTreeMap::new(),
                    &mut validation,
                )
                .unwrap();
            let groups =
                crate::declaration_context::certify_selected_artifact_view_groups_with_validation(
                    target.artifacts(),
                    None,
                    &mut validation,
                )
                .unwrap();
            let target = target.with_certified_groups(Arc::new(groups)).unwrap();
            let resolved = target.resolve_sources().unwrap();
            assert_eq!(resolved.groups().len(), 1);
            let values = resolved
                .target_requirements()
                .iter()
                .map(|link| {
                    let SelectedNativeTargetImport::Source { binding, value } = link else {
                        panic!("actual Source slot")
                    };
                    (*binding, *value)
                })
                .collect::<Vec<_>>();
            assert_eq!(values.len(), 2);
            assert_eq!(values[0].0, values[1].0);
            assert_eq!(
                values.iter().map(|(_, value)| *value).collect::<Vec<_>>(),
                order
                    .map(|index| ValueId(u32::try_from(index).unwrap()))
                    .to_vec()
            );
            selected_values.push(values);
            assert_eq!(
                inventory.metrics().issued_scope_nodes,
                before,
                "target borrows completed occurrences"
            );
        }
        assert_eq!(
            selected_values[0].iter().rev().copied().collect::<Vec<_>>(),
            selected_values[1]
        );
    }

    #[test]
    fn selected_fresh_candidates_preserve_origin_and_full_native_bytes() {
        use crate::artifact_inventory::{ArtifactEntry, ArtifactInventory, NativeGroupKey};
        let original = full_native_fixture("FreshSubset", vec![(8, vec![]), (11, vec![])], 7);
        let candidates = original
            .original_native()
            .unwrap()
            .groups
            .iter()
            .map(|group| group.admitted(original.original_native().unwrap()).unwrap())
            .collect::<Vec<_>>();
        let mut validation = PackageInterfaceValidation::default();
        let entry = Arc::new(
            ArtifactEntry::original_with_validation([1; 32], original.clone(), &mut validation)
                .unwrap(),
        );
        let inventory = ArtifactInventory::default();
        let selected = inventory
            .admit_recovery_selection(
                &inventory.empty_view(),
                vec![entry.clone()],
                &BTreeSet::from([NativeGroupKey {
                    artifact: entry.descriptor.id,
                    original_ordinal: 8,
                }]),
            )
            .unwrap();
        let issued = IssuedGroupCandidates::bind(
            nominal_pending_groups(&candidates).0.into(),
            &[original.clone()],
        )
        .unwrap();
        let groups =
            crate::declaration_context::certify_issued_artifact_view_groups_with_validation(
                &selected,
                &issued,
                None,
                &mut validation,
            )
            .unwrap();
        assert_eq!(groups.len(), 1);
        assert_eq!(
            groups[0].origin(),
            original.original_native().unwrap().groups[0].origin()
        );
        assert_eq!(groups[0].group().original_ordinal(), 8);
        assert_eq!(original.original_native().unwrap().groups.len(), 2);
        let selected_entries = selected.entries();
        let retained_entry = selected_entries
            .iter()
            .find(|candidate| candidate.descriptor.id == entry.descriptor.id)
            .unwrap();
        let crate::artifact_inventory::ArtifactPayload::Original(retained) =
            &retained_entry.payload
        else {
            unreachable!()
        };
        assert_eq!(retained.owner(), original.owner());
        assert_eq!(retained.product_bytes(), original.product_bytes());
        assert_eq!(
            retained.certification_bytes(),
            original.certification_bytes()
        );
    }

    #[test]
    fn retained_core_selection_requires_exact_certified_original() {
        let packages = BTreeMap::new();
        let fixture = fixture_finalized_product(
            original_witness_fixture("Original", None, 7, &packages),
            [1; 32],
        );
        let original = recovered_witness_fixtures(std::slice::from_ref(&fixture))
            .remove(0)
            .product;
        let packet = CertifiedRetainedCoreProducts {
            products: BTreeMap::from([(
                (
                    original.owner().unit.clone(),
                    original.owner().module.clone(),
                ),
                original.clone(),
            )])
            .into(),
        };
        assert!(packet.contains_original(&original.clone()));
        assert!(!CertifiedRetainedCoreProducts::default().contains_original(&original));
        let recaptured = recovered_witness_fixtures(&[fixture]).remove(0).product;
        assert_eq!(recaptured.owner(), original.owner());
        assert_eq!(recaptured.product_bytes(), original.product_bytes());
        assert!(!packet.contains_original(&recaptured));
    }

    fn recovery_graph_original(
        source: &Path,
    ) -> crate::recovery_artifacts::CertifiedRecoveryProduct {
        let (graph, originals) = crate::execution_source::test_prepared_graph(source);
        let original = originals.into_iter().next().unwrap();
        let certificate =
            encode_home_certification(&original.owner, &[], &BTreeMap::new()).unwrap();
        let certificate = bind_home_execution_source(
            &certificate,
            &original.owner,
            graph.digest(),
            &mut PackageInterfaceValidation::default(),
        )
        .unwrap();
        fixture_finalized_product(
            crate::recovery_artifacts::CertifiedRecoveryProduct::from_certification(
                original.owner,
                original.interface,
                original.product,
                Vec::new(),
                certificate,
            ),
            [7; 32],
        )
        .with_execution_source(graph)
        .unwrap()
    }

    #[test]
    fn acquired_recovery_companions_reject_fresh_tampering_without_redecoding_retained_certificates(
    ) {
        let source = tempfile::tempdir().unwrap();
        let root = tempfile::tempdir().unwrap();
        let original = recovery_graph_original(source.path());
        let references = crate::recovery_artifacts::materialize_certified_products(
            root.path(),
            [7; 32],
            std::slice::from_ref(&original),
        )
        .unwrap();
        let reference = &references[0];
        let canonical = reference.module_interface.as_ref().unwrap();
        let paths = [
            &canonical.certificate_path,
            &canonical.core.as_ref().unwrap().path,
            &reference.execution_source.as_ref().unwrap().path,
        ];
        for path in paths {
            let path = root.path().join(path);
            let bytes = std::fs::read(&path).unwrap();
            let acquired =
                crate::recovery_artifacts::verify_materialized_ref(root.path(), reference).unwrap();
            let mut changed = bytes.clone();
            changed[0] ^= 1;
            std::fs::write(&path, changed).unwrap();
            assert!(
                crate::recovery_artifacts::verify_materialized_ref(root.path(), reference).is_err()
            );
            let before = HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get);
            let retained = certify_recovery_products_with_validation(
                vec![acquired],
                &mut PackageInterfaceValidation::default(),
            )
            .unwrap();
            assert_eq!(
                HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get),
                before
            );
            assert_eq!(retained[0].product.owner(), original.owner());
            assert_eq!(
                retained[0].product.execution_source().unwrap().digest(),
                original.execution_source().unwrap().digest()
            );
            assert_eq!(
                retained[0]
                    .product
                    .module_interface()
                    .unwrap()
                    .certificate_bytes(),
                original.module_interface().unwrap().certificate_bytes()
            );
            assert_eq!(
                retained[0].product.module_interface().unwrap().core_bytes(),
                original.module_interface().unwrap().core_bytes()
            );
            std::fs::write(&path, bytes).unwrap();
            assert!(
                crate::recovery_artifacts::verify_materialized_ref(root.path(), reference).is_ok()
            );
        }
    }

    #[test]
    fn recovery_native_cohort_refuses_a_late_original_with_inconsistent_group_headers() {
        let first = fixture_finalized_product(
            original_groups_fixture_with_interface(
                "First",
                vec![(7, vec![])],
                7,
                &BTreeMap::new(),
                b"first native interface".to_vec(),
            ),
            [7; 32],
        );
        let second = fixture_finalized_product(
            original_groups_fixture_with_interface(
                "Second",
                vec![(11, vec![])],
                9,
                &BTreeMap::new(),
                b"second native interface".to_vec(),
            ),
            [7; 32],
        );
        let mut fixture_validation = PackageInterfaceValidation::default();
        let originals = [first, second].map(|original| {
            finalize_original_for_inventory(original, &mut fixture_validation).unwrap()
        });
        let root = tempfile::tempdir().unwrap();
        let references = crate::recovery_artifacts::materialize_certified_products(
            root.path(),
            [7; 32],
            &originals,
        )
        .unwrap();
        let acquire = |reference: &crate::recovery_artifacts::RecoveryArtifactRef| {
            crate::recovery_artifacts::verify_materialized_ref(root.path(), reference).unwrap()
        };
        let before = HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get);
        let baseline = certify_recovery_products_with_validation(
            references.iter().map(acquire).collect(),
            &mut PackageInterfaceValidation::default(),
        )
        .unwrap();
        assert_eq!(
            HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get) - before,
            originals.len()
        );
        assert_eq!(baseline.len(), originals.len());
        for ((original, recovered), ordinal) in originals.iter().zip(&baseline).zip([7, 11]) {
            assert_eq!(recovered.product.owner(), original.owner());
            assert_eq!(
                recovered.product.original_native().unwrap().groups[0]
                    .group()
                    .original_ordinal(),
                ordinal
            );
        }

        // Tamper with stored input after valid publication. The changed HOME
        // remains canonical but disagrees with the unchanged TPMOD group.
        let bytes = std::fs::read(root.path().join(&references[1].certification_path)).unwrap();
        let mut witness = decode_home_witness(&bytes).unwrap();
        assert_eq!(witness.groups[0].0, 11);
        witness.groups[0].0 = 12;
        let bytes = encode_home_witness(&witness).unwrap();
        let mut tampered = references[1].clone();
        tampered.certification_sha256 = sha(&bytes);
        tampered.certification_path = PathBuf::from("artifacts")
            .join(format!("{}.owners", hex(&tampered.certification_sha256)));
        std::fs::write(root.path().join(&tampered.certification_path), bytes).unwrap();

        let acquired = vec![acquire(&references[0]), acquire(&tampered)];
        let before = HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get);
        assert!(matches!(
            certify_recovery_products_with_validation(
                acquired,
                &mut PackageInterfaceValidation::default()
            ),
            Err(CertificationError::Mismatch(
                "inherited original group/globals"
            ))
        ));
        assert_eq!(
            HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get),
            before
        );
        let after_refusal = certify_recovery_products_with_validation(
            references.iter().map(acquire).collect(),
            &mut PackageInterfaceValidation::default(),
        )
        .unwrap();
        assert_eq!(after_refusal.len(), baseline.len());
        for (recovered, prior) in after_refusal.iter().zip(&baseline) {
            assert!(recovered.product.same_durable_artifact(&prior.product));
            assert_eq!(
                recovered.product.original_native().unwrap().groups,
                prior.product.original_native().unwrap().groups
            );
        }
    }

    #[test]
    fn recovery_acquisition_and_native_certification_decode_each_home_once() {
        let mut originals = vec![
            fixture_finalized_product(
                original_groups_fixture_with_interface(
                    "First",
                    vec![(7, vec![])],
                    7,
                    &BTreeMap::new(),
                    b"first native interface".to_vec(),
                ),
                [7; 32],
            ),
            fixture_finalized_product(
                original_groups_fixture_with_interface(
                    "Second",
                    vec![(11, vec![])],
                    9,
                    &BTreeMap::new(),
                    b"second native interface".to_vec(),
                ),
                [7; 32],
            ),
        ];
        let source = tempfile::tempdir().unwrap();
        originals.push(recovery_graph_original(source.path()));
        let mut fixture_validation = PackageInterfaceValidation::default();
        let originals = originals
            .into_iter()
            .map(|original| {
                finalize_original_for_inventory(original, &mut fixture_validation).unwrap()
            })
            .collect::<Vec<_>>();
        let root = tempfile::tempdir().unwrap();
        let references = crate::recovery_artifacts::materialize_certified_products(
            root.path(),
            [7; 32],
            &originals,
        )
        .unwrap();
        let mut validation = PackageInterfaceValidation::default();
        let before = HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get);
        let acquired = references
            .iter()
            .map(|reference| {
                crate::recovery_artifacts::verify_materialized_ref_with_validation(
                    root.path(),
                    reference,
                    &mut validation,
                )
                .unwrap()
            })
            .collect();
        let recovered =
            certify_recovery_products_with_validation(acquired, &mut validation).unwrap();
        assert_eq!(
            HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get) - before,
            originals.len()
        );
        assert_eq!(validation.home_witness_validations, originals.len());
        for ((original, recovered), expected_ordinal) in
            originals
                .iter()
                .zip(&recovered)
                .zip([Some(7), Some(11), None])
        {
            assert_eq!(recovered.product.owner(), original.owner());
            assert_eq!(
                recovered.product.certification_bytes(),
                original.certification_bytes()
            );
            let groups = &recovered.product.original_native().unwrap().groups;
            assert_eq!(groups.len(), usize::from(expected_ordinal.is_some()));
            if let Some(ordinal) = expected_ordinal {
                assert_eq!(groups[0].group().original_ordinal(), ordinal);
            }
            assert_eq!(
                recovered
                    .product
                    .execution_source()
                    .map(|graph| graph.digest()),
                original.execution_source().map(|graph| graph.digest())
            );
            assert_eq!(recovered.requirements.owner, *original.owner());
            assert!(recovered.requirements.sources.is_empty());
            assert!(recovered.requirements.packages.is_empty());
        }
        let borrowed_before = HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get);
        for recovered in &recovered {
            original_native_requirements(&recovered.product).unwrap();
        }
        assert_eq!(
            HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get),
            borrowed_before
        );
    }

    #[cfg(unix)]
    proptest::proptest! {
        #![proptest_config(proptest::test_runner::Config { cases: 24, ..proptest::test_runner::Config::default() })]
        #[test]
        fn recovery_certificate_histories_preserve_retained_bytes_and_fresh_acquisition(
            history in proptest::collection::vec((0usize..5, 0u8..5), 1..16)
        ) {
            let root = tempfile::tempdir().unwrap();
            let external = tempfile::tempdir().unwrap();
            let package = external.path().join("External.hi");
            let package_bytes = b"external-package-interface";
            std::fs::write(&package, package_bytes).unwrap();
            let packages = BTreeMap::from([(("external-package".into(), "External".into()),
                PackageInterfaceWitness { selected_path: package.clone(), sha256: sha(package_bytes) })]);
            let original = fixture_finalized_product(original_groups_fixture_with_interface(
                "Retained", vec![(7, vec![PendingImportOwner::Package {
                    unit: "external-package".into(), module: "External".into(),
                    binder: SymbolIdentity { unit: "external-package".into(),
                        ..testing::identity("External", "entry") },
                    interface_digest: sha(package_bytes),
                }])], 9, &packages, b"retained-original-interface".to_vec(),
            ), [1; 32]);
            let original = finalize_original_for_inventory(
                original, &mut PackageInterfaceValidation::default(),
            ).unwrap();
            let references = crate::recovery_artifacts::materialize_certified_products(
                root.path(), [1; 32], std::slice::from_ref(&original),
            ).unwrap();
            let reference = &references[0];
            let acquired = crate::recovery_artifacts::verify_materialized_ref(root.path(), reference).unwrap();
            std::fs::remove_file(&package).unwrap();
            proptest::prop_assert!(crate::recovery_artifacts::verify_materialized_ref(
                root.path(), reference,
            ).is_ok(), "cold recovery owns package bytes independently of their selected origin");
            proptest::prop_assert!(certify_inherited_products(
                &[InheritedProductInput { artifact: &acquired }], &[],
            ).is_ok(), "retained package tokens survive selected-origin removal");
            assert_eq!(reference.package_interfaces.len(), 1);
            let paths = [root.path().join(&reference.certification_path),
                root.path().join(&reference.interface_path), root.path().join(&reference.product_path),
                root.path().join(&reference.package_imports_path),
                root.path().join(&reference.package_interfaces[0].path)];
            let originals = paths.iter().map(|path| std::fs::read(path).unwrap()).collect::<Vec<_>>();
            let controls = [(0, 1), (4, 2), (4, 0), (0, 0)];
            for (index, operation) in controls.into_iter().chain(history) {
                let path = &paths[index];
                if std::fs::symlink_metadata(path).is_ok() { std::fs::remove_file(path).unwrap(); }
                match operation {
                    0 => std::fs::write(path, &originals[index]).unwrap(),
                    1 => { let mut changed = originals[index].clone(); changed[0] ^= 1;
                        std::fs::write(path, changed).unwrap(); },
                    2 => {},
                    3 => { let target = external.path().join("redirect");
                        std::fs::write(&target, &originals[index]).unwrap();
                        std::os::unix::fs::symlink(target, path).unwrap(); },
                    4 => { let replacement = path.with_extension("replacement");
                        std::fs::write(&replacement, &originals[index]).unwrap();
                        std::fs::rename(replacement, path).unwrap(); },
                    _ => unreachable!(),
                }
                // Exact issued bytes and physical path kinds are the oracle;
                // it does not reuse production's digests or decoded certificate.
                let fresh_oracle = paths.iter().zip(&originals).all(|(path, bytes)| {
                    std::fs::read(path).is_ok_and(|actual| &actual == bytes)
                        && std::fs::symlink_metadata(path)
                            .is_ok_and(|metadata| !metadata.file_type().is_symlink())
                });
                let fresh = crate::recovery_artifacts::verify_materialized_ref(root.path(), reference);
                proptest::prop_assert_eq!(fresh.is_ok(), fresh_oracle, "operation={} file={}", operation, index);
                let before = HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get);
                let retained = certify_inherited_products(&[InheritedProductInput { artifact: &acquired }], &[]);
                proptest::prop_assert!(retained.is_ok(),
                    "retained tokens survive storage mutation: operation={} file={}", operation, index);
                proptest::prop_assert_eq!(HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get), before);
                proptest::prop_assert_eq!(acquired.certification_bytes(), original.certification_bytes());
                if let Ok(groups) = retained {
                    proptest::prop_assert_eq!(groups.len(), 1);
                    proptest::prop_assert_eq!(groups[0].group().original_ordinal(), 7);
                    proptest::prop_assert_eq!(groups[0].owner(), original.owner());
                }
                if let Ok(fresh) = fresh {
                    let before = HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get);
                    let recovered = certify_recovery_products_with_validation(vec![fresh],
                        &mut PackageInterfaceValidation::default()).unwrap();
                    proptest::prop_assert_eq!(recovered[0].product.owner(), original.owner());
                    proptest::prop_assert_eq!(HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get), before);
                }
            }
            for (path, bytes) in paths.iter().zip(&originals) {
                if std::fs::symlink_metadata(path).is_ok() { std::fs::remove_file(path).unwrap(); }
                std::fs::write(path, bytes).unwrap();
            }
            let fresh = crate::recovery_artifacts::verify_materialized_ref(root.path(), reference).unwrap();
            let before = HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get);
            let restored = certify_recovery_products_with_validation(vec![fresh],
                &mut PackageInterfaceValidation::default()).unwrap();
            proptest::prop_assert_eq!(restored[0].product.owner(), original.owner());
            proptest::prop_assert_eq!(HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get), before);
        }
    }

    #[test]
    fn candidate_original_issuer_matches_cold_recovery_and_refuses_seal_drift() {
        let fixture = fixture_finalized_product(
            original_groups_fixture(
                "CatalogNative",
                vec![(7, vec![]), (9001, vec![])],
                23,
                &BTreeMap::new(),
            ),
            [5; 32],
        );
        let fixture =
            finalize_original_for_inventory(fixture, &mut PackageInterfaceValidation::default())
                .unwrap();
        let cold = recovered_witness_fixtures(std::slice::from_ref(&fixture))
            .remove(0)
            .product;
        let candidate = |owner: CachedHomeOwner,
                         certification_bytes: Vec<u8>,
                         module_interface: CertifiedModuleInterface| {
            OriginalNativeCandidate {
                owner,
                product: crate::module_candidates::CandidateProduct::decode(
                    fixture.product_bytes().to_vec(),
                )
                .unwrap(),
                certification_bytes,
                module_interface,
                package_interfaces: fixture
                    .original_native()
                    .unwrap()
                    .package_interfaces()
                    .clone(),
                execution_source: None,
            }
        };
        let decoded_before = ORIGINAL_PRODUCT_DECODES.with(std::cell::Cell::get);
        let home_before = HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get);
        let carried = certify_candidate_original_with_validation(
            candidate(
                fixture.owner().clone(),
                fixture.certification_bytes().to_vec(),
                fixture.module_interface().unwrap().clone(),
            ),
            &mut PackageInterfaceValidation::default(),
        )
        .unwrap();
        assert_eq!(
            ORIGINAL_PRODUCT_DECODES.with(std::cell::Cell::get),
            decoded_before
        );
        assert_eq!(
            HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get) - home_before,
            1
        );
        assert_eq!(carried.certification_bytes(), fixture.certification_bytes());
        assert!(carried.same_durable_artifact(&cold));
        assert_eq!(
            carried.original_native().unwrap().groups,
            cold.original_native().unwrap().groups
        );
        assert_eq!(
            original_native_requirements(&carried).unwrap(),
            original_native_requirements(&cold).unwrap()
        );
        let mut wrong_owner = fixture.owner().clone();
        wrong_owner.module_version = ModuleVersion([24; 32]);
        assert!(certify_candidate_original_with_validation(
            candidate(
                wrong_owner,
                fixture.certification_bytes().to_vec(),
                fixture.module_interface().unwrap().clone()
            ),
            &mut PackageInterfaceValidation::default(),
        )
        .is_err());
        let changed_core =
            fixture_module_core(fixture.module_interface().unwrap(), b"other-core".to_vec());
        assert_eq!(changed_core.interface_bytes(), fixture.interface_bytes());
        assert!(certify_candidate_original_with_validation(
            candidate(
                fixture.owner().clone(),
                fixture.certification_bytes().to_vec(),
                changed_core
            ),
            &mut PackageInterfaceValidation::default(),
        )
        .is_err());
        let mut missing_graph = decode_home_witness(fixture.certification_bytes()).unwrap();
        missing_graph.execution_source_sha256 = Some([31; 32]);
        assert!(certify_candidate_original_with_validation(
            candidate(
                fixture.owner().clone(),
                encode_home_witness(&missing_graph).unwrap(),
                fixture.module_interface().unwrap().clone()
            ),
            &mut PackageInterfaceValidation::default(),
        )
        .is_err());
        let mut changed_seal = fixture.certification_bytes().to_vec();
        changed_seal.push(0);
        assert!(certify_candidate_original_with_validation(
            candidate(
                fixture.owner().clone(),
                changed_seal,
                fixture.module_interface().unwrap().clone()
            ),
            &mut PackageInterfaceValidation::default(),
        )
        .is_err());
    }

    #[test]
    fn original_native_witness_reuses_nonempty_cycle_and_checks_selected_closure() {
        let source = |owner: CachedHomeOwner| PendingImportOwner::Source {
            binder: testing::identity(&owner.module, "entry"),
            owner,
            original_ordinal: 7,
        };
        let packages = BTreeMap::new();
        let fixture = |module: &str, import| {
            original_groups_fixture_with_interface(
                module,
                vec![(7, vec![import])],
                7,
                &packages,
                format!("{module} interface").into_bytes(),
            )
        };
        let a = fixture("A", source(inherited_owner("B")));
        let b = fixture("B", source(a.owner().clone()));
        let a = fixture("A", source(b.owner().clone()));
        let a = fixture_finalized_product(a, [1; 32]);
        let b = fixture_finalized_product(b, [1; 32]);
        let before = ORIGINAL_PRODUCT_DECODES.with(std::cell::Cell::get);
        let recovered = recovered_witness_fixtures(&[a, b]);
        assert_eq!(
            ORIGINAL_PRODUCT_DECODES.with(std::cell::Cell::get) - before,
            2
        );
        let products = recovered
            .iter()
            .map(|original| &original.product)
            .collect::<Vec<_>>();
        let expected = products
            .iter()
            .map(|product| {
                (
                    certified_home_requirements(product.certification_bytes(), product.owner())
                        .unwrap(),
                    certified_native_requirements(product.certification_bytes(), product.owner())
                        .unwrap(),
                )
            })
            .collect::<Vec<_>>();
        let certificate_decodes = HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get);
        for (product, (sources, native)) in products.iter().zip(&expected) {
            assert_eq!(
                &original_home_requirements_with_validation(
                    product,
                    &mut PackageInterfaceValidation::default()
                )
                .unwrap(),
                sources
            );
            assert_eq!(&original_native_requirements(product).unwrap(), native);
            let entry =
                crate::artifact_inventory::ArtifactEntry::original([1; 32], (*product).clone())
                    .unwrap();
            assert_eq!(
                entry
                    .native_requirements
                    .values()
                    .flatten()
                    .cloned()
                    .collect::<BTreeSet<_>>(),
                native
                    .artifact_edges
                    .iter()
                    .cloned()
                    .collect::<BTreeSet<_>>()
            );
        }
        let groups = certify_owned_products_with_validation(
            &products,
            &[],
            &mut PackageInterfaceValidation::default(),
        )
        .unwrap();
        assert_eq!(groups.len(), 2);
        assert!(groups
            .iter()
            .all(|group| group.origin() == ProductOrigin::Cached));
        assert!(Arc::ptr_eq(
            &groups[0].group,
            &products[0].original_native().unwrap().groups[0].group
        ));
        assert!(certify_owned_products_with_validation(
            &products,
            &groups,
            &mut PackageInterfaceValidation::default()
        )
        .unwrap()
        .is_empty());
        assert!(certify_owned_products_with_validation(
            &[products[0]],
            &[],
            &mut PackageInterfaceValidation::default()
        )
        .is_err());
        assert!(certify_owned_products_with_validation(
            &[products[0], products[0]],
            &[],
            &mut PackageInterfaceValidation::default()
        )
        .is_err());
        assert_eq!(
            ORIGINAL_PRODUCT_DECODES.with(std::cell::Cell::get) - before,
            2,
            "reusing witnesses cannot decode native products again"
        );
        assert_eq!(
            HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get),
            certificate_decodes,
            "witness reuse and inventory admission cannot decode certificates again"
        );
        let duplicate = vec![groups[0].clone(), groups[0].clone()];
        assert!(matches!(
            certify_owned_products_with_validation(
                &[products[0]],
                &duplicate,
                &mut PackageInterfaceValidation::default()
            ),
            Err(CertificationError::Mismatch(
                "duplicate current original ordinal"
            ))
        ));
        let mut changed = groups.clone();
        changed[0].imports = vec![PendingImportOwner::Retained {
            identity: testing::identity("Value", "changed"),
            generation: 99,
        }]
        .into();
        assert!(matches!(
            certify_owned_products_with_validation(
                &products,
                &changed,
                &mut PackageInterfaceValidation::default()
            ),
            Err(CertificationError::Mismatch("shared original home groups"))
        ));
        println!("native witness original_decodes=2 reuse_decodes=0 nonempty_groups=2");
    }

    #[test]
    fn recovered_native_witness_preserves_distinct_original_versions() {
        let retained = |generation| PendingImportOwner::Retained {
            identity: testing::identity("Value", "live"),
            generation,
        };
        let old = original_witness_fixture("A", Some(retained(11)), 7, &BTreeMap::new());
        let new = original_witness_fixture("A", Some(retained(22)), 8, &BTreeMap::new());
        let recovered = recovered_witness_fixtures(&[
            fixture_finalized_product(old, [1; 32]),
            fixture_finalized_product(new, [1; 32]),
        ]);
        for (index, original) in recovered.iter().enumerate() {
            let groups = certify_owned_products_with_validation(
                &[&original.product],
                &[],
                &mut PackageInterfaceValidation::default(),
            )
            .unwrap();
            assert!(
                matches!(groups[0].imports()[0], PendingImportOwner::Retained { generation, .. } if generation == [11, 22][index])
            );
        }
        let products = recovered
            .iter()
            .map(|original| &original.product)
            .collect::<Vec<_>>();
        assert!(
            certify_owned_products_with_validation(
                &products,
                &[],
                &mut PackageInterfaceValidation::default()
            )
            .is_err(),
            "one selected context cannot combine different full versions of one owner"
        );
    }

    #[test]
    fn inherited_packages_reuse_issued_witness_and_charge_owned_selection() {
        let root = tempfile::tempdir().unwrap();
        let path = root.path().join("External.hi");
        std::fs::write(&path, [0x43]).unwrap();
        let packages = BTreeMap::from([(
            ("external-package".into(), "External".into()),
            PackageInterfaceWitness {
                selected_path: path,
                sha256: sha(&[0x43]),
            },
        )]);
        let fixture = fixture_finalized_product(
            original_witness_fixture(
                "Consumer",
                Some(PendingImportOwner::Package {
                    unit: "external-package".into(),
                    module: "External".into(),
                    binder: SymbolIdentity {
                        unit: "external-package".into(),
                        ..testing::identity("External", "entry")
                    },
                    interface_digest: sha(&[0x43]),
                }),
                7,
                &packages,
            ),
            [1; 32],
        );
        let issued = recovered_witness_fixtures(&[fixture]).remove(0).product;
        assert_eq!(
            issued.module_interface().unwrap().producer_sha256(),
            [1; 32]
        );
        assert!(issued.original_native().unwrap().matches_original(&issued));
        let legacy = crate::recovery_artifacts::CertifiedRecoveryProduct::from_certification(
            issued.owner().clone(),
            issued.interface_bytes().to_vec(),
            issued.product_bytes().to_vec(),
            issued.package_imports_bytes().to_vec(),
            issued.certification_bytes().to_vec(),
        );
        assert!(legacy.original_native().is_none());
        assert!(
            legacy
                .clone()
                .with_original_native(issued.original_native().unwrap().clone())
                .is_err(),
            "identical recaptured bytes cannot borrow another original's witness"
        );
        let mut legacy_validation = PackageInterfaceValidation::default();
        let before = HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get);
        let expected = inherited_package_witnesses_with_validation(
            std::slice::from_ref(&legacy),
            &mut legacy_validation,
        )
        .unwrap();
        assert_eq!(
            HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get),
            before + 1
        );
        assert_eq!(expected, packages);
        let legacy_spent = legacy_validation.inventory.work_usage().unwrap().0;
        let mut validation = PackageInterfaceValidation::default();
        let inventory = validation.inventory.clone();
        let before = HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get);
        let selected = inherited_package_witnesses_with_validation(
            std::slice::from_ref(&issued),
            &mut validation,
        )
        .unwrap();
        assert_eq!(selected, expected);
        let (owner, witness) = selected.iter().next().unwrap();
        check_segment_package_addition(owner, witness, &BTreeMap::new(), &selected).unwrap();
        assert!(matches!(
            check_segment_package_addition(owner, witness, &selected, &selected),
            Err(CertificationError::Mismatch(
                "item repeats an original package selection"
            ))
        ));
        let mut conflicting = witness.clone();
        conflicting.sha256[0] ^= 1;
        assert!(matches!(
            check_segment_package_addition(owner, &conflicting, &BTreeMap::new(), &selected),
            Err(CertificationError::Mismatch(
                "item replaces an inherited package selection"
            ))
        ));
        let mut another_path = witness.clone();
        another_path.selected_path = root.path().join("AnotherExternal.hi");
        assert!(
            check_segment_package_addition(owner, &another_path, &BTreeMap::new(), &selected,)
                .is_err()
        );
        assert_eq!(
            HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get),
            before
        );
        let spent = inventory.work_usage().unwrap().0;
        assert!(spent > 0 && spent < legacy_spent);
        let repeated = inherited_package_witnesses_with_validation(
            &[issued.clone(), issued.clone()],
            &mut validation,
        )
        .unwrap();
        assert_eq!(repeated, expected);
        assert_eq!(
            HOME_CERTIFICATION_DECODES.with(std::cell::Cell::get),
            before
        );
        assert!(
            inventory.work_usage().unwrap().0 > spent,
            "owned output copies stay charged"
        );
        assert_ne!(
            selected
                .values()
                .next()
                .unwrap()
                .selected_path
                .as_os_str()
                .as_encoded_bytes()
                .as_ptr(),
            repeated
                .values()
                .next()
                .unwrap()
                .selected_path
                .as_os_str()
                .as_encoded_bytes()
                .as_ptr()
        );
        let remaining = inventory.work_usage().unwrap().1;
        inventory.charge(remaining).unwrap();
        assert!(matches!(
            inherited_package_witnesses_with_validation(
                std::slice::from_ref(&issued),
                &mut validation,
            ),
            Err(CertificationError::Product(
                tidepool_repr::execution_schema::ParseError::LimitExceeded("work")
            ))
        ));
        assert_eq!(inventory.work_usage().unwrap().1, 0);
        assert_eq!(
            inherited_package_witnesses_with_validation(
                &[issued],
                &mut PackageInterfaceValidation::default(),
            )
            .unwrap(),
            expected
        );
        let mut wrong_owner = legacy.owner().clone();
        wrong_owner.module = "AnotherConsumer".into();
        let wrong_owner = crate::recovery_artifacts::CertifiedRecoveryProduct::from_certification(
            wrong_owner,
            legacy.interface_bytes().to_vec(),
            legacy.product_bytes().to_vec(),
            legacy.package_imports_bytes().to_vec(),
            legacy.certification_bytes().to_vec(),
        );
        assert!(matches!(
            inherited_package_witnesses_with_validation(
                &[wrong_owner],
                &mut PackageInterfaceValidation::default(),
            ),
            Err(CertificationError::Mismatch(
                "inherited package product owner"
            ))
        ));
        let mut changed = legacy.certification_bytes().to_vec();
        changed[0] ^= 1;
        let changed = crate::recovery_artifacts::CertifiedRecoveryProduct::from_certification(
            legacy.owner().clone(),
            legacy.interface_bytes().to_vec(),
            legacy.product_bytes().to_vec(),
            legacy.package_imports_bytes().to_vec(),
            changed,
        );
        assert!(inherited_package_witnesses_with_validation(
            &[changed],
            &mut PackageInterfaceValidation::default(),
        )
        .is_err());
    }

