    proptest::proptest! {
        #![proptest_config(original_native_index_property_config())]
        #[test]
        fn dictionary_typed_uniqueness_matches_full_wire_facts(
            seed in 0_u8..8,
            owner_kind in 0_u8..4,
            changed_field in 0_u8..12,
            signature_kind in 0_u8..4,
            identical in proptest::bool::ANY,
        ) {
            let mut left = dictionary_test_global();
            left.identity.occurrence = format!("value{seed}");
            left.identity.record_parent = (seed % 2 == 0).then(|| "Parent".into());
            left.entry_signature = match signature_kind {
                0 => None,
                kind => Some(Signature {
                    arguments: vec![RuntimeRep::LiftedRef, RuntimeRep::Word(64)],
                    results: match kind {
                        1 => ResultContract::Returns(vec![RuntimeRep::Int(64)]),
                        2 => ResultContract::NoSuccess,
                        _ => ResultContract::CallerResult,
                    },
                }),
            };
            left.owner = match owner_kind {
                0 => ReceiptImportOwner::Source {
                    unit: "home".into(), module: "Owner".into(),
                    module_version: Some(ModuleVersion([seed; 32])),
                    original_ordinal: seed.into(), binder: left.identity.clone(),
                },
                1 => ReceiptImportOwner::Retained { identity: left.identity.clone(), generation: seed.into() },
                2 => ReceiptImportOwner::Package { unit: "library".into(), module: "Owner".into(),
                    interface_digest: [seed; 32], binder: left.identity.clone() },
                _ => ReceiptImportOwner::OriginalBinding { unit: "home".into(), module: "Owner".into(),
                    interface: crate::artifact_inventory::ArtifactBinding {
                        artifact: crate::artifact_inventory::ArtifactId([seed; 32]),
                        selection: crate::artifact_inventory::ArtifactSelectionId([1; 32]),
                    },
                    original: crate::artifact_inventory::ArtifactBinding {
                        artifact: crate::artifact_inventory::ArtifactId([seed + 1; 32]),
                        selection: crate::artifact_inventory::ArtifactSelectionId([2; 32]),
                    }, binder: left.identity.clone() },
            };
            let mut right = left.clone();
            if !identical {
                match changed_field {
                    0 => right.identity.unit.push('x'),
                    1 => right.identity.module.push('x'),
                    2 => right.identity.namespace.push('x'),
                    3 => right.identity.occurrence.push('x'),
                    4 => right.identity.record_parent = Some("Different".into()),
                    5 => right.rep = RuntimeRep::UnliftedRef,
                    6 => right.required_evaluated = !right.required_evaluated,
                    7 => right.entry_signature = Some(Signature {
                        arguments: vec![RuntimeRep::Address], results: ResultContract::CallerResult,
                    }),
                    8 => match &mut right.owner {
                        ReceiptImportOwner::Source { original_ordinal, .. } => *original_ordinal += 1,
                        ReceiptImportOwner::Retained { generation, .. } => *generation += 1,
                        ReceiptImportOwner::Package { interface_digest, .. } => interface_digest[0] ^= 1,
                        ReceiptImportOwner::OriginalBinding { original, .. } => original.artifact.0[0] ^= 1,
                    },
                    9 => match &mut right.owner {
                        ReceiptImportOwner::Source { module_version, .. } => *module_version = None,
                        ReceiptImportOwner::Retained { identity, .. } => identity.module.push('x'),
                        ReceiptImportOwner::Package { module, .. }
                        | ReceiptImportOwner::OriginalBinding { module, .. } => module.push('x'),
                    },
                    10 => right.owner = ReceiptImportOwner::Retained { identity: right.identity.clone(), generation: 999 },
                    _ => match &mut right.owner {
                        ReceiptImportOwner::Source { binder, .. }
                        | ReceiptImportOwner::Package { binder, .. } => binder.occurrence.push('x'),
                        ReceiptImportOwner::OriginalBinding { original, .. } => original.selection.0[0] ^= 1,
                        ReceiptImportOwner::Retained { identity, .. } => identity.occurrence.push('x'),
                    },
                }
            }
            // Original bindings carry the outer symbol; the decoder derives
            // this binder rather than accepting an independent wire field.
            if let ReceiptImportOwner::OriginalBinding { binder, .. } = &mut right.owner {
                *binder = right.identity.clone();
            }
            let item = segment_item_receipt(&SegmentItemReceipt {
                globals: vec![left.clone()], packages: BTreeMap::new(), package_products: vec![],
            });
            let operation = InventoryOperation::new(Default::default());
            let decoded = decode_segment_item_with_operation(&receipt_bytes(&item), &operation).unwrap();
            proptest::prop_assert_eq!(&decoded.globals, &vec![left.clone()]);
            let decoded_right = accepted_global(&value_global(&right)).unwrap();
            proptest::prop_assert_eq!(&decoded_right, &right);
            proptest::prop_assert!(decoded.packages.is_empty());
            let wire_equal = receipt_bytes(&value_global(&left)) == receipt_bytes(&value_global(&right));
            let mut unique = BTreeSet::new();
            unique.insert(&left);
            let duplicate = !unique.insert(&right);
            proptest::prop_assert_eq!(duplicate, wire_equal);
            proptest::prop_assert_eq!(left == right, wire_equal);
        }
    }

    #[test]
    fn receipt_coordinates_share_dictionary_reconstruction_work_budget() {
        let package_global = |module: &str| {
            let mut global = dictionary_test_global();
            global.identity.module = module.into();
            global.identity.occurrence = format!("{module}-value");
            global.owner = ReceiptImportOwner::Package {
                unit: "library".into(),
                module: module.into(),
                interface_digest: sha(module.as_bytes()),
                binder: global.identity.clone(),
            };
            global
        };
        let first = package_global("Alpha");
        let second = package_global("Omega");
        let compact_dictionary = |globals: &[AcceptedGlobal]| {
            let full = value_array([
                value_text("product-facts"),
                value_text("dictionary"),
                value_array([]),
                value_array([]),
                value_array([]),
                value_array(globals.iter().map(value_global)),
                Value::Null,
                Value::Null,
            ]);
            let compact = compact_receipt_coordinates(&full);
            let header = product_receipt_payload(&compact).unwrap();
            (header[4].clone(), header[7].clone())
        };
        let (first_rows, first_coordinates) = compact_dictionary(std::slice::from_ref(&first));
        let (second_rows, second_coordinates) = compact_dictionary(std::slice::from_ref(&second));
        let decode = |rows: &Value, coordinates: &Value, max_work| {
            let mut coordinates = OwnerCoordinates::decode(coordinates).unwrap();
            let operation = InventoryOperation::new(InventoryDecodeLimits {
                max_work,
                ..InventoryDecodeLimits::default()
            });
            GlobalDictionary::decode_with_operation(rows, &mut coordinates, &operation)
        };

        const SEARCH_CAP: usize = 1 << 20;
        assert!(decode(&first_rows, &first_coordinates, SEARCH_CAP).is_ok());
        let mut low = 0;
        let mut high = SEARCH_CAP;
        while low + 1 < high {
            let middle = low + (high - low) / 2;
            match decode(&first_rows, &first_coordinates, middle) {
                Ok(_) => high = middle,
                Err(CertificationError::Product(
                    tidepool_repr::execution_schema::ParseError::LimitExceeded("work"),
                )) => low = middle,
                Err(error) => panic!("dictionary budget control failed: {error:?}"),
            }
        }
        let operation = InventoryOperation::new(InventoryDecodeLimits {
            max_work: high,
            ..InventoryDecodeLimits::default()
        });
        let mut first_coordinates = OwnerCoordinates::decode(&first_coordinates).unwrap();
        assert_eq!(
            GlobalDictionary::decode_with_operation(
                &first_rows,
                &mut first_coordinates,
                &operation,
            )
            .unwrap()
            .rows
            .len(),
            1
        );
        let mut decoded_second_coordinates = OwnerCoordinates::decode(&second_coordinates).unwrap();
        assert!(matches!(
            GlobalDictionary::decode_with_operation(
                &second_rows,
                &mut decoded_second_coordinates,
                &operation,
            ),
            Err(CertificationError::Product(
                tidepool_repr::execution_schema::ParseError::LimitExceeded("work")
            ))
        ));
        assert_eq!(
            decode(&second_rows, &second_coordinates, high)
                .unwrap()
                .rows
                .len(),
            1
        );
    }

    #[test]
    fn receipt_dictionary_references_share_expansion_work_budget() {
        let global = dictionary_test_global();
        let mut dictionary = test_dictionary(std::slice::from_ref(&global));
        let payload_bytes = dictionary.rows[0].1;
        let one_reference_work = std::mem::size_of::<AcceptedGlobal>()
            + payload_bytes
            + std::mem::size_of::<(usize, usize, usize)>();
        let operation = InventoryOperation::new(InventoryDecodeLimits {
            max_work: one_reference_work,
            ..InventoryDecodeLimits::default()
        });
        let reference = [Value::Integer(0.into())];
        assert_eq!(
            dictionary
                .resolve_with_operation(&reference, &operation)
                .unwrap(),
            vec![global.clone()]
        );
        assert!(matches!(
            dictionary.resolve_with_operation(&reference, &operation),
            Err(CertificationError::Product(
                tidepool_repr::execution_schema::ParseError::LimitExceeded("work")
            ))
        ));
        let fresh_operation = InventoryOperation::new(InventoryDecodeLimits {
            max_work: one_reference_work,
            ..InventoryDecodeLimits::default()
        });
        assert_eq!(
            dictionary
                .resolve_with_operation(&reference, &fresh_operation)
                .unwrap(),
            vec![global]
        );
    }

    #[test]
    fn world_recipe_receipt_preserves_exact_identity_and_refuses_invalid_framing() {
        let recipe = value_array([
            value_text("world-unavailable"),
            Value::Bytes(vec![7; 32]),
            Value::Bytes(vec![9; 32]),
            value_text("unsupported-source-recipe"),
        ]);
        let decode = |recipe: Value| {
            let mut value = dictionary_receipt(&empty_product_facts());
            receipt_payload_mut(&mut value)[6] = recipe;
            decode_receipt(&receipt_bytes(&value))
        };
        assert_eq!(
            decode(recipe.clone()).unwrap().source_recipe,
            WorkerExecutionSource::WorldUnavailable {
                base_world_identity: [7; 32],
                captured_source_domain: [9; 32],
            }
        );
        for (field, invalid) in [
            (1, Value::Bytes(vec![7; 31])),
            (2, Value::Bytes(vec![9; 33])),
            (1, value_text(hex(&[7; 32]))),
            (2, value_text(hex(&[9; 32]))),
            (3, value_text("no-fresh-originals")),
        ] {
            let mut invalid_recipe = recipe.clone();
            invalid_recipe.as_array_mut().unwrap()[field] = invalid;
            assert!(decode(invalid_recipe).is_err());
        }
        let mut missing = recipe.clone();
        missing.as_array_mut().unwrap().pop();
        assert!(decode(missing).is_err());
        let mut extra = recipe;
        extra.as_array_mut().unwrap().push(Value::Null);
        assert!(decode(extra).is_err());
    }

    #[test]
    fn exact_recipe_receipt_requires_owning_sidecar_and_preserves_issued_bytes() {
        let root = tempfile::tempdir().unwrap();
        let (graph, _) = crate::execution_source::test_graph(root.path());
        let mut value = dictionary_receipt(&empty_product_facts());
        let header = receipt_payload_mut(&mut value);
        header[6] = value_array([
            value_text("exact-available"),
            value_text(hex(&graph.digest())),
        ]);
        let encoded = receipt_bytes(&value);
        assert!(
            decode_receipt(&encoded).is_err(),
            "no ambient output directory"
        );
        assert!(
            decode_receipt_in(&encoded, Some(root.path())).is_err(),
            "missing advertised capsule"
        );
        let path = root.path().join("execution-source.cbor");
        std::fs::write(&path, graph.bytes()).unwrap();
        let receipt = decode_receipt_in(&encoded, Some(root.path())).unwrap();
        let WorkerExecutionSource::ExactAvailable { digest, bytes } = receipt.source_recipe else {
            panic!("available receipt must preserve its route")
        };
        assert_eq!(digest, graph.digest());
        assert_eq!(bytes.as_ref(), graph.bytes());
        let (_, observations) =
            crate::recovery_artifacts::PackageInterfaceValidation::capture_entry(
                root.path(),
                Arc::new(InventoryOperation::new(Default::default())),
                |validation| decode_receipt_with_validation(&encoded, root.path(), validation),
            )
            .unwrap();
        assert!(
            observations
                .entry_owned_paths()
                .contains(Path::new("execution-source.cbor")),
            "the actual receipt consumer must retain its graph read"
        );
        observations
            .verify_entry_inventory(
                root.path(),
                &BTreeMap::from([(PathBuf::from("execution-source.cbor"), hex(&graph.digest()))]),
            )
            .unwrap();
        assert!(observations
            .verify_entry_inventory(
                root.path(),
                &BTreeMap::from([(PathBuf::from("execution-source.cbor"), hex(&[42; 32]))])
            )
            .is_err());
        std::fs::write(&path, b"changed source recipe").unwrap();
        assert!(decode_receipt_in(&encoded, Some(root.path())).is_err());
        let header = receipt_payload_mut(&mut value);
        header[6] = value_array([value_text("exact-unavailable"), value_text("unknown")]);
        assert!(decode_receipt_in(&receipt_bytes(&value), Some(root.path())).is_err());
    }

